    }
  }
  def debugDimFlip(m: Array[Array[Long]]): Unit = if (!oj){
    REP(m(0).length) { j =>
      REP(m.length) { i =>
        System.err.print(m(i)(j))
        System.err.print(" ")
      }
      System.err.println()
    }
  }
  def debug(s: => String): Unit = DEBUG {
    System.err.println(s)
  }
  def debugL(num: => Long): Unit = DEBUG {
    System.err.println(num)
  }

  class InputReader(val stream: InputStream) {
    private val reader = new BufferedReader(new InputStreamReader(stream), 32768)
    private var tokenizer: StringTokenizer = _

    def next(): String = {
      while (tokenizer == null || !tokenizer.hasMoreTokens)
        tokenizer = new StringTokenizer(reader.readLine)
      tokenizer.nextToken
    }

    def nextInt(): Int = Integer.parseInt(next())
    def nextLong(): Long = java.lang.Long.parseLong(next())
    def nextChar(): Char = next().charAt(0)

    def ni(): Int = nextInt()
    def nl(): Long = nextLong()
    def nc(): Char = nextChar()
    def ns(): String = next()
    def ns(n: Int): Array[Char] = ns().toCharArray
    def na(n: Int, offset: Int = 0): Array[Int] = map(n)(_ => ni() + offset)
    def na2(n: Int, offset: Int = 0): (Array[Int], Array[Int]) = {
      val A1, A2 = Array.ofDim[Int](n)
      REP(n) { i =>
        A1(i) = ni() + offset
        A2(i) = ni() + offset
      }
      (A1, A2)
    }
    def nm(n: Int, m: Int): Array[Array[Int]] = {
      val A = Array.ofDim[Int](n, m)
      REP(n) { i =>
        REP(m) { j =>
          A(i)(j) = ni()
        }
      }
      A
    }
    def nal(n: Int): Array[Long] = map(n)(_ => nl())
    def nm_c(n: Int, m: Int): Array[Array[Char]] = map(n) (_ => ns(m))
  }

  def REP(n: Int, offset: Int = 0)(f: Int => Unit): Unit = {
    var i = offset
    val N = n + offset
    while(i < N) { f(i); i += 1 }
  }
  def REP_r(n: Int, offset: Int = 0)(f: Int => Unit): Unit = {
    var i = n - 1 + offset
    while(i >= offset) { f(i); i -= 1 }
  }
  def TO(from: Int, to: Int)(f: Int => Unit): Unit = {
    REP(to - from + 1, from) { i =>
      f(i)
    }
  }
  def map[@specialized A: ClassTag](n: Int, offset: Int = 0)(f: Int => A): Array[A] = {
    val res = Array.ofDim[A](n)
    REP(n)(i => res(i) = f(i + offset))
    res
  }

  def sumL(as: Array[Int]): Long = {
    var s = 0L
    REP(as.length)(i => s += as(i))
    s
  }
  def cumSum(as: Array[Int]): Array[Long] = {
    val cum = Array.ofDim[Long](as.length + 1)
    REP(as.length) { i =>
      cum(i + 1) = cum(i) + as(i)
    }
    cum
  }
}

class Main(out: java.io.PrintWriter, sc: Main.InputReader) {
  import sc._
  import Main._
  import java.util.Arrays.sort

  import scala.collection.mutable
  import math.{abs, max, min}
  import mutable.ArrayBuffer

  // toIntとか+7とかするならvalにしろ
  @inline private def MOD = 998244353

  def solve(): Unit = {
    val N = ni()
    val S = ns(3 * N)
    val byNum = Array.fill[java.util.TreeSet[Int]](N)(new java.util.TreeSet())
    val byColor = Array.ofDim[Int](3, N)
    val ix = Array.ofDim[Int](3)
    REP(N * 3) { i =>
      val t = S(i) match {
        case 'R' => 0
        case 'G' => 1
        case 'B' => 2
      }
      byNum(ix(t)).add(i)
      byColor(t)(ix(t)) = i
      ix(t) += 1
    }

    debug(byNum.mkString(" "))
    REP(3) { i =>
      debug(byColor(i))
    }

    def size(i: Int) = byNum(i).last - byNum(i).first

    val sz = Array.ofDim[Int](N)
    REP(N) { i =>
      sz(i) = size(i)
    }
    debug(sz)

    def check(t: Int, i: Int): Boolean = {
      val a = byColor(t)(i)
      val b = byColor(t)(i + 1)
      byNum(i).remove(a)
      byNum(i).add(b)
      byNum(i + 1).remove(b)
      byNum(i + 1).add(a)

      val r = sz(i) + sz(i + 1) == size(i) + size(i + 1)

      byNum(i).remove(b)
      byNum(i).add(a)
      byNum(i + 1).remove(a)
      byNum(i + 1).add(b)

      r
    }

    val flgByColor = Array.ofDim[Boolean](3, N)
    REP(3) { t =>
      REP(N - 1) { i =>
        flgByColor(t)(i) = check(t, i)
      }
    }
    val flg = Array.ofDim[Boolean](N)
    REP(N) { i =>
      var ok = true
      REP(3) { t =>
        ok &&= flgByColor(t)(i)
      }
      flg(i) = ok
    }

    REP(3) { i =>
      debug(flgByColor(i))
    }
    debug(flg)

    val comb = new Comb(N, MOD)
    var ans = comb.F(N)
    REP(3) { t =>
      var cnt = 1
      REP(N) { i =>
        if (flgByColor(t)(i)) {
          cnt += 1
          ans = ans * cnt % MOD
        } else {
          cnt = 1
        }
      }
    }

    var cnt = 1
    REP(N) { i =>
      if (flg(i)) {
        cnt += 1
        ans = ans * comb.rev(cnt) % MOD
      } else {
        cnt = 1
      }
    }

    out.println(ans)
  }

class Comb(NN: Int, MOD: Int) {
  def powMod(x: Int, n: Int, m: Int): Int = {
    def step(x: Long, n: Int, stack: Long): Long = {
      n match {
        case 0 => stack
        case _ => step(x * x % m, n / 2, if (n % 2 == 1) stack * x % m else stack)
      }
    }
    step(x, n, 1).toInt
  }

  val F = Array.ofDim[Long](NN + 1)
  F(0) = 1
  REP(NN) { i =>
    F(i + 1) = F(i) * (i + 1) % MOD
  }
  val I = Array.ofDim[Long](F.length)
  I(NN) = powMod(F(NN).toInt, MOD - 2, MOD)

  // x! = x(x-1)!
  // x!I(x!) ≡ (x-1)!I((x-1)!)
  // I((x-1)!) ≡ I(x!) * x   MODがでかいので(x-1)!はMODと素
  REP_r(NN) { i =>
    I(i) = I(i + 1) * (i + 1) % MOD
  }

  def comb(n: Int, k: Int): Long = {
    if (n < k) 0
    else F(n) * I(n - k) % MOD * I(k) % MOD
  }

  def rev(x: Int) = {
    I(x) * F(x - 1) % MOD
  }

  /**
    * nのグループからk回重複ありで選ぶ組み合わせ数
    * n - 1のしきりとkの○で考える
    */
  def H(n: Int, k: Int) = {
    comb(n + k - 1, k)
  }
}
}

