			}
			else if(b>=r) {
				br++;
				ans=(ans*(b+g))%mod;
				b--;
				r--;
			} else if(g>=r) {
				gr++;
				ans=(ans*g)%mod;
				g--;
				r--;
			}
		} else if(s[i]==1) {
			g++;
