				g--;
			}
			else if(b>=g) {
				bg++;
				ans=(ans*(b+r))%mod;
				b--;
				g--;
			} else if(r>=g) {
				rg++;
				ans=(ans*r)%mod;
				r--;
				g--;
			}
		} else {
			b++;
			if(gr>=b) {
				ans=(ans*(gr+rg))%mod;
				gr--;
				b--;
