priority_queue<pair<int,int> >Q;
//pair定义优先队列 先按first 再按second 自动排序 
int main()
{
	//freopen("hopeless.in","r",stdin);
	//freopen("hopeless.out","w",stdout);
	n=rd();
	for(int i=1;i<=n;i++)
		a[i]=rd();
	for(int i=1;i<=n;i++)
	{
		b[i]=rd();
		if(a[i]!=b[i]) Q.push(make_pair(b[i],i));
	}
	while(!Q.empty())
	{
		pair<int,int> now=Q.top();Q.pop();
		int i=now.snd;
		/*int pre=i-1,suf=i+1;
		if(pre==0) pre=n;
		if(suf==n+1) suf=1;
		int step=(b[i]-a[i])/(b[pre]+b[suf]);
		*/
		/*
		如果中间的数大于两边的数之和,那么中间那个数一定要被操作(设abc为i-1,i,i+1上的B值) 
		而且在b>a+c条件不被破坏时,如果不对b操作,那么a,c也不会被操作(操作之后为负数)
		只要b>a+c并且 Bi>Ai b就要一直减去(a+c)
		由于是一定要减 是必要的 所以也最小 

		b>a+c的条件就是在if(...)-1 那个地方判断的 也可以写成if(!step) 就是判断操作次数至少为1次 
		如果不能操作(操作就成负数)那就不能有解 如果可以操作 下取整操作次数是一定要做的 哪怕只有一次都要做
		做完之后 如果满足了Ai==Bi那最好 就ok啦
		但如果不满足 根据step的算法 就是再减一次就变成负数 这个时候b<a+c了
		就不一定需要操作 所以继续塞到队列里面等着有朝一日继续操作

		用优先队列呢，也是因为"在b>a+c条件不被破坏时,如果不对b操作,那么a,c也不会被操作(操作之后为负数)"
		如果不先对最大的那个数操作 那么后面也就没有办法操作 
		*/
		int pre=(i+n-2)%n+1,suf=i%n+1;
		int step=(b[i]-a[i])/(b[pre]+b[suf]);
		if(b[i]-b[pre]-b[suf]<a[i])
		{
			puts("-1");
			return 0;
		}
		ans+=step;
		b[i]-=step*(b[pre]+b[suf]);
		if(a[i]!=b[i]) Q.push(make_pair(b[i],i));
	}
	printf("%lld\n",ans);
    return 0;
}

