    ll cnt = N, ans = 1;
    for(auto e:v){
        if(e.first == 'R') qR.push(e.second);
        if(e.first == 'G') qG.push(e.second);
        if(e.first == 'B') qB.push(e.second);

        while(qR.size() && qG.size() && qB.size()) {
