            if(e.first != 'G') (ans *= qG.front()) %= MOD2;
            if(e.first != 'B') (ans *= qB.front()) %= MOD2;
            (ans *= cnt) %= MOD2;
            qR.front()--;
            qG.front()--;
            qB.front()--;
            cnt--;
            if(qR.front()==0) qR.pop();
            if(qG.front()==0) qG.pop();
            if(qB.front()==0) qB.pop();
        }
    }
    cout << ans << endl;

    return 0;
}

