const int MOD = 998244353;
const string uu = "RGB";
const int MAXN = 1e6 + 239;

vector<int> fact(MAXN);

int mul(int a, int b) {
	int res = a * b;
	return res % MOD;
}

int binpow(int a, int b) {
	int res = 1;
	while (b > 0) {
		if (b & 1) {
			res = mul(res, a);
		}
		a = mul(a, a);
		b >>= 1;
	}
	return res;
}

int divv(int a, int b) {
	return mul(a, binpow(b, MOD - 2));
}

int who(int a, int b, int c) {
	int ans = 0;
	if (a > b) {
		ans++;
	}
	if (a > c) {
		ans++;
	}
	return ans;
}

void init() {
	fact[0] = 1;
	for (int i = 1; i < MAXN; i++) {
		fact[i] = mul(fact[i - 1], i);
	}
}



signed main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	init();

	int n;
	cin >> n;
	string s;
	cin >> s;
	vector<vector<int>> pos(3);
	for (int i = 0; i < 3 * n; i++) {
		for (int j = 0; j < 3; j++) {
			if (s[i] == uu[j]) {
				pos[j].push_back(i);
			}
		}
	}
	vector<vector<int>> help(3, vector<int> (n));
	for (int i = 0; i < n; i++) {
		help[0][i] = who(pos[0][i], pos[1][i], pos[2][i]);
		help[1][i] = who(pos[1][i], pos[2][i], pos[0][i]);
		help[2][i] = who(pos[2][i], pos[0][i], pos[1][i]);
	}
	vector<vector<int>> bl(3);
	int ans = fact[n];
	for (int i = 0; i < 3; i++) {
		vector<int> o;
		for (int k = 0; k < 3; k++) {
			if (i != k) {
				o.push_back(k);
			}
		}
		for (int j = 0; j < n; j++) {
			int r = j;
			bl[i].push_back(j);
			while (r + 1 < n) {
				int ok = 1;
				ok &= (help[i][r] == help[i][r + 1]);
				ok &= (help[i][r] == who(pos[i][r], pos[o[0]][r + 1], pos[o[1]][r + 1]));
				ok &= (help[i][r] == who(pos[i][r + 1], pos[o[0]][r], pos[o[1]][r]));
				if (ok) {
					r++;
					bl[i].push_back(j);
				} else {
					break;
				}
			}
			int len = r - j + 1;
			ans = mul(ans, fact[len]);
			j = r;
		}
	}
	cerr << "pos " << endl;
	for (auto t : pos) {
		for (auto x : t) {
			cerr << x << ' ';
		}
		cerr << endl;
	}
	cerr << "help" << endl;
	for (auto t : help) {
		for (auto x : t) {
			cerr << x << ' ';
		}
		cerr << endl;
	}
	cerr << "bl " << endl;
	for (auto t : bl) {
		for (auto x : t) {
			cerr << x << ' ';
		}
		cerr << endl;
	}
	for (int i = 0; i < n; i++) {
		int r = i;
		while (r + 1 < n) {
			if (bl[0][r] == bl[i][r + 1] && bl[1][r] == bl[1][r + 1] && bl[2][r] == bl[2][r + 1]) {
				r++;
			} else {
				break;
			}
		}
		int len = r - i + 1;
		i = r;
		ans = divv(ans, fact[len]);
	}
	cout << ans << endl;
}

