constexpr lint MOD = 998244353;

int main()
{
    lint N;
    cin >> N;
    string S;
    cin >> S;
    lint b = 0, r = 0, g = 0, br = 0, rg = 0, gb = 0;
    lint ret = 1;
    for (auto c : S)
    {
        if (c == 'B' and rg) { ret = ret * rg % MOD; rg--; }
        else if (c == 'R' and gb) { ret = ret * gb % MOD; gb--; }
        else if (c == 'G' and br) { ret = ret * br % MOD; br--; }
        else
        {
            if (c == 'B') b++;
            if (c == 'R') r++;
            if (c == 'G') g++;
        }
        if (b and r) ret = ret * b * r % MOD, b--, r--, br++;
        if (r and g) ret = ret * r * g % MOD, r--, g--, rg++;
        if (g and b) ret = ret * g * b % MOD, g--, b--, gb++;
    }
    REP(i, N) ret = ret * (i + 1) % MOD;
    cout << ret << endl;
}

