#include <bits/stdc++.h>

using namespace std;

const int RIGHT  = 0;
const int CENTER = 1;
const int LEFT   = 2;

const int64_t MOD = 998244353;

int64_t F(int n) {
  static unordered_map<int, int64_t> cache;
  if (cache.find(n) != cache.end()) {
    return cache[n];
  }

  if (n == 1) {
    return cache[n] = 1;
  } else {
    return cache[n] = F(n - 1) * n % MOD;
  }
}

int main() {
  int64_t L;
  cin >> L;
  string S;
  cin >> S;

  unordered_map<char, int64_t> m;
  int64_t result = F(L);
  unordered_map<char, int64_t> count_left;
  count_left['R'] = 0;
  count_left['G'] = 0;
  count_left['B'] = 0;
  unordered_map<char, int64_t> count_center;
  count_center['R'] = 0;
  count_center['G'] = 0;
  count_center['B'] = 0;

  string RGB = "RGB";
  for (char c : S) {
    int current_pos = 0;
    for (int i = 0; i < 3; i++) {
      char other = RGB[i];
      if (c == other) continue;
      if (m[c] >= m[other]) current_pos++;
    }
    m[c]++;

    if (current_pos == LEFT) {
      count_left[c]++;
    } else if (current_pos == CENTER) {
      count_center[c]++;
    } else {
      for (int i = 0; i < 3; i++) {
	char k = RGB[i];
	if (count_left[k] > 1) {
	  result *= F(count_left[k]);
	  result %= MOD;
	}
	if (count_center[k] > 1) {
	  result *= F(count_center[k]);
	  result %= MOD;
	}
      }
      count_left['R'] = 0;
      count_left['G'] = 0;
      count_left['B'] = 0;
      count_center['R'] = 0;
      count_center['G'] = 0;
      count_center['B'] = 0;
    }
  }

  for (int i = 0; i < 3; i++) {
    char k = RGB[i];
    if (count_left[k] > 1) {
      result *= F(count_left[k]);
      result %= MOD;
    }
    if (count_center[k] > 1) {
      result *= F(count_center[k]);
      result %= MOD;
    }
  }
  cout << result << endl;

  return 0;
}

