/*-------------------------------------------------*/
long long mod_inv(long long a, long long mod = MOD) {
  a %= mod;
  if (__gcd(a, mod) != 1) return -1;
  long long b = mod, x = 1, y = 0;
  while (b > 0) {
    long long tmp = a / b;
    a -= tmp * b;
    swap(a, b);
    x -= tmp * y;
    swap(x, y);
  }
  x %= mod;
  if (x < 0) x += mod;
  return x;
}

int main() {
  cin.tie(0); ios::sync_with_stdio(false);
  // freopen("input.txt", "r", stdin);

  int n; string s; cin >> n >> s;
  map<char, int> mp;
  mp['R'] = 0; mp['G'] = 1; mp['B'] = 2;
  vector<pair<int, int> > len;
  int now = mp[s[0]], cnt = 1;
  FOR(i, 1, 3 * n) {
    if (mp[s[i]] != now) {
      len.emplace_back(now, cnt);
      cnt = 0;
    }
    now = mp[s[i]];
    ++cnt;
  }
  len.emplace_back(now, cnt);
  vector<vector<int> > idx(len.size(), vector<int>(3, 0));
  vector<multiset<int> > ball(3);
  map<tuple<int, int, int>, int> kaburu;
  REP(i, len.size()) {
    REP(j, len[i].second) ball[len[i].first].emplace(i);
    while (!ball[0].empty() && !ball[1].empty() && !ball[2].empty()) {
      vector<int> tmp(3);
      REP(j, 3) {
        tmp[j] = *ball[j].begin();
        ball[j].erase(ball[j].begin());
      }
      sort(ALL(tmp));
      // cout << tmp[0] << ' ' << tmp[1] << ' ' << tmp[2] << '\n';
      ++kaburu[make_tuple(tmp[0], tmp[1], tmp[2])];
      REP(j, 3) ++idx[tmp[j]][j];
    }
  }
  vector<long long> fact(n + 1);
  fact[0] = 1;
  FOR(i, 1, n + 1) fact[i] = fact[i - 1] * i % MOD;
  long long ans = 1;
  REP(i, len.size()) REP(j, 3) (ans *= fact[idx[i][j]]) %= MOD;
  for (auto tpl : kaburu) (ans *= mod_inv(fact[tpl.second])) %= MOD;
  cout << ans * fact[n] % MOD << '\n';
  return 0;
}

