int add(int x, int y) {
	int ret = (x + y);
	if (ret < 0) {
		return ret + mod;
	}
	else if (ret >= mod) {
		return ret -= mod;
	}
	return ret;
}
int mul(int x, int y) {
	return (ll)x*y%mod;
}
void solve() {
	int n;
	char s[N];
	scanf("%d", &n);
	scanf(" %s", s);
	int sz = n * 3;
	int num[3] = { 0,0,0 }, mid = 0;
	int ret = 1;
	for (int i = 0; i < sz; ++i) {
		int id;
		switch (s[i])
		{
		case 'R':
			id = 0;
			break;
		case 'B':
			id = 1;
			break;
		case 'G':
			id = 2;
			break;
		default:
			break;
		}
		//지금 begin을 결정해야되는데 조건이 뭐지?
		//완성본은 사실 더 이상 뭐 할게 없긴하다.
		//완성본은 mid 를 곱해주고 mid를 감소시켜주면 된다.
		//완성본인 경우는 어떻게 파악하지? num으로 파악하면 될듯한데...
		//완성본이 아닌 경우에는 사실 begin또는 mid가 된다. 
		//완성본이 아니라면 색은 많아봐야 2개의 색이 차있을 거다.
		int &numA = num[(id + 1) % 3], &numB = num[(id + 2) % 3];
		int &my = num[id];
		if (numA > 0 && numB > 0) {
			ret = mul(ret, mid);
			--numA, --numB;
			--mid;
		}
		else {
			int *g;
			if (numA == 0) {
				g = &num[(id + 2) % 3];
			}
			else {
				g = &num[(id + 1) % 3];
			}
			if (my >= *g) {
				++my;
			}
			else {
				ret = mul(ret, *g - my);
				++mid;
				++my;
			}
		}
	}
	for (int i = n; i; --i) {
		ret = mul(ret, i);
	}
	printf("%d\n", ret);
}
int main()
{
	//freopen("input.txt", "r", stdin);
	solve();
	return 0;
}

