void solve() {
  int res = 1;
  int x = 0, y = 0;
  int a = -1, b = -1;
  for (int i = 0; i < 3 * n; i++) {
    int c = (s[i] == 'R' ? 0 : (s[i] == 'G' ? 1 : 2));
    if (a == -1) {
      a = c;
      x = 1;
      continue;
    }
    if (a == c) {
      x++;
      continue;
    }
    if (b == -1) {
      b = c;
      y = 0;
    }
    if (b == c) {
      if (!x) {
        swap(a, b);
        x++;
        continue;
      }
      res = mul(res, x);
      x--;
      y++;
      continue;
    }
    if (!y) {
      b = c;
      if (!x) {
        swap(a, b);
        x++;
        continue;
      }
      res = mul(res, x);
      x--;
      y++;
      continue;
    }
    res = mul(res, y);
    y--;
  }
  for (int i = 1; i <= n; i++) {
    res = mul(res, i);
  }
  printf("%d\n", res);
}

