using ll = long long;
constexpr int mod = 998244353;

ll mod_pow(ll x, ll y) {
  if (y == 0) return 1;
  if (y % 2 == 0) return mod_pow(x * x % mod, y / 2);
  return x * mod_pow(x, y - 1) % mod;
}

int main() {
  int n;
  string s;
  cin >> n >> s;

  vector<ll> factrial(n + 1), inverse_factrial(n + 1);
  inverse_factrial[0] = factrial[0] = 1;
  for (int i = 1; i <= n; i++) {
    factrial[i] = factrial[i - 1] * i % mod;
    inverse_factrial[i] = mod_pow(factrial[i], mod - 2);
  }

  ll rs = 1;
  map<string, ll> m;
  queue<int> r, g, b;
  for (int i = 0, l = n; i < 3 * n; i++) {
    if (s[i] == 'R') {
      r.push(i);
    } else if (s[i] == 'G') {
      g.push(i);
    } else if (s[i] == 'B') {
      b.push(i);
    }
    if (r.size() == g.size() && g.size() == b.size()) {
      while (!r.empty()) {
        priority_queue<pair<int, char>> q;
        q.push({-r.front(), 'R'});
        q.push({-g.front(), 'G'});
        q.push({-b.front(), 'B'});
        r.pop();
        g.pop();
        b.pop();
        string t;
        while (!q.empty()) {
          t.push_back(q.top().second);
          q.pop();
        }
        m[t]++;
      }
      for (const auto& e : m) {
        // cerr << e.first << ' ' << e.second << endl;
        rs *=
            (factrial[e.second] * factrial[e.second] % mod) * factrial[l] % mod * inverse_factrial[l - e.second] % mod;
        rs %= mod;
        l -= e.second;
      }
      m.clear();
    }
  }
  cout << rs << endl;
}

