				dp[to][1] += dp[i][0] * com.fac[cnt - 1] * (cnt - 1);
			}
			dp[to][0] += dp[i][0] + dp[i][1];

			i = to - 1;
		}
		else {
			// 両方

			int cnt = to2 - i;

			if (2 < cnt) {
				dp[to2][0] += dp[i][1] * (com.fac[cnt - 2] * com.fac[cnt - 2] - 1);
				dp[to2][1] += dp[i][1] * com.fac[cnt - 2] * (cnt - 1) * com.fac[cnt - 2] * (cnt - 1);
