void initFacts()
{
	facts[0] = 0;
	facts[1] = 1;
	for (int i = 2 ; i < 100010 ; i++)
		facts[i] = (facts[i - 1] * i) % MOD;
}

void makeNumSet()
{
	for (int i = 0 ; i < n ; i++)
	{
		posSet[i].nums[0] = rPos[i];
		posSet[i].nums[1] = gPos[i];
		posSet[i].nums[2] = bPos[i];

		sort(posSet[i].nums, posSet[i].nums + 3);
	}
}

long long doChecks(bool checkLow, bool checkHigh)
{
	int l = 0;
	int h = 0;
	//三排的计数情况 
	int al, ah;
	int bl, bh;
	int cl, ch;

	long long ans = 1;
	long long sectionCount;

	while (l < n)
	{
		h = l;
		al = posSet[l].nums[0];
		ah = posSet[l].nums[0];

		bl = posSet[l].nums[1];
		bh = posSet[l].nums[1];

		cl = posSet[l].nums[2];
		ch = posSet[l].nums[2];

		while ((h + 1) < n)
		{
			if (checkLow && checkHigh)
			{
				if (posSet[h + 1].nums[0] > bl)
					break;

				if (posSet[h + 1].nums[1] > cl)
					break;
			}
			else if (checkLow)
			{
				if (posSet[h + 1].nums[0] > bl)
					break;
			}
			else if (checkHigh)
			{
				if (posSet[h + 1].nums[1] > cl)
					break;
			}

			ah = posSet[h + 1].nums[0];
			bh = posSet[h + 1].nums[1];
			ch = posSet[h + 1].nums[2];

			h++;			
		}

		if (h > l)
		{
			if ((isUsed[l] == false) && (isUsed[h] == false))
			{
				int len = h - l + 1;
				if (checkLow && checkHigh)
					sectionCount = facts[len] * facts[len] % MOD;
				else
					sectionCount = facts[len];
				ans = ans * sectionCount % MOD;

				for (int i = l ; i <= h ; i++)
					isUsed[i] = true;
			}
		}

		l = h + 1;
	}

	return ans;
}


int main()
{
	initFacts();

	scanf("%d\n", &n);
