			rPos[pR] = i;
			pR++;
		} else if (s[i] == 'G') {
			gPos[pG] = i;
			pG++;
		} else if (s[i] == 'B') {
			bPos[pB] = i;
			pB++;
		}
	}

	makeNumSet();

	memset(isUsed, false, sizeof(isUsed));

	long long ans = facts[n];

	long long sectionCount;
	sectionCount = doChecks(true, true);
	ans = ans * sectionCount;

	sectionCount = doChecks(true, false);
	ans = ans * sectionCount;

	sectionCount = doChecks(false, true);
	ans = ans * sectionCount;


	printf("%lld\n", ans);

	return 0;
}

