const long long MOD = 998244353;


vector<int> r, g, b;
map<int, int> dp[1 << 20];

int dfs(int bit, int c) {
    if (c < 0) return 0;

    if (bit == 0) {
        assert(c == 0);
        return c == 0;
    }
    if (dp[bit].count(c)) return dp[bit][c];

    int ans = 0;
    for (auto i : r) {
        if (bit >> i & 1) {
            for (auto j : g) {
                if (bit >> j & 1) {
                    for (auto k : b) {
                        if (bit >> k & 1) {
                            ans += dfs(bit - (1 << i) - (1 << j) - (1 << k), c - (max({i, j, k}) - min({i, j, k})));
                        }
                    }
                }

            }
        }
    }

    return dp[bit][c] = ans;
}


void solve(long long N, std::string S) {


    for (int i = 0; i < 3 * N; i++) {
        if (S[i] == 'R') { r.push_back(i); }
        if (S[i] == 'G') { g.push_back(i); }
        if (S[i] == 'B') { b.push_back(i); }

    }
    vector<int> C[3] = {r, g, b};
    auto H = [&](vector<int> &down, vector<int> &up, int d1, int mid, int d2) {
        ll d = upper_bound(down.begin(), down.end(), mid) - lower_bound(down.begin(), down.end(), d1);
        ll u = upper_bound(up.begin(), up.end(), d2) - lower_bound(up.begin(), up.end(), mid);
        return d * u % MOD;
    };

    ll mult = 1;
    for (int i = 0; i < N; i++) {
        pair<int, int> t[3] = {{r[i], 0},
                               {g[i], 1},
                               {b[i], 2}};
        sort(t, t + 3);
        ll v = H(C[t[0].second], C[t[2].second], t[0].first, t[1].first, t[2].first);
        mult *= v;
        mult %= MOD;
    }
    for(int i = 1 ; i <= N ; i++)
        mult *= i, mult %= MOD;
    cout << mult << endl;

}

int main() {
    long long N;
    scanf("%lld", &N);
    std::string S;
    std::cin >> S;
    solve(N, S);
    return 0;
}

