                if(tmp_third_R > 1) {
                    tmp_x *= tmp_third_R % MODNUM;
                    tmp_third_R--;
                }
            }
        }

        tmp_ans += tmp_x % MODNUM;
    }
    if(first_B > 0) {
        ll tmp_x = 1;

        ll tmp_second_G = second_G;
        ll tmp_third_R = third_R;
        ll tmp_second_R = second_R;
