		if (r[i] < b[i] && b[i] < g[i]) v[1].push_back(make_pair(r[i], make_pair(b[i], g[i])));
		if (g[i] < b[i] && b[i] < r[i]) v[2].push_back(make_pair(g[i], make_pair(b[i], r[i])));
		if (g[i] < r[i] && r[i] < b[i]) v[3].push_back(make_pair(g[i], make_pair(r[i], b[i])));
		if (b[i] < r[i] && r[i] < g[i]) v[4].push_back(make_pair(b[i], make_pair(r[i], g[i])));
		if (b[i] < g[i] && g[i] < r[i]) v[5].push_back(make_pair(b[i], make_pair(g[i], r[i])));
	}
	long long ans = 1;
	for (int i = 0; i < 6; i++) {
		vector<int> a, b, c;
		for (int j = 0; j < v[i].size(); j++) {
			a.push_back(v[i][j].first);
			b.push_back(v[i][j].second.first);
			c.push_back(v[i][j].second.second);
		}
		for (int j = 0; j < v[i].size(); j++) {
			int l = lower_bound(a.begin(), a.end(), b[j]) - a.begin();
			int r = lower_bound(c.begin(), c.end(), b[j]) - c.begin();
			r = v[i].size() - r;
			l -= j;
			r -= (v[i].size() -j-1);
			ans *= l;
			ans %= MOD;
			ans *= r;
			ans %= MOD;
			//printf("%d %d\n", l, r);
		}
	}
	for (int i = 1; i <= N; i++) {
		ans *= i;
		ans %= MOD;
	}
	printf("%lld\n", ans);
}

