bool bad(vector <int> &x, vector <int> &y, int i, int j){
    int last = max(r[i], g[i], b[i]) - min(r[i], g[i], b[i]) + max(r[j], g[j], b[j]) - min(r[j], g[j], b[j]);
    swap(x[i], x[j]);
    swap(y[i], y[j]);
    int cur = max(r[i], g[i], b[i]) - min(r[i], g[i], b[i]) + max(r[j], g[j], b[j]) - min(r[j], g[j], b[j]);
    swap(x[i], x[j]);
    swap(y[i], y[j]);
    return cur != last;
}

bool bad(vector <int> &x, int i, int j){
    int last = max(r[i], g[i], b[i]) - min(r[i], g[i], b[i]) + max(r[j], g[j], b[j]) - min(r[j], g[j], b[j]);
    swap(x[i], x[j]);
