class Solver {
 public:
  int n;
  string s;
  vector<int> a;
  Solver(LL n) : n(n), a(3 * n){};

  void solve() {
    string rgb = "RGB";
    cin >> s;
    while (s[0] != rgb[0]) {
      rotate(rgb.begin(), rgb.begin() + 1, rgb.end());
    }
    for (int i = 0; i < 3 * n; ++i) {
      a[i] = distance(rgb.begin(), find(rgb.begin(), rgb.end(), s[i]));
    }
    vector<int> cnt(3);
    Modint<> ans(1);
    for (int i = 0; i < 3 * n; ++i) {
      vector<int> cnt2(cnt);
      cnt2[a[i]]++;
      int min1 = *min_element(cnt.begin(), cnt.end());
      int min2 = *min_element(cnt2.begin(), cnt2.end());
      int max1 = *max_element(cnt.begin(), cnt.end());
      int max2 = *max_element(cnt2.begin(), cnt2.end());
      if (min1 == min2 && max1 == max2) {
        ans *= (max1 - cnt[a[i]]);
      } else if (min1 < min2) {
        sort(cnt.begin(), cnt.end());
        ans *= (cnt[1] - cnt2[a[i]] + 1);
      }
      cnt = cnt2;
    }
    for (int i = 1; i <= n; ++i) {
      ans *= i;
    }
    cout << ans << endl;
  }
};

