		A[x+y+z-min({x,y,z})-max({x,y,z})] = 2; 
	}
	long long int ans = Fac[N]; 
	int by1 = 0, by2 = 0, by3 = 0; 
	for(int i = 1; i <= N * 3; i++){
		if(A[i] == 1) by1 ++; 
		if(A[i] == 2){
			ans *= (long long) by1; ans %= P; 
			by1 --; by2 ++; 
		}
		if(A[i] == 3){
			ans *= (long long) by2; ans %= P; 
			by2 --; by3 ++; 
		}
	}
	cout << ans << endl; 
}

