//Combination Mod
class Combination_Mod {
public:
	vector<long long> fac,finv,inv;
	long long MOD;

	Combination_Mod(int N,long long mod) : fac(vector<long long>(N + 1)), finv(vector<long long>(N + 1)), inv(vector<long long>(N + 1)), MOD(mod) {
		fac[0] = fac[1] = finv[0] = finv[1] = inv[1] = 1;
		for (int i = 2; i <= N; ++i) {
			fac[i] = fac[i - 1] * i % MOD;
			inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
			finv[i] = finv[i - 1] * inv[i] % MOD;
		}
	}

	long long num(int n, int k) {
		return ((n < 0 || k < 0 || n < k) ? 0 : fac[n] * (finv[k] * finv[n - k] % MOD) % MOD);
	}
};


//Factorial_Mod
vector<long long> Factorial_Mod(long long N, long long mod) {
    vector<long long> res(N + 1, 1);
    for (long long i = 1; i <= N; ++i) res[i] = (res[i - 1] * i) % mod;
    return res;
}
int main() {
    int N; cin >> N;
    string S; cin >> S;
    S = S + ".";
    ll R = 0, G = 0, B = 0;

    if(S[0]=='R') R++;
    if(S[0]=='G') G++;
    if(S[0]=='B') B++;        

    vector<pair<char,ll>> v;
    for(int i = 1; i < 3*N+1; ++i){
        if(S[i]=='R') R++;
        if(S[i]=='G') G++;
        if(S[i]=='B') B++;
        if(S[i]==S[i-1]) continue;
        if(S[i-1]=='R'){
            v.push_back({'R',R});
            R = 0;
        }
        if(S[i-1]=='G'){
            v.push_back({'G',G});
            G = 0;
        }
        if(S[i-1]=='B'){
            v.push_back({'B',B});
            B = 0;
        }
    }
    ll qR = 0,qG = 0,qB = 0;
    ll cnt = N, ans = 1;
    Combination_Mod CM(N,MOD2);
    auto f = Factorial_Mod(N,MOD2);

    for(auto e:v){
        if(e.first == 'R') qR += e.second;
        if(e.first == 'G') qG += e.second;
        if(e.first == 'B') qB += e.second;

        while(qR && qG && qB) {
            ll t = min({qR,qG,qB});
            (ans *= f[t]) %= MOD2;
            (ans *= f[t]) %= MOD2;
            (ans *= f[t]) %= MOD2;
            (ans *= CM.num(cnt,t)) %= MOD2;
            qR -= t;
            qG -= t;
            qB -= t;
            cnt -= t;
        }
    }
    cout << ans*2 << endl;

    return 0;
}

