struct mll{
	static ll MOD;
	ll val;
	mll(ll v = 0): val(v % MOD){ if (val < 0) val += MOD; }
	mll operator - () const { return -val; }
	mll operator + (const mll &b) const { return val + b.val; }
	mll operator - (const mll &b) const { return val - b.val; }
	mll operator * (const mll &b) const { return val * b.val; }
	mll operator / (const mll &b) const { return mll(*this) /= b; }
	mll operator + (ll b) const { return *this + mll(b); }
	mll operator - (ll b) const { return *this - mll(b); }
	mll operator * (ll b) const { return *this * mll(b); }
	friend mll operator + (ll a, const mll &b) { return b + a; }
	friend mll operator - (ll a, const mll &b) { return -b + a; }
	friend mll operator * (ll a, const mll &b) { return b * a; }
	mll &operator += (const mll &b) { val=(val+b.val)%MOD; return *this; }
	mll &operator -= (const mll &b) { val=(val+MOD-b.val)%MOD; return *this; }
	mll &operator *= (const mll &b) { val=(val*b.val)%MOD; return *this; }
	mll &operator /= (const mll &b) {
		ll c=b.val, d=MOD, u=1, v=0;
		while (d){
			ll t = c / d;
			c -= t * d; swap(c, d);
			u -= t * v; swap(u, v);
		}
		val = val * u % MOD;
		if (val < 0) val += MOD;
		return *this;
	}
	mll &operator += (ll b) { return *this += mll(b); }
	mll &operator -= (ll b) { return *this -= mll(b); }
	mll &operator *= (ll b) { return *this *= mll(b); }
	mll &operator /= (ll b) { return *this /= mll(b); }
	bool operator == (const mll &b) { return val == b.val; }
	bool operator != (const mll &b) { return val != b.val; }
	bool operator == (ll b) { return *this == mll(b); }
	bool operator != (ll b) { return *this != mll(b); }
	friend bool operator == (ll a, const mll &b) { return mll(a) == b.val; }
	friend bool operator != (ll a, const mll &b) { return mll(a) != b.val; }
	friend ostream &operator << (ostream &os, const mll &a) { return os << a.val; }
	friend istream &operator >> (istream &is, mll &a) { return is >> a.val; }
	static mll Combination(ll a, ll b){
		chmin(b, a-b);
		if (b<0) return mll(0);
		mll c = 1;
		REP(i, b) c *= a-i;
		REP(i, b) c /= i+1;
		return c;
	}
};
ll mll::MOD = 998244353LL;// (ll)(1e9 + 7);



void solve()
{
	ll N;
	string S;
	cin >> N >> S;

	vll ballNum(3, 0);

	mll ans = 1;
	REP(i, 3*N){
		vll sortedIdx ={0,1,2};
		std::sort(sortedIdx.begin(), sortedIdx.end(),
			[&](ll &a, ll &b){ return ballNum[a] > ballNum[b]; }
		);
		vll rank(3);
		REP(i, 3) {
			ll idx = sortedIdx[i];
			rank[idx] = i;
			if (i == 0) continue;
			ll preIdx = sortedIdx[i-1];
			if (ballNum[idx] == ballNum[preIdx]){
				rank[idx] = rank[preIdx];
			}
		}

		char c = S[i];
		ll idx;
		switch (c){
		case 'R': idx = 0; break;
		case 'G': idx = 1; break;
		case 'B': idx = 2; break;
		default: break;
		}

		switch(rank[idx]){
		case 0://一番多いボール
			ans *= (N - ballNum[sortedIdx[0]]);
			break;
		case 1:
			ans *= (ballNum[sortedIdx[0]] - ballNum[sortedIdx[1]]);
			break;
		case 2:
			ans *= (ballNum[sortedIdx[1]] - ballNum[sortedIdx[2]]);
			break;
		default:break;
		}

		ballNum[idx]++;
	}

	cout << ans << '\n';
}

int main(){
	solve();
	return 0;
}

