                ans = 1ll * ans * (x[2] - x[1]) % mod;
            }
        }
        for (int i = 1; i <= n; i++) //A[n,n]
            ans = 1ll * ans * i % mod;
        printf("%d\n", ans);
    }
    return 0;
}

