constexpr int MOD = 998244353;

long long power(long long x, long long n, long long mod = MOD) {
    if (n == 0) return 1;
    if (n % 2 == 0) return power(x * x % mod, n/2, mod);
    else return x * power(x, n-1, mod) % mod;
}

void solve() {
    int n;
    string s;
    cin >> n >> s;

    VLL kai(n+1);
    kai[0] = 1;
    REP(i,1,n+1) kai[i] = (kai[i-1] * i) % MOD;

    priority_queue<int> r,g,b;
    REP(i,0,3*n) {
        if (s[i] == 'R') r.push(-i);
        if (s[i] == 'G') g.push(-i);
        if (s[i] == 'B') b.push(-i);
    }
    LL mind = 0;
    VI role(n*3);
    REP(i,0,n) {
        mind += max({r.top(), g.top(), b.top()}) - min({r.top(), g.top(), b.top()});
        VI a = {r.top(), g.top(), b.top()};
        sort(all(a));
        REP(i,0,3) {
            role[-a[i]] = i;
        }
        r.pop(); g.pop(); b.pop();
    }
    int c = 1;
    VI cs(n+1);
    REP(i,1,3*n) {
        if (s[i] != s[i-1]) {
            cs[c]++;
            c = 1;
            continue;
        }
        if (role[i] != role[i-1]) {
            cs[c]++;
            c = 1;
            continue;
        }
        ++c;
    }
    cs[c]++;
    dump(mind);
    LL ans = kai[n];
    LL cnt = 0;
    REP(i,2,n+1) {
        if (cs[i] == 0) continue;
        ans = ((ans * power(kai[i], cs[i])) % MOD);
        cnt += cs[i] * i;
    }
    if (cnt == 3 * n) {
        cout << power(kai[n], n) << endl;
        return;
    }
    cout << ans << endl;
}

int main() {
    solve();

    return 0;
}

