void solve(istream &cin = std::cin, ostream &cout = std::cout)
{
	int n;

	cin >> n;

	string s;

	cin >> s;

	string rgb = "RGB";

	vector<int> prf(3);

	ll ans = 1;

	for (auto it : s)
	{
		prf[rgb.find(it)]++;

		if (*min_element(prf.begin(), prf.end()) > 0)
		{
			int mid = *max_element(prf.begin(), prf.end()) ^*min_element(prf.begin(), prf.end());

			for (auto item : prf)
				mid ^= item;

			ans *= mid;
			ans %= mod;

			for (auto &m : prf)
				m--;
		}
		else
		{
			bool mx = true;

			prf[rgb.find(it)]--;

			for (auto item : prf)
				mx &= item <= prf[rgb.find(it)];

			if (!mx)
			{
				int mid = *max_element(prf.begin(), prf.end()) ^*min_element(prf.begin(), prf.end());

				for (auto item : prf)
					mid ^= item;

				ans *= *max_element(prf.begin(), prf.end()) - mid;
				ans %= mod;
			}

			prf[rgb.find(it)]++;
		}
	}

	cerr << ans << endl;

	for (int i = 1; i <= n; i++)
	{
		ans *= i;
		ans %= mod;
	}

	cout << ans << endl;
}


