		else if (S[r] == 'B') {
			B = true;
			cB++;
		}
		if (cR>0&&cG>0&&cB>0) {
			if (r < 3 * N - 1 && S[r + 1] == S[r]) {
				r++;
				continue;
			}
			ans *= fac[cG] % MOD*fac[cB] % MOD;
			ans %= MOD;
