            vector<ll> up_ms(cur_mas.size());
            for (int j = 0; j < cur_mas.size(); ++j) {
                ll low = lower_bound(all(g), b[j]) - g.begin() - j;
                low_ms[j] = low;
            }
            for (int j = int(cur_mas.size()) - 1; j >= 0; --j) {
                ll up = r.end() - upper_bound(all(r), b[j]) - (int(cur_mas.size()) - 1 - j);
                up_ms[j] = up;
            }

            for (int j = 0; j < cur_mas.size(); ++j) {
                ans *= low_ms[j] * up_ms[j];
                ans %= MOD;
            }
        }
    }

    cout << (ans * fac(n)) % MOD;

    return 0;
}

