inline ll read()
{
	ll x=0; char c=getchar(),f=1;
	for(;c<'0'||'9'<c;c=getchar())if(c=='-')f=-1;
	for(;'0'<=c&&c<='9';c=getchar())x=x*10+c-'0';
	return x*f;
}
inline void write(ll x)
{
	static char buf[20];
	int len=0;
	if(x<0)putchar('-'),x=-x;
	for(;x;x/=10)buf[len++]=x%10+'0';
	if(!len)putchar('0');
	else while(len)putchar(buf[--len]);
}
inline void writesp(ll x){write(x); putchar(' ');}
inline void writeln(ll x){write(x); putchar('\n');}
char s[3*maxn];
int n;
int main()
{
	n=read();
	scanf("%s",s);
	int cntr=0,cntg=0,cntb=0;
	ll ans=1;
	for(int i=0;i<3*n;i++){
		int A=cntr,B=cntg,C=cntb;
		if(A<B)std::swap(A,B);
		if(A<C)std::swap(A,C);
		if(B<C)std::swap(B,C);
		if(s[i]=='R'){
			if(cntr==A)ans=ans*(n-A)%mod;
			else if(cntr==B)ans=ans*(A-B)%mod;
			else ans=ans*(B-C)%mod;
			++cntr;
		}
		else if(s[i]=='G'){
			if(cntg==A)ans=ans*(n-A)%mod;
			else if(cntg==B)ans=ans*(A-B)%mod;
			else ans=ans*(B-C)%mod;
			++cntg;
		}
		else if(s[i]=='B'){
			if(cntb==A)ans=ans*(n-A)%mod;
			else if(cntb==B)ans=ans*(A-B)%mod;
			else ans=ans*(B-C)%mod;
			++cntb;
		}
	}
	writeln(ans);
	return 0;
}

