    ios::sync_with_stdio(false); cin.tie(nullptr);
    int N; cin >> N;
    string S; cin >> S;

    mint ans = 1;
    rep(i,N) ans *= (i+1);
    ll R = 0, G = 0, B = 0, l = 0, val = 0;
    vector<mint> A(N);
    LazySegmentTree<mint> seg(A);
    int p = 0; int q = 0;
    rep(i,3*N) {
        if (S[i]=='R') {
            ++R;
            if (R > G && R > B) ++l;
            else if (R <= G && R <= B) {
                ans *= seg.get(p,q);
                ++p;
                seg.update(p,q,-1);
                --l;
            }
            else {
                seg.update(q,q+1,l);
                ++q;
            }
        } else if (S[i]=='G') {
            G++;
            if (G > B && G > R) ++l;
            else if (G <= B && G <= R) {
                ans *= seg.get(p,q);
                ++p;
                seg.update(p,q,-1);
                --l;
            }
            else {
                seg.update(q,q+1,l);
                ++q;
            }
        } else if (S[i]=='B') {
            B++;
            if (B > R && B > G) ++l;
            else if (B <= R && B <= G) {
                ans *= seg.get(p,q);
                ++p;
                seg.update(p,q,-1);
                --l;
            }
            else {
                seg.update(q,q+1,l);
                ++q;
            }
        }
    }

    cout << ans.a << ln;
}

