                dp[R][i] = 1;
            } else if (S[i] == 'G') {
                dp[G][i] = 1;
            } else if (S[i] == 'B') {
                dp[B][i] = 1;
            }
            continue;
        }

        assert(1 <= i && i < MAX_N);
        for (int j = 0; j < 8; ++j) {
            dp[j][i] = dp[j][i - 1];
        }

        if (S[i] == 'R') {
            if (dp[GB][i - 1] > 0) {
                pat = (pat * dp[GB][i - 1]) % mod;
                dp[GB][i]--;
            } else if (dp[B][i - 1] > 0) {
                pat = (pat * dp[B][i - 1]) % mod;
                dp[B][i]--;
                dp[RB][i]++;
            } else if (dp[G][i - 1] > 0) {
                pat = (pat * dp[G][i - 1]) % mod;
                dp[G][i]--;
                dp[RG][i]++;
            } else {
                dp[R][i]++;
            }
        } else if (S[i] == 'G') {
            if (dp[RB][i - 1] > 0) {
                pat = (pat * dp[RB][i - 1]) % mod;
                dp[RB][i]--;
            } else if (dp[B][i - 1] > 0) {
                pat = (pat * dp[B][i - 1]) % mod;
                dp[B][i]--;
                dp[GB][i]++;
            } else if (dp[R][i - 1] > 0) {
                pat = (pat * dp[R][i - 1]) % mod;
                dp[R][i]--;
                dp[RG][i]++;
            } else {
                dp[G][i]++;
            }
        } else if (S[i] == 'B') {
            if (dp[RG][i - 1] > 0) {
                pat = (pat * dp[RG][i - 1]) % mod;
                dp[RG][i]--;
            } else if (dp[R][i - 1] > 0) {
                pat = (pat * dp[R][i - 1]) % mod;
                dp[R][i]--;
                dp[RB][i]++;
            } else if (dp[G][i - 1] > 0) {
                pat = (pat * dp[G][i - 1]) % mod;
                dp[G][i]--;
                dp[GB][i]++;
            } else {
                dp[B][i]++;
            }
        }
    }
    return pat;
}

