int f[100050],x[100050],y[100050],m;
deque<int> p[3];
struct node{
	int a,b,c;
	node(){}
	node(int a,int b,int c):a(a),b(b),c(c){}
};
vector<node> a[6];
int work(){
	int i,ans=1,l;
	for(i=m;i;--i){
		l=upper_bound(y+1,y+m+1,x[i])-y;
		ans=(ll)ans*(i-l+1)%mod;
	}
	return ans;
}
inline int solve(vector<node> &a){
	int i,res=1;
	m=a.size();
	for(i=0;i<a.size();++i){x[i+1]=a[i].b;y[i+1]=a[i].c;}
	res=work();
	for(i=0;i<a.size();++i){x[i+1]=a[i].a;y[i+1]=a[i].b;}
	res=(ll)res*work()%mod;
	return res;
}
int main(){
	int n,i,ans=1;
	scanf("%d%s",&n,s+1);
	for(i=1;i<=n*3;++i)if(s[i]=='R')p[0].push_back(i);
	else if(s[i]=='G')p[1].push_back(i);
	else p[2].push_back(i);
	for(f[1]=1,i=2;i<=n;++i)f[i]=(ll)f[i-1]*i%mod;
	for(i=1;i<=n;++i){
		if(p[0][0]<p[1][0])if(p[0][0]<p[2][0])if(p[1][0]<p[2][0])a[0].push_back(node(p[0][0],p[1][0],p[2][0]));
		else a[1].push_back(node(p[0][0],p[2][0],p[1][0]));
		else a[4].push_back(node(p[2][0],p[0][0],p[1][0]));
		else if(p[1][0]<p[2][0])if(p[0][0]<p[2][0])a[2].push_back(node(p[1][0],p[0][0],p[2][0]));
		else a[3].push_back(node(p[1][0],p[2][0],p[0][0]));
		else a[5].push_back(node(p[2][0],p[1][0],p[0][0]));
		p[0].pop_front();p[1].pop_front();p[2].pop_front();
	}
	for(i=0;i<6;++i)ans=(ll)ans*solve(a[i])%mod;
	printf("%d\n",(ll)ans*f[n]%mod);
	return 0;
}

