vector<int> fact(MAXN);

int mul(int a, int b) {
	int res = a * b;
	return res % MOD;
}

int binpow(int a, int b) {
	int res = 1;
	while (b > 0) {
		if (b & 1) {
			res = mul(res, a);
		}
		a = mul(a, a);
		b >>= 1;
	}
	return res;
}

int divv(int a, int b) {
	return mul(a, binpow(b, MOD - 2));
}

int who(int a, int b, int c) {
	int ans = 0;
	if (a > b) {
		ans++;
	}
	if (a > c) {
		ans++;
	}
	return ans;
}

void init() {
	fact[0] = 1;
	for (int i = 1; i < MAXN; i++) {
		fact[i] = mul(fact[i - 1], i);
	}
}



