template <
    usize N, class T, class... Args,
    std::enable_if_t<N==0, int> = 0
 >
auto mkvec(Args... args) {
    return T(args...);
}

template <
    usize N, class T, class... Args,
    std::enable_if_t<N!=0, int> = 0
 >
auto mkvec(usize sz, Args... args) {
    using value_type = std::decay_t<decltype(mkvec<N-1, T>(args...))>;
    return vec<value_type>(sz, value_type(args...));
}

int main(){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);
    std::cout << std::setprecision(15) << std::fixed;

    usize n, N;
    std::string s;
    std::cin >> n >> s;
    N = 3 * n;

    auto cum = mkvec<2, i32>(N, 3);
    for (usize i=0; i<N; i++) {
        if (i) cum.at(i) = cum.at(i-1);
        cum.at(i).at(s.at(i)%3)++;
    }

    vec<i32> min(N), max(N);
    for (usize i=0; i<N; i++) {
        min.at(i) = *std::min_element(ALL(cum.at(i)));
        max.at(i) = *std::max_element(ALL(cum.at(i)));
    }
    std::adjacent_difference(ALL(min), min.begin());
    std::adjacent_difference(ALL(max), max.begin());

    vec<i32> ear(N, 1);
    for (usize i=0; i<N; i++) {
        if (min.at(i)) ear.at(i) = 2;
        if (max.at(i)) ear.at(i) = 0;
    }

    mint ans = 1;
    vec<usize> now(3);
    for (i32 x: ear) {
        if (x==0) {
            now.at(0)++;
        }
        if (x==1) {
            ans *= now.at(0)--;
            now.at(1)++;
        }
        if (x==2) {
            ans *= now.at(1)--;
            now.at(2)++;
        }
    }

    for (usize i=1; i<=n; i++) {
        ans *= i;
    }
    std::cout << ans << '\n';
}

