#include<cstdio>
const int mod=998244353;
char s[300005];
int S[300005];
int posi[300005];//0:left 1:mid 2:right
int main(){
    int n;scanf("%d",&n);
    scanf("%s",s+1);
    int N=n*3;
    int r=0,g=0,b=0;
    for(int i=1;i<=N;++i){
        if(s[i]=='R'){
            S[i]=0;
        }else if(s[i]=='G'){
            S[i]=1;
        }else{
            S[i]=2;
        }
    }
    int cnt[3]={0,0,0};
    for(int i=1;i<=N;++i){
        cnt[S[i]]++;
        if(cnt[0]==cnt[1]&&cnt[1]==cnt[2]){//完全相同
            posi[i]=2;
        }
        int lt=0,gt=0,eq=0;
        for(int j=0;j<3;++j){
            if(cnt[j]>cnt[S[i]])gt++;
            else if(cnt[j]<cnt[S[i]])lt++;
            else eq++;
        }
        if(gt==2)posi[i]=2;
        else if(lt==2)posi[i]=0;
        else if(eq==3)posi[i]=2;
        else if(gt==1&&lt==1)posi[i]=1;
        else if(eq==2){
            if(gt==1){
                posi[i]=2;
            }else{
                posi[i]=1;
            }
        }
    }
    int ans=1;
    for(int i=1;i<=n;++i)ans=ans*1ll*i%mod;
    int num[3]={0,0,0};
    for(int i=1;i<=N;++i){
        if(posi[i]==0){
            num[0]++;
        }else if(posi[i]==1){
            ans=ans*1ll*num[0]%mod;
            num[0]--;num[1]++;
        }else{
            ans=ans*1ll*num[1]%mod;
            num[1]--;num[2]++;
        }
    }
    printf("%d\n",ans);
    return 0;
}
