int main(){
    FIO;
    ll n, mod = 998244353;
    cin >> n;
    string s;
    cin >> s;
    ll n1 = s.size(), ans = 1;
    ll cnt = n, r=0, g=0, b=0, rb=0, rg=0, gb=0;
    for(ll i = 0 ; i < n1 ; i++){
        if(s[i] == 'R'){
            if(gb > 0){
                ans *= gb;      gb--;
            }else if(g > 0 || b > 0){
                if(g > 0){
                    ans *= g;   rg++;   g--;
                }else{
                    ans *= b;   rb++;   b--;
                }
            }else{
                r++;    ans *= cnt;     cnt--;
            }
        }else if(s[i] == 'G'){
            if(rb > 0){
                ans *= rb;      rb--;
            }else if(b > 0 || r > 0){
                if(b > 0){
                    ans *= b;      b--;     gb++;
                }else{
                    ans *= r;       r--;    rg++;
                }
            }else{
                ans *= cnt;     cnt--;      g++;
            }
        }else{
            if(rg > 0){
                ans *= rg;      rg--;
            }else if(g > 0 || r > 0){
                if(r > 0){
                    ans *= r;       r--;    rb++;
                }else{
                    ans *= g;   g--;    gb++;
                }
            }else{
                ans *= cnt;     cnt--;      b++;
            }
        }
        //cout << ans << endl;
        ans %= mod;
    }
    cout << ans << endl;
    return 0;
}

