const int mod=998244353,N=100005;
int add(int x,int y)
{
  x+=y;
  if(x>=mod) x-=mod;
  if(x<0) x+=mod;
  return x;
}
int mult(int x,int y)
{
  ll tmp=(ll)x*y;
  if(tmp>=mod) tmp%=mod;
  return tmp;
}
//R,G,B,RG,RB,BG
map<vi,int> dp[N];
string s;
int fun(vi v,int ind)
{
  if(ind==sz(s)) return 1;
  if(dp[ind].count(v)) return dp[ind][v];
  int ans=0,id;
  if(s[ind]=='R') id=0;
  else if(s[ind]=='G') id=1;
  else id=2;
  int nxt1=(id+1),nxt2=(id+2);
  nxt1%=3; nxt2%=3;
  if(v[5-id])//2 are there
    {
      vi tmp(v);
      tmp[5-id]--;
      ans=mult(v[5-id],fun(tmp,ind+1));
    }
  else if(!v[nxt1] && !v[nxt2])//no single is there to join
    {
      vi tmp(v);
      tmp[id]++;
      ans=fun(tmp,ind+1);
    }
  else//join with one of the singles
    {
      if(s[ind]=='R')
	{
	  vi tmp(v);
	  //RG
	  if(tmp[nxt1])
	    {
	      tmp[nxt1]--; tmp[3]++;
	      ans=add(ans,mult(v[nxt1],fun(tmp,ind+1)));
	      tmp[nxt1]++; tmp[3]--;
	    }
	  //RB
	  if(tmp[nxt2])
	    {
	      tmp[nxt2]--; tmp[4]++;
	      ans=add(ans,mult(v[nxt2],fun(tmp,ind+1)));
	      tmp[nxt2]++; tmp[4]--;
	    }
	}
      else if(s[ind]=='G')
	{
	  vi tmp(v);
	  //GB
	  if(tmp[nxt1])
	    {
	      tmp[nxt1]--; tmp[5]++;
	      ans=add(ans,mult(v[nxt1],fun(tmp,ind+1)));
	      tmp[nxt1]++; tmp[5]--;
	    }
	  //RG
	  if(tmp[nxt2])
	    {
	      tmp[nxt2]--; tmp[3]++;
	      ans=add(ans,mult(v[nxt2],fun(tmp,ind+1)));
	      tmp[nxt2]++; tmp[3]--;
	    }
	}
      else
	{
	  vi tmp(v);
	  //RB
	  if(tmp[nxt1])
	    {
	      tmp[nxt1]--; tmp[4]++;
	      ans=add(ans,mult(v[nxt1],fun(tmp,ind+1)));
	      tmp[nxt1]++; tmp[4]--;
	    }
	  //BG
	  if(tmp[nxt2])
	    {
	      tmp[nxt2]--; tmp[5]++;
	      ans=add(ans,mult(v[nxt2],fun(tmp,ind+1)));
	      tmp[nxt2]++; tmp[5]--;
	    }
	}
    }
  return dp[ind][v]=ans;
}
