#define MOD 998244353

int n ;
string a ;

long long f[ 4 ] ;
int len ;
deque < pair < int , long long > > q ;

void input ( ) {
    cin >> n ;
    cin >> a ;
}

void solve ( ) {
    long long ans = 1 ;
    int len = 0 ;
    for ( int i = 0 ; i < 3 * n ; ++ i ) {
        int x = ( a[ i ] == 'G' ) * 1 + ( a[ i ] == 'B' ) * 2 ;
        if ( len >= 2 ) {
            pair < int , long long > aux1 = q.front ( ) ;
            q.pop_front ( ) ;
            pair < int , long long > aux2 = q.front ( ) ;
            q.pop_front ( ) ;
            len -= 2 ;
            if ( aux1.first != aux2.first && aux1.first != x && aux2.first != x ) {
                ans *= aux1.second ;
                ans %= MOD ;
                if ( aux1.second >= aux2.second ) {
                    ans *= aux2.second ;
                    ans %= MOD ;
                }
                -- aux1.second , -- aux2.second ;
                if ( aux2.second > 0 ) { q.push_front ( aux2 ) ; ++ len ; }
                if ( aux1.second > 0 ) { q.push_front ( aux1 ) ; ++ len ; }
            }
            else {
                if ( aux2.second > 0 ) { q.push_front ( aux2 ) ; ++ len ; }
                if ( aux1.second > 0 ) { q.push_front ( aux1 ) ; ++ len ; }
                pair < int , long long > ret = q.back ( ) ;
                q.pop_back ( ) ;
                if ( ret.first == x ) { ++ ret.second , q.push_back ( ret ) ; }
                else { q.push_back ( ret ) , q.push_back ( { x , 1 } ) , ++ len ; }
            }
        }
        else {
            if ( len == 0 ) {
                q.push_back ( { x , 1 } ) , ++ len ;
            }
            else {
                pair < int , long long > ret = q.back ( ) ;
                q.pop_back ( ) ;
                if ( ret.first == x ) { ++ ret.second , q.push_back ( ret ) ; }
                else { q.push_back ( ret ) , q.push_back ( { x , 1 } ) , ++ len ; }
            }
        }
    }
    for ( int i = 1 ; i <= n ; ++ i ) {
        ans = ( ans * i ) % MOD ;
    }
    printf ( "%lld\n" , ans ) ;
}

int main ( ) {
    ios_base :: sync_with_stdio ( false ) ;
    cin.tie ( NULL ) ;
    input ( ) ;
    solve ( ) ;
    return 0 ;
}

