int main(){
  ll N,ans=1LL;
  string S;
  cin>>N>>S;
  COMinit();

  ll CR[3*N+1],CG[3*N+1],CB[3*N+1];
  ll GROUP[3*N+1],mn=0LL,mx=0LL;
  // GROUP[i]=1,2 はそれぞれ 最初,最後
  REP(i,3*N+1){
    CR[i]=0;
    CG[i]=0;
    CB[i]=0;
    GROUP[i]=0;
  }

  RREP(i,3*N){
    CR[i]=CR[i-1];
    CG[i]=CG[i-1];
    CB[i]=CB[i-1];
    if(S[i-1]=='R'){
      CR[i]++;
      if(CR[i]>mx){
        mx++;
        GROUP[i]=1;
      }
      if(CR[i]>mn&&CG[i]>mn&&CB[i]>mn && CR[i-1]<=mn){
        mn++;
        GROUP[i]=2;
      }
    }
    if(S[i-1]=='G'){
      CG[i]++;
      if(CG[i]>mx){
        mx++;
        GROUP[i]=1;
      }
      if(CR[i]>mn&&CG[i]>mn&&CB[i]>mn && CG[i-1]<=mn){
        mn++;
        GROUP[i]=2;
      }
    }
    if(S[i-1]=='B'){
      CB[i]++;
      if(CB[i]>mx){
        mx++;
        GROUP[i]=1;
      }
      if(CR[i]>mn&&CG[i]>mn&&CB[i]>mn && CB[i-1]<=mn){
        mn++;
        GROUP[i]=2;
      }
    }

    chmin(mn,CR[i]);
    chmin(mn,CG[i]);
    chmin(mn,CB[i]);
    chmax(mx,CR[i]);
    chmax(mx,CG[i]);
    chmax(mx,CB[i]);
  }

  ll P[3*N+1],U=0;
  REP(i,3*N+1) P[i]=0;
  RREP(i,3*N){
    if(GROUP[i]==0) U=i;
    if(GROUP[i]==2) P[i]=U;
  }

  ll cnt=0;
  RREP(i,3*N){
    if(GROUP[i]==2){
      ll R=max(CR[P[i]]-cnt,0LL);
      ll G=max(CG[P[i]]-cnt,0LL);
      ll B=max(CB[P[i]]-cnt,0LL);
      if(S[i-1]=='R') R++;
      if(S[i-1]=='G') G++;
      if(S[i-1]=='B') B++;

      ans*=R*G*B;
      ans%=MOD;
      cnt++;
    }
  }

  ans*=fac[N];
  ans%=MOD;
  if(ans<0) ans+=MOD;
  co(ans);
  return 0;
}

