const ll MOD = 998244353;

ll modpow(ll x, ll n, ll mod = MOD) {
    ll res = 1;
    while (n > 0) {
        if (n & 1) res = res * x % mod;
        x = x * x % mod;
        n >>= 1;
    }
    return res;
}

ll solve(int n, const string& s) {
    vector<int> cnt(8, 0);
    ll ans = 1;
    for (int i = 1; i <= n; i++) {
        (ans *= i) %= MOD;
    }

    for (int i = 0; i < 3 * n; i++) {
        int hoge = 0;
        if (s[i] == 'R') {
            hoge = 1;
        } else if (s[i] == 'G') {
            hoge = 2;
        } else {
            hoge = 4;
        }

        if (cnt[7 ^ hoge] > 0) {
            (ans *= cnt[7 ^ hoge]) %= MOD;
            cnt[7 ^ hoge]--;
            cnt[7]++;
        } else {
            bool f = false;
            for (int j : {1, 2, 4}) {
                if (j == hoge) continue;
                if (cnt[j] > 0) {
                    f = true;
                    (ans *= cnt[j]) %= MOD;
                    cnt[j]--;
                    cnt[j ^ hoge]++;
                }
            }

            if (!f) {
                cnt[hoge]++;
            }
        }
    }
    return ans; 
}

