				R[2].push_back(make_pair(c,a));
			}
			else
			{
				L[2].push_back(make_pair(c,a));
				R[1].push_back(make_pair(b,a));
			}
		}
		else if(a<b^c<b)
		{
			if(a<c)
			{
				L[0].push_back(make_pair(a,b));
				R[2].push_back(make_pair(c,b));
			}
			else
			{
				L[2].push_back(make_pair(c,b));
				R[0].push_back(make_pair(a,b));
			}
		}
		else
		{
			if(a<b)
			{
				L[0].push_back(make_pair(a,c));
				R[1].push_back(make_pair(b,c));
			}
			else
			{
				L[1].push_back(make_pair(b,c));
				R[0].push_back(make_pair(a,c));
			}
		}
	}
	long ans=1;
	for(int i=0;i<3;i++)
	{
		sort(L[i].begin(),L[i].end());
		priority_queue<int>P;
		for(pair<int,int>p:L[i])
		{
			while(!P.empty()&&-P.top()<p.first)P.pop();
			P.push(-p.second);
			ans=ans*P.size()%mod;
		}
		sort(R[i].begin(),R[i].end());
		reverse(R[i].begin(),R[i].end());
		priority_queue<int>Q;
		for(pair<int,int>p:R[i])
		{
			while(!Q.empty()&&Q.top()>p.first)Q.pop();
			Q.push(p.second);
			ans=ans*Q.size()%mod;
		}
	}
	for(int i=1;i<=N;i++)ans=ans*i%mod;
	cout<<ans<<endl;
}

