int main() {
	int n; scanf("%d", &n);
	std::string s; cin >> s;

	using P = std::pair<int, int>;
	using P2 = std::pair<P, int>;

	const int MOD = 998244353;

	std::queue<int> R, G, B;
	std::queue<P> RG, RB, GR, GB, BR, BG;
	std::vector<P2> RGB, RBG, GRB, GBR, BRG, BGR;
	for(int i = 0; i < s.size(); i++) {
		if(s[i] == 'R') {
			if(!GB.empty()) {
				GBR.push_back({GB.front(), i});
				GB.pop();
			} else if(!BG.empty()) {
				BGR.push_back({BG.front(), i});
				BG.pop();
			} else if(!G.empty()) {
				GR.push({G.front(), i});
				G.pop();
			} else if(!B.empty()) {
				BR.push({B.front(), i});
				B.pop();
			} else {
				R.push(i);
			}
		} else if(s[i] == 'G') {
			if(!RB.empty()) {
				RBG.push_back({RB.front(), i});
				RB.pop();
			} else if(!BR.empty()) {
				BRG.push_back({BR.front(), i});
				BR.pop();
			} else if(!R.empty()) {
				RG.push({R.front(), i});
				R.pop();
			} else if(!B.empty()) {
				BG.push({B.front(), i});
				B.pop();
			} else {
				G.push(i);
			}
		} else if(s[i] == 'B') {
			if(!RG.empty()) {
				RGB.push_back({RG.front(), i});
				RG.pop();
			} else if(!GR.empty()) {
				GRB.push_back({GR.front(), i});
				GR.pop();
			} else if(!R.empty()) {
				RB.push({R.front(), i});
				R.pop();
			} else if(!G.empty()) {
				GB.push({G.front(), i});
				G.pop();
			} else {
				B.push(i);
			}	
		}
	}
	assert(R.empty() and B.empty() and G.empty());

	auto solve = [MOD](std::vector<P2>& vec) {
		if(vec.empty()) return 1LL;

		std::vector<int> A, B, C;
		for(auto v: vec) {
			A.push_back(v.second);
			B.push_back(v.first.second);
			C.push_back(v.first.first);
		}
		sort(begin(A), end(A)); reverse(begin(A), end(A));
		sort(begin(B), end(B)); reverse(begin(B), end(B));
		sort(begin(C), end(C)); reverse(begin(C), end(C));

		i64 ret = 1, a = 0;
		for(int i = 0; i < B.size(); i++) {
			int val = B[i];
			while(a < A.size() and val < A[a]) a++;
			(ret *= a - i) %= MOD;
		}
		reverse(begin(B), end(B)); reverse(begin(C), end(C));

		i64 c = 0;
		for(int i = 0; i < B.size(); i++) {
			int val = B[i];
			while(c < C.size() and val > C[c]) c++;
			(ret *= c - i) %= MOD;
		}
		return ret;
	};

	i64 ans = solve(RGB) * solve(RBG) % MOD
			* solve(GBR) % MOD * solve(GRB) % MOD
			* solve(BRG) % MOD * solve(BGR) % MOD;
	for(i64 i = 1; i <= n; i++) (ans *= i) %= MOD;
	printf("%lld\n", ans);
	return 0;
}

