using namespace std;

constexpr auto BASE = 998244353;

int N;
string b;

enum {R,G,B,CNUM};

int main()
{
	int ans = 1;
	int ans_min = 1;
	int ans_max = 1;

	cin >> N;
	cin >> b;

	int ball_count[CNUM];
	int min_count[CNUM];
	int max_count[CNUM];
	int cen_count[CNUM];
	for (int i = 0; i < CNUM; i++) {
		ball_count[i] = 0;
		min_count[i] = 0;
		max_count[i] = 0;
		cen_count[i] = 0;
	}


	int tgt,opp1, opp2;
	for ( int i = 0; i < N*CNUM; i++) {
		if (b.at(i) == 'R') {
			tgt = R;
			opp1 = G;
			opp2 = B;
		}
		else if (b.at(i) == 'G') {
			tgt = G;
			opp1 = B;
			opp2 = R;

		}
		else{
			tgt = B;
			opp1 = R;
			opp2 = G;
		}

		int opp_cen = cen_count[opp1] + cen_count[opp2];
		if (ball_count[tgt] >= ball_count[opp1] && ball_count[tgt] >= ball_count[opp2]) {
			//min
			ans_min = (ans_min * (min_count[tgt] - opp_cen + 1)) % BASE;

			min_count[tgt]++;
		}
		else if (ball_count[tgt] < ball_count[opp1] && ball_count[tgt] < ball_count[opp2]) {
			//max
			ans_max = (ans_max * (opp_cen - ball_count[tgt])) % BASE;

			max_count[tgt]++;
		}
		else {
			//center

			cen_count[tgt]++;
		}

		ball_count[tgt]++;
	}



	ans = (ans_min * ans_max) % BASE;
	for (int i = 1; i < N + 1; i++) {
		ans = (ans * i) % BASE;
	}

	cout << ans << endl;

	return 0;
}

