void solve() {
    int n;
    string s;
    cin >> n >> s;
    int cnt1[] = { 0, 0, 0 }, cnt2[] = { 0, 0, 0 };
    const int MOD = 998244353;
    int ans = 1;
    for (char x : s) {
        int t = 0;
        if (x == 'G')
            t = 1;
        else if (x == 'B')
            t = 2;
        int p = (t + 1) % 3, q = (t + 2) % 3;
        if (cnt2[t]) {
            ans = 1LL * ans * cnt2[t] % MOD;
            --cnt2[t];
        } else if (cnt1[p]) {
            assert(cnt1[q] == 0);
            ans = 1LL * ans * cnt1[p] % MOD;
            ++cnt2[q];
            --cnt1[p];
        } else if (cnt1[q]) {
            ans = 1LL * ans * cnt1[q] % MOD;
            ++cnt2[p];
            --cnt1[q];
        } else {
            ++cnt1[t];
        }
    }
    for (int i = 1; i <= n; ++i) {
        ans = 1LL * ans * i % MOD;
    }
    printf("%d\n", ans);
}

