            vector<int> b(3, 0);
            REP(k, x) b[2-k] = 1;
            bool ok = 0;
            do {
                int64 j =0;
                REP(k, 3) j |= b[k] << k;
                if (cnt[j] == 0) continue;
                if (j >> s[i] & 1) continue;
                if (j != 0)
                    res *= cnt[j];
                cnt[j]--;
                cnt[j | (1 << s[i])]++;
                ok = 1;
                break;
            } while(next_permutation(all(b)));
            if (ok) break;
        }
    }
    cout << res * f[N] << endl;
}

