int main() {
	const Int MOD = 998244353;
	Int N;
	cin >> N;
	string s;
	cin >> s;

	// 0:R, 1:G, 2:B, 3:**(R), 4:**(G), 5:**(B)
	vector<Int> dp(6, 0);
	Int ans = 1;
	for (int i = 0; i < s.size(); ++i) {
		int idx = c2i(s[i]);
		if (dp[idx + 3] > 0) {
			(ans *= dp[idx + 3]) %= MOD;
			--dp[idx + 3];
			continue;
		}
		for (int j = 0; j < 3; ++j) {
			if (idx < 0 ||j == idx || dp[j] <= 0) { continue; }
			(ans *= dp[j]) %= MOD;
			--dp[j];
			++dp[6 - (idx + j)];
			idx = -1;
		}
		if (idx >= 0) { ++dp[idx]; }
	}
	while (N > 0) {
		(ans *= N--) %= MOD;
	}
	cout << ans % MOD << endl;

	return 0;
}

