    for (int i = 0; i < 6; ++i) {
        int k = rgbs[i][1].size();
        if (i < 3) {
            int l = 0;
            for (int j = 0; j < k; ++j) {
                while (l != k - 1 && rgbs[i][1][j] > rgbs[i][0][l + 1])
                    l++;
                ret *= l + 1 - j;
                assert(l + 1 - j > 0);
            }
        } else {
            int r = k - 1;
            for (int j = k - 1; j >= 0; --j) {
                while (r != 0 && rgbs[i][1][j] < rgbs[i][2][r - 1])
                    r--;
                ret *= (k - 1 - r + 1) - (k - 1 - j);
                assert((k - 1 - r + 1) - (k - 1 - j) > 0);
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        ret *= i;
    }
    cout << ret << "\n";
    return 0;
}

