struct Combination{

    vector<mint> fact, invfact;

    Combination(int N){
        fact = vector<mint>({mint(1)});
        invfact = vector<mint>({mint(1)});
        fact_initialize(N);
    }

    void fact_initialize(int N){
        int i0 = fact.size();
        if(i0 >= N + 1) return;
        fact.resize(N + 1);
        invfact.resize(N + 1);
        for(int i = i0; i <= N; i++) fact[i] = fact[i - 1] * i;
        invfact[N] = (mint)1 / fact[N];
        for(int i = N - 1; i >= i0; i--) invfact[i] = invfact[i + 1] * (i + 1); 
    }

    mint nCr(int n, int r){
        if(n < 0 || r < 0 || r > n) return mint(0);
        if(fact.size() < n + 1) fact_initialize(n);
        return fact[n] * invfact[r] * invfact[n - r];
    }

    mint nPr(int n, int r){
        if(n < 0 || r < 0 || r > n) return mint(0);
        if(fact.size() < n + 1) fact_initialize(n);
        return fact[n] * invfact[n - r];
    }

};

signed main(){

    int N; cin >> N;
    string S; cin >> S;

    Combination C(N);

    vec r, g, b;
    int ir = 0, ig = 0, ib = 0;
    mint ans = 1;
    REP(i, 3 * N){
        if(S[i] == 'R'){
            if(SZ(g) > ig && SZ(b) > ib){
                if(g[ig] < b[ib]){
                    int u = Lower_bound(g, b[ib]);
                    ans *= u - ig;
                    ans *= min(u - ig, SZ(b) - ib);
                }else{
                    int u = Lower_bound(b, g[ig]);
                    ans *= u - ib;
                    ans *= min(u - ib, SZ(g) - ig);
                }
                ig++;
                ib++;
            }else r.pb(i);
        }else if(S[i] == 'G'){
            if(SZ(b) > ib && SZ(r) > ir){
                if(b[ib] < r[ir]){
                    int u = Lower_bound(b, r[ir]);
                    ans *= u - ib;
                    ans *= min(u - ib, SZ(r) - ir);
                }else{
                    int u = Lower_bound(r, g[ib]);
                    ans *= u - ir;
                    ans *= min(u - ir, SZ(b) - ib);
                }
                ib++;
                ir++;
            }else g.pb(i);
        }else{
            if(SZ(r) > ir && SZ(g) > ig){
                if(r[ir] < g[ig]){
                    int u = Lower_bound(r, g[ig]);
                    ans *= u - ir;
                    ans *= min(u - ir, SZ(g) - ig);
                }else{
                    int u = Lower_bound(g, g[ir]);
                    ans *= u - ig;
                    ans *= min(u - ig, SZ(r) - ir);
                }
                ir++;
                ig++;
            }else b.pb(i);
        }
    }
    ans *= C.fact[N];
    Out(ans);

    return 0;
}

