ll calc(vector<ll> big,vector<ll> mid,vector<ll> sml){
	ll n = big.size();
	ll pbig=1,psml=1;
	vector<ll> cntb(n,0),cnts(n,0);

	FOR(i,0,n){
		ll can = POSU(mid,big[i]);
		cntb[can-1]++;
	}
	FORR(i,0,n-1)cntb[i]+=cntb[i+1];
	ll j = 0;
	FORR(i,0,n){
		(pbig *= (cntb[i]-j)) %= MOD;
		j++;
	}


	FOR(i,0,n){
		ll can = POSL(mid,sml[i]);
		cnts[can]++;
	}
	FOR(i,1,n)cnts[i]+=cnts[i-1];

	FOR(i,0,n){
		(psml *= cnts[i]-i) %= MOD;
	}


	//cout << "#####" << (pbig*psml)%MOD << "#####" << endl;
	return (pbig*psml)%MOD;
}


char char_big(ll B,ll G,ll R){
	if(max({B,G,R})==B)return 'B';
