			cnt[0]++;
			a[i]=-1;
		}
		else if(cnt[1]&&col[1]&&col[1]==s[i])
		{
			cnt[1]++;
			if(cnt[1]>cnt[0])
			{
				swap(cnt[1],cnt[0]);
				swap(col[1],col[0]);
				a[i]=-1;
			}
			else a[i]=0;
		}
		else if(!cnt[0])
		{
			cnt[0]=1;
			col[0]=s[i];
			a[i]=-1;
		}
		else if(!cnt[1])
		{
			cnt[1]=1;
			col[1]=s[i];
			a[i]=0;
		}
		else
		{
			cnt[0]--;
			cnt[1]--;
			a[i]=1;
		}
	}
	int rem=0;
	for(int i=0;i<LEN;i++)
	{
		if(a[i]==-1)rem++;
		if(a[i]==0)ans=ans*rem%mod,rem--;
	}
	for(int i=LEN-1;i>=0;i--)
	{
		if(a[i]==1)rem++;
		if(a[i]==0)ans=ans*rem%mod,rem--;
	}
	//printf("%lld\n",ans);
	for(int i=1;i<=n;i++)ans=ans*i%mod;
	printf("%lld\n",ans);
	return 0;
}

