#define BASE 998244353
using namespace std;

struct Tuple3 {
    int a, b, c;
};

typedef pair<int, int> P;

long calc(vector<Tuple3> v) {
    const int n = v.size();
    int balls[3][n];
    for (int i = 0; i < n; i++) {
        balls[0][i] = v[i].a;
        balls[1][i] = v[i].b;
        balls[2][i] = v[i].c;
    }
    long ret = 1;
    for (int j = 1; j < 3; j++) {
        for (int i = 0; i < n; i++) {
            ret = (ret * (lower_bound(balls[j - 1], balls[j - 1] + n, balls[j][i]) - balls[j - 1] - i)) % BASE;
        }
    }
    return ret;
}

