    mfact(int size = 200010) : fact(size + 1), ifact(size + 1) {
        fact[0] = mint<mod>(1);
        for(int i = 1; i <= size; i++)fact[i] = fact[i - 1] * mint<mod>(i);
        ifact[size] = fact[size].inv();
        for(int i = size; i > 0; i--)ifact[i - 1] = ifact[i] * mint<mod>(i);
    }
    inline mint<mod> operator [] (int i){ return fact[i]; }
    inline mint<mod> nPr(int n, int r){ return fact[n] * ifact[r]; }
    inline mint<mod> nCr(int n, int r){ return fact[n] * ifact[n - r] * ifact[r]; }
};

