    mint<998244353> ans(1);

    function<int(char)> enc = [](char c){
        if(c == 'R')return 1;
        if(c == 'G')return 2;
        if(c == 'B')return 4;
        return 0;
    };

    vector<int> cnt(7, 0);
    rep(i, n * 3){
        char c; cin >> c;
        c = enc(c);
        if(cnt[7 - c]){
            ans *= mint<998244353>(cnt[7 - c]--);
            continue;
        }
        bool found = false;
        for(int j = 1; j <= 4; j <<= 2)if(found = cnt[j]){
            if(c == j){
                cnt[j]++; break;
            } else {
                ans *= mint<998244353>(cnt[j]--);
                cnt[c + j]++;
                break;
            }
        }
        if(!found)cnt[c]++; 
    }

    for(int i : cnt)assert(i == 0);
    cout << ans * mfact<998244353>()[n] << endl;
    return 0;

}

