int solve(int n, string s) {
    vector<vector<int>> v(3);
    vector<int> a(3 * n);
    for (int i = 0; i < 3 * n; i++) {
        string Z = "RGB";
        int c = 0;
        while (Z[c] != s[i]) c++;
        a[i] = c;
        v[c].push_back(i);
    }

    vector<vector<pair<int, int>>> b(3);
    vector<int> coef(3 * n);
    for (int i = 0; i < n; i++) {
        int x = v[0][i], y = v[1][i], z = v[2][i];
        if (x>y) swap(x, y);
        if (x>z) swap(x, z);
        if (y>z) swap(y, z);

        coef[x] = -1;
        coef[z] = +1;

        for (int j = 0; j< 3; j++) {
            if (v[j][i] == y) {
                b[j].push_back({x, -1});
                b[j].push_back({y, 0});
                b[j].push_back({z, +1});
            }
        }
    }

    mint ans = 1;
    for (auto vct : b) {
        sort(vct.begin(), vct.end());
        int cur1 = 0;
        int cur2 = 0;
        for (auto o : vct) {
            if (o.second == -1) {
                cur1++;
                cur2++;
            } else if (o.second == 0) {
                ans *= cur2--;
            } else {
                ans *= cur1--;
            }
        }
    }
    for (int i = 1; i <= n; i++) ans *= i;
    return ans();
}

