#include<cstdio>
#include<algorithm>
using ll = long long;
constexpr ll mod = 998244353;
char s[300001]={};
ll factorial[100001];
char order[300001]={};//'a'<'b'<'c'
int main(){
    int n;
    scanf("%d%s",&n,s);
    factorial[0]=1;
    for(int i=1;i<=n;++i){
        factorial[i]=(factorial[i-1]*static_cast<ll>(i))%mod;
    }
    //ordering
    int r_itr=0,g_itr=0,b_itr=0;
    while(true){
        while(r_itr<3*n && s[r_itr]!='R')r_itr++;
        while(g_itr<3*n && s[g_itr]!='G')g_itr++;
        while(b_itr<3*n && s[b_itr]!='B')b_itr++;
        if(r_itr>=3*n || g_itr>=3*n || b_itr>=3*n)break;
        int sorted_itr[3]={r_itr,g_itr,b_itr};
        std::sort(sorted_itr,sorted_itr+3);
        order[sorted_itr[0]]='a';
        order[sorted_itr[1]]='b';
        order[sorted_itr[2]]='c';
        ++r_itr;
        ++g_itr;
        ++b_itr;
    }
    ll ans=factorial[n];
    int cnt=1;
    for(int i=1;i<3*n;++i){
        if(s[i]==s[i-1]&&order[i]==order[i-1])++cnt;
        else{
            ans=(ans*factorial[cnt])%mod;
            cnt=1;
        }
    }
    printf("%lld\n",ans);
    return 0;
}

