        auto f = [&](int k){
            if(v[0].fs == v[2].fs) return 1LL;
            LL pp = v[2].fs - v[1].fs;
            LL p = v[1].fs - v[0].fs;
            if(v[0].sc == k){
                if(!p) return pp;
                else return p;
            }
            else if(v[1].sc == k){
                if(!pp) return 1LL; 
                else return pp;
            }
            else return 1LL;
        };
        if(s[i]=='R'){
            ans = (ans * f(0))%mod;
            a[0]++;
        }
        else if(s[i]=='G'){
            ans = (ans * f(1))%mod;
            a[1]++;
        }
        else{
            ans = (ans * f(2))%mod;
            a[2]++;
        }
    }
    cout << ans << endl;
    return 0;
}

