            chmin(mi,v[i+cnt][1]);
            cnt++;
        }
        ans=ans*fac[cnt]%mod;
        i+=cnt;
    }

    for(int i=n-1;i>=0;){
        int cnt=0;
        int mx=v[i][1];
        while(i-cnt>=0 and v[i-cnt][2]>mx){
            chmax(mx,v[i-cnt][1]);
            cnt++;
        }
        ans=ans*fac[cnt]%mod;
        i-=cnt;
    }
    cout<<ans<<endl;
    return 0;
}

