using namespace std;
#define int64 long long

const int MODULO = 998244353;
const int N_MAX = 100010;

namespace Mod {
	int product(int x, int y) {
		return (int64)x * y % MODULO;
	}
}

struct Group {
	vector<int> A, B, C;
};

Group groups[3][3];
int factorials[N_MAX];
int nTuple;

int computeAlignment(const vector<int> &A, const vector<int> &B) {
	int n = A.size();

	vector<int> rightBound(n);
	for (int i = 0; i < n; ++i) {
		int j = (i > 0 ? rightBound[i - 1] : 0);
		while (j < n && A[j] < B[i]) ++j;
		rightBound[i] = j;
	}

	int result = 1;
	int cnt = 0;
	int j = n - 1;
	for (int i = n - 1; i >= 0; --i) {
		while (j >= 0 && rightBound[j] > i) {
			++cnt;
			--j;
		}

		result = Mod::product(result, cnt);
		--cnt;
	}

	return result;
}

int computeGroupShuffle(const Group &group) {
	if (group.A.empty()) return 1;

	int s = computeAlignment(group.A, group.B);
	s = Mod::product(s, computeAlignment(group.B, group.C));
	return s;
}

