void readData() {
	string S;
	cin >> nTuple >> S;

	deque<int> R, G, B;
	vector<pair<int, int>> tmp;
	for (int i = 0; i < S.size(); ++i) {
		if (S[i] == 'R') R.push_back(i);
		if (S[i] == 'G') G.push_back(i);
		if (S[i] == 'B') B.push_back(i);

		if (!R.empty() && !G.empty() && !B.empty()) {
			tmp.clear();
			tmp.emplace_back(R.front(), 0);
			tmp.emplace_back(G.front(), 1);
			tmp.emplace_back(B.front(), 2);
			sort(tmp.begin(), tmp.end());

			R.pop_front();
			G.pop_front();
			B.pop_front();

			int x = tmp.front().second;
			int y = tmp.back().second;
			groups[x][y].A.push_back(tmp[0].first);
			groups[x][y].B.push_back(tmp[1].first);
			groups[x][y].C.push_back(tmp[2].first);
		}
	}
}

void initData() {
	factorials[0] = 1;
	for (int i = 1; i <= nTuple; ++i) {
		factorials[i] = Mod::product(factorials[i - 1], i);
	}
}

void solveData() {
	int result = factorials[nTuple];
	for (int x = 0; x < 3; ++x) {
		for (int y = 0; y < 3; ++y) {
			result = Mod::product(result, computeGroupShuffle(groups[x][y]));
		}
	}

	cout << result << "\n";
}

