    a = a*b % MOD;
}

int main(){
    int N;
    string str;
    cin >> N >> str;
    string RGB = "RGB";
    vector<int> S(3*N);
    for(int i=0; i<3*N; i++) S[i] = RGB.find(str[i]);

    vector<bool> start(3*N), term(3*N);
    for(int t=0; t<2; t++){
        int num[3] = {0};
        for(int i=0; i<3*N; i++){
            num[S[i]]++;
            if(num[0] && num[1] && num[2]){
                (t ? start : term)[i] = 1;
                for(int k=0; k<3; k++) num[k]--;
            }
        }
        reverse(S.begin(), S.end());
    }
    reverse(start.begin(), start.end());

    int64_t ans = 1;
    int st[3] = {0}, ready[3] = {0};
    for(int i=0; i<3*N; i++){
        int a = S[i];
        if(start[i]){
            st[a]++;
        }else if(term[i]){
            mul(ans, ready[a]);
            ready[a]--;
        }else{
            int s = (a+1)%3, t = (a+2)%3;
            if(st[t]) swap(s, t);
            mul(ans, st[s]);
            st[s]--;
            ready[t]++;
        }
    }
    for(int i=1; i<=N; i++) mul(ans, i);
    cout << ans << endl;
    return 0;
}

