void solve(istream &cin = std::cin, ostream &cout = std::cout)
{
    auto solve_test = [&] ()
    {
        int n;
        if (!(cin >> n))
            return false;

        string s;
        cin >> s;
        assert(int(s.size()) == 3 * n);

        vector<int> only(3), without(3);

        int ans = 1;
        for (char ch : s)
        {
            const int cur = (ch == 'R' ? 0 : (ch == 'G' ? 1 : (ch == 'B' ? 2 : -1)));
            assert(cur != -1);

            if (without[cur] > 0)
            {
                ans = mult(ans, without[cur]);
                without[cur]--;
            }
            else
            {
                bool ok = false;
                for (int i = 0; !ok && i < 3; i++)
                if (i != cur)
                {
                    if (only[i] > 0)
                    {
                        ans = mult(ans, only[i]);
                        only[i]--;
                        without[i ^ cur ^ 3]++;
                        ok = true;
                    }
                }

                if (!ok)
                    only[cur]++;
            }
        }

        for (int i = 1; i <= n; i++)
            ans = mult(ans, i);

        cout << ans << endl;
        return true;
    };

    while (solve_test());
}


