template<class T, class Alloc = std::allocator<T>>
class Vector {

	using traits = std::allocator_traits<Alloc>;

	using size_type = unsigned int;

	class iterator {

	public:

		using difference_type = int;
		using value_type = T;
		using pointer = T*;
		using reference = T&;
