struct solver_agc_037_b {
	// int one = 0, two = 0;
	// int r = 0, g = 0, b = 0, rg = 0, rb = 0, gb = 0, gr = 0, br = 0, bg = 0, all = 0;
	// int r = 0, g = 0, b = 0, xr = 0, xg = 0, xb = 0, all = 0;
	// int used_one = 0, used_two = 0;
	// int one = 0, two = 0;
	// char one_col, two_col;
	ll run(int N, string S) {
		int r = 0, g = 0, b = 0, xr = 0, xg = 0, xb = 0, all = 0;
		int used_one = 0, used_two = 0;
		int one = 0, two = 0;
		const int MOD = 998244353;
		ll ans = 1;
		char col;

		for(int i = 0; i < 3 * N; ++i) {
			col = S[i];
			if((r+g+b) == 0) {
				cerr << "one" << col << ": " << (N - used_one) << endl;
				ans *= (N - used_one);
				ans %= MOD;
				if(col == 'R') {
					++r;
				}else if(col == 'G'){
					++g;
				}else{
					++b;
				}
				used_one++;
				one++;
			}else{
				cerr << "i col: " << i << col << endl;
				if(col == 'R') {
					if(r >= 1) {
						// add stack
						cerr << "one r: " << (N - used_one) << endl;
						ans *= (N - used_one);
						++r;
						used_one++;
					}else if((xg + xb) >= 1) {
						// close
						cerr << "close r: " << (xg + xb) << endl;
						ans *= (xg + xb);
						if(xg >= 1) {
							xg--;
							b--;
						}else{
							xb--;
							g--;
						}
					}else{
						if((g + b - xr) == 0) {
							cerr << "full one: " << (N - used_one) << endl;
							ans *= (N - used_one);
							++r;
							used_one++;
						}else{
							cerr << "two: " << (g + b - xr) << endl;
							ans *= (g + b - xr);
							xr++;
						}
					}
				}else if(col == 'G'){
					if(g >= 1) {
						// add stack
						cerr << "one g: " << (N - used_one) << endl;
						ans *= (N - used_one);
						++g;
						used_one++;
					}else if((xb + xr) >= 1) {
						// close
						cerr << "close g" << (xb + xr) << endl;
						ans *= (xb + xr);
						if(xb >= 1) {
							xb--;
							r--;
						}else{
							xr--;
							b--;
						}
					}else{
						if((b + r - xg)== 0) {
							cerr << "full one: " << (N - used_one) << endl;
							ans *= (N - used_one);
							++g;
							used_one++;
						}else{
							cerr << "two: " << (b + r - xg) << endl;
							ans *= (b + r - xg);
							xg++;
						}
					}
				}else{
					if(b >= 1) {
						// add stack
						cerr << "one b: " << (N - used_one) << endl;
						ans *= (N - used_one);
						++b;
						used_one++;
					}else if((xr + xg) >= 1) {
						// close
						cerr << "close b" << (xr + xg) << endl;
						ans *= (xr + xg);
						if(xr >= 1) {
							xr--;
							g--;
						}else{
							xg--;
							r--;
						}
					}else{
						if((r + g - xb)== 0) {
							cerr << "full one: " << (N - used_one) << endl;
							ans *= (N - used_one);
							++b;
							used_one++;
						}else{
							cerr << "two: " << (r + g - xb) << endl;
							ans *= (r + g - xb);
							xb++;
						}
					}
				}
				ans %= MOD;
			}
			cerr << ans << endl;
		}
		return ans;
	}
};

