#define MOD 998244353ll
char S[303030];
ll N,N3,rgb[303030];
ll alw[303030];// 0:-> 1:O 2:<-
stack<pll> rgbstk[3];
ll Fa[101010];
ll i,j,k,ans;

ll moddiv(ll a,ll b){
    a %= MOD;
    b %= MOD;
    for(ll m=MOD-2;m>0;m/=2){
        if(m&1){
            a=a*b%MOD;
        }
        b=b*b%MOD;
    }
    return a;
}

int main(){
    scanf("%d%s",&N, S);
    Fa[0] = 1;
    fornum(i,0,N){
        Fa[i + 1] = Fa[i] * (i + 1) % MOD;
    }
    N3 = N * 3;
    fornum(i,0,N3){
        switch(S[i]){
            case 'R':
                rgb[i] = 0;
                break;
            case 'G':
                rgb[i] = 1;
                break;
            case 'B':
                rgb[i] = 2;
                break;
        }
    }
    ll rgbn[] = {0, 0, 0};
    fornum(i,0,N3){
        rgbn[rgb[i]]++;
        ll f = 0;
        fornum(j,0,3){
            if(rgb[i]!=j&&rgbn[rgb[i]]<=rgbn[j]){
                f++;
            }
        }
        alw[i] = f;
        //printf("%lld ", f);
    }

    pll jj = {rgb[N3 - 1], alw[N3 - 1]};
    k = 1;
    fornum(i,1,N3){
        //printf("%lld:%lld,%lld:%lld,%lld\n", i, jj.first, jj.second, rgb[N3 - 1 - i], alw[N3 - 1 - i]);
        if (jj.first !=rgb[N3 - 1 - i]||jj.second!= alw[N3 - 1 - i])
        {
            rgbstk[jj.first].push({N3 - i, k});
            jj = {rgb[N3 - 1 - i], alw[N3 - 1 - i]};
            k = 0;
        }
        k++;
    }
    rgbstk[jj.first].push({0, k});

    rgbn[0]=rgbn[1]=rgbn[2]=0;
    i = N;
    ans = 1;
    while(i>0){
        //printf("%lld,%lld\n", i, ans);
        ll a = 1e9;
        fornum(j,0,3){
            if(rgbn[j]==0){
                rgbn[j] = rgbstk[j].top().second;
                rgbstk[j].pop();
            }
            a = min(a, rgbn[j]);
        }
        //printf("%lld ", a);
        ll r = moddiv(Fa[rgbn[0]], Fa[a]*Fa[rgbn[0] - a]);
        ll g = moddiv(Fa[rgbn[1]], Fa[rgbn[1] - a]);
        ll b = moddiv(Fa[rgbn[2]], Fa[rgbn[2] - a]);
        ans = (ans *r%MOD * g%MOD * b) % MOD;
        i -= a;
        fornum(j,0,3){
            rgbn[j] -= a;
        }
    }
    printf("%lld", ans*Fa[N]%MOD);
    return 0;
}

