int main() 
{
	int n; scanf("%d ", &n);
	long long res = 1;
	for (int i = 0; i < 3 * n; ++i)
	{
		char c = getchar();
		int x = (++c ^ 64) / 8;
		int y = x ? x - 1 : 2;
		int z = y ? y - 1 : 2;
		if (cnt[y] > cnt[z])
			std::swap(y, z);
		if (cnt[x] < cnt[y]) 
		{
			res = res * (cnt[y] - cnt[x]++) % MOD;
			continue;
		}
		if (cnt[x] < cnt[z]) 
		{
			res = res * (cnt[z] - cnt[x]++) % MOD;
			continue;
		}
		res = res * ++cnt[x] % MOD;
	}
	printf("%lld\n", res);
}

