int main(){
    int n;
    string s;
    cin>>n>>s;
    ll ans=1;
    ll head,mid,len=0;
    queue<int> q[3];
    for(int i=2;i<=n;i++){
        ans=(ans*i)%MOD;
    }
    for(int i=0;i<3*n;i++){
        if(s[i]=='R')q[0].push(i);
        else if(s[i]=='G')q[1].push(i);
        else q[2].push(i);
        if(q[0].size()&&q[1].size()&&q[2].size()){
            if(len==0){
                int m=min({q[0].front(),q[1].front(),q[2].front()});
                for(int k=0;k<3;k++){
                    if(q[k].front()==m)head=k;
                }
                int j=head+1;
                len=1;
                while(j<3*n&&s[head]==s[j]){
                    j++;
                    len++;
                }
            }
            if(s[head]+s[i]=='R'+'G'){
                mid=2;
            }
            else if(s[head]+s[i]=='G'+'B'){
                mid=0;
            }
            else{
                mid=1;
            }
            ans=(ans*len)%MOD;
            ans=(ans*min(len,(ll)q[mid].size()))%MOD;
            len--;
            for(int j=0;j<3;j++)q[j].pop();
        }
    }
    cout<<ans<<endl;
}

