void solve ( ) {
    long long ans = 1 ;
    long long len = 0 ;
    for ( long long i = 0 ; i < 3 * n ; ++ i ) {
        long long x = ( a[ i ] == 'G' ) * 1 + ( a[ i ] == 'B' ) * 2 ;
        if ( len >= 2 ) {
            pair < long long , long long > aux1 = q.front ( ) ;
            q.pop_front ( ) ;
            pair < long long , long long > aux2 = q.front ( ) ;
            q.pop_front ( ) ;
            len -= 2 ;
            if ( aux1.first != aux2.first && aux1.first != x && aux2.first != x ) {
                ans *= aux1.second ;
                ans %= MOD ;
                if ( aux1.second >= aux2.second ) {
                    ans *= aux2.second ;
                    ans %= MOD ;
                }
                else {
                    ans *= aux1.second ;
                    ans %= MOD ;
                }
                -- aux1.second , -- aux2.second ;
                if ( aux2.second > 0 ) { q.push_front ( aux2 ) ; ++ len ; }
                if ( aux1.second > 0 ) { q.push_front ( aux1 ) ; ++ len ; }
            }
            else {
                if ( aux2.second > 0 ) { q.push_front ( aux2 ) ; ++ len ; }
                if ( aux1.second > 0 ) { q.push_front ( aux1 ) ; ++ len ; }
                pair < long long , long long > ret = q.back ( ) ;
                q.pop_back ( ) ;
                if ( ret.first == x ) { ++ ret.second , q.push_back ( ret ) ; }
                else { q.push_back ( ret ) , q.push_back ( { x , 1 } ) , ++ len ; }
            }
        }
        else {
            if ( len == 0 ) {
                q.push_back ( { x , 1 } ) , ++ len ;
            }
            else {
                pair < long long , long long > ret = q.back ( ) ;
                q.pop_back ( ) ;
                if ( ret.first == x ) { ++ ret.second , q.push_back ( ret ) ; }
                else { q.push_back ( ret ) , q.push_back ( { x , 1 } ) , ++ len ; }
            }
        }
    }
    for ( long long i = 1 ; i <= n ; ++ i ) {
        ans = ( ans * i ) % MOD ;
    }
    printf ( "%lld\n" , ans ) ;
}

int main ( ) {
    ios_base :: sync_with_stdio ( false ) ;
    cin.tie ( NULL ) ;
    input ( ) ;
    solve ( ) ;
    return 0 ;
}

