#define REP(i, n) for(ll i = 0;i < n;i++)
#define ll long long
#define MOD 1000000007
using vi = vector<ll>; // intの1次元の型に vi という別名をつける
using vvi = vector<vi>; // intの2次元の型に vvi という別名をつける

ll n,k,x,y;

int main(){
  ll ans=1LL;
  cin >> n;
  string s;cin>>s;

  vi lr(n*3);//0がL、1が中間、2がR
  vi rgb(3);
  vi dat0(n*3);//0が何個つながってるか、1が何こつながってるか記憶するやつ
  vi datn(n*3);//0が何個つながってるか、1が何こつながってるか記憶するやつ

  ll flag=0;
  REP(i,n*3){
    if (s[i]=='R') flag=0;
    if (s[i]=='G') flag=1;
    if (s[i]=='B') flag=2;
    rgb[flag]++;
    lr[i]=1;
    if ((rgb[(flag+1)%3]!=0)&(rgb[(flag+2)%3]!=0)){
      lr[i]=2;
      rgb[0]--;
      rgb[1]--;
      rgb[2]--;
    }else{
      if (rgb[flag]>rgb[(flag+1)%3]){
        if (rgb[flag]>rgb[(flag+2)%3]){
          lr[i]=0;
        }
      }
    }
  }


  dat0[0]=lr[0];
  datn[0]=1;
  int w=0;
  int ref=0;
  int dref=0;
  for(int i=1;i<n*3;i++){
    if (lr[i]==2){
      ans*=datn[dref];
      ans%=MOD;
      ans*=datn[dref+1];
      ans%=MOD;
      datn[dref]--;
      datn[dref+1]--;
      if (datn[dref]==0){
        dref+=2;
      }
      continue;
    }else{
      if (lr[ref]==lr[i]){
        datn[w]++;
      }else{
        w++;
        dat0[w]=lr[i];
        datn[w]=1;
      }
      ref=i;
    }
  }

  REP(i,n){
    ans*=(i+1LL);
    ans%=MOD;
  }


  cout<<ans<<endl;
  return 0;
}

