	// snuke method
	const ll mod = 998244353;

	ll N;
	string S; //size 3N
	cin >> N >> S;
	ll cnt_r=0, cnt_g=0, cnt_b=0;
	ll ans = 1;
	rep(i, 3*N) {
		if(S[i]=='R') {
			if(cnt_r<cnt_g && cnt_r<cnt_b) {
				ans *= min(cnt_g, cnt_b);
				ans %= mod;
				cnt_g--; 
				cnt_b--;
			} else if(cnt_r>=cnt_g && cnt_r>=cnt_b) {
				cnt_r++;
			} else {
				ans *= max(cnt_g, cnt_b) - cnt_r;
				ans %= mod;
				cnt_r++;	
			}
		} else if(S[i]=='G') {
			if(cnt_g<cnt_r && cnt_g<cnt_b) {
				ans *= min(cnt_r, cnt_b);
				ans %= mod;
				cnt_r--; 
				cnt_b--;
			} else if(cnt_g>=cnt_r && cnt_g>=cnt_b) {
				cnt_g++;
			} else {
				ans *= max(cnt_r, cnt_b) - cnt_g;
				ans %= mod;
				cnt_g++;	
			}
		} else {
			if(cnt_b<cnt_g && cnt_b<cnt_r) {
				ans *= min(cnt_g, cnt_r);
				ans %= mod;
				cnt_g--; 
				cnt_r--;
			} else if(cnt_b>=cnt_g && cnt_b>=cnt_r) {
				cnt_b++;
			} else {
				ans *= max(cnt_g, cnt_r) - cnt_b;
				ans %= mod;
				cnt_b++;	
			}
		}
	}
	ans *= factorial(N);
	ans %= mod;
	cout << ans << endl;

	return 0;
}

