        int x = ( a[ i ] == 'B' ) + ( a[ i ] == 'G' ) * 2 ;
        int lft = ( 7 - (1<<x) ) ;
        if ( f[ lft ] > 0 ) {
            ans *= f[ lft ] -- , ans %= MOD ;
        }
        else {
            int j ;
            for ( j = 0 ; j < 3 ; ++ j ) {
                if ( j == x )  { continue ; }
