                    break ;
                }
            }
            if ( j >= 3 ) {
                ++ f[ (1<<x) ] ;
            }
        }
    }
    for ( int i = 1 ; i <= n ; ++ i ) {
        ans = ( ans * i ) % MOD ;
    }
    printf ( "%lld\n" , ans ) ;
}

