namespace modint {
    static const int MODx = 998244353;

    struct mint {
        int a = 0;

        mint() {}

        mint(int a) : a(a) {}

        mint operator+(const mint& b) const {
            int res = a + b.a;
            if (res >= MODx) {
                res -= MODx;
            }
            return res;
        }

        void operator+=(const mint& b) {
            a += b.a;
            if (a >= MODx) {
                a -= MODx;
            }
        }

        mint operator-(const mint& b) const {
            int res = a - b.a;
            if (res < 0) {
                res += MODx;
            }
            return res;
        }

        void operator-=(const mint& b) {
            a -= b.a;
            if (a < 0) {
                a += MODx;
            }
        }

        mint operator*(const mint& b) const {
            return (ll) a * b.a % MODx;
        }

        void operator*=(const mint& b) {
            a = (ll) a * b.a % MODx;
        }

        int get() const {
            return a;
        }
    };

    mint fpow(mint a, int p) {
        mint x = 1;
        while (p) {
            if (p & 1) {
                x *= a;
            }
            a *= a;
            p >>= 1;
        }
        return x;
    }

    istream& operator>>(istream& in, mint& a) {
        return (in >> a.a);
    }

    ostream& operator<<(ostream& out, const mint& a) {
        return (out << a.a);
    }
}

