inline int ex_gcd(int a, int b, int &x, int &y)//a>=b
{
    if(!b)
    {
        x=1, y=0;
        return a;
    }
    int g=ex_gcd(b, a%b, x, y);
    int t=x;
    x=y, y=t-a/b*x;
    return g;
}

inline int invp(int N, int M)// M>N
{
    int x, y;
    int d=ex_gcd(M, N, x, y);
    if(d!=1) return -1;
    return ((y%M)+M)%M;
}	

