class ModInt {
    const int M;
    int value;
public:
    ModInt(long long n, int m) : M(m), value((n % m + m) % m) {}
    ModInt& operator*=(long long x) {
        x %= M;
        if (x < 0) x += M;
        value = static_cast<long long>(value) * x % M;
        return *this;
    }
    int get() { return value; }
};

