    }
    for(auto& v : cnt) sort(v.begin(), v.end());
    long long res = 1;
    for(int i=2;i<=N;i++) res = (res * i) % MOD;
    for(int i=1;i<cnt.size();i++){
        for(int j=0;j<2;j++){
            if(cnt[i][j] > cnt[i-1][j]) res = (res * (cnt[i][j+1] - cnt[i-1][j])) % MOD;
        }
    }
    cout << res << endl;
}

