ll ext_gcd(ll a,ll b,ll &x,ll &y){
    if(b==0){x=1;y=0;return a;}
    ll q=a/b, g=ext_gcd(b,a-q*b,x,y), z=x-q*y;
    x=y; y=z;
    return g;
}
ll inv(ll a,ll p=mod){
    ll x,y;
    ext_gcd(a,p,x,y);
    return (x+p)%p;
}
int main(){
    int n;
    scanf("%d%s",&n,s);
    factorial[0]=1;
    for(int i=1;i<=n;++i){
        factorial[i]=(factorial[i-1]*static_cast<ll>(i))%mod;
        invfact[i]=inv(factorial[i]);
    }
    //ordering
    int r_itr=0,g_itr=0,b_itr=0,multicount=1;
    ll ans=factorial[n];
    while(true){
        bool is_multicount=true;
        while(r_itr<3*n && s[r_itr]!='R'){
            r_itr++;
            is_multicount=false;
        }
        while(g_itr<3*n && s[g_itr]!='G'){
