        }
        while(b_itr<3*n && s[b_itr]!='B'){
            b_itr++;
            is_multicount=false;
        }
        if(is_multicount)++multicount;
        bool itr_end = r_itr>=3*n || g_itr>=3*n || b_itr>=3*n;
        if(!is_multicount || itr_end){
            ans=(ans*invfact[multicount])%mod;
