#define mod 998244353

ll fact_mod(ll n) {
    ll ret = 1;
    for (ll i=1; i<=n; i++) {
        ret *= i;
        ret %= mod;
    }
    return ret;
}

int main() {
    int n = 0;
    cin >> n;
    string s = "";
    cin >> s;
    int step = 0;
    ll ans = 1;
    char one = 0, two = 0, three = 0;
    ll cnt1 = 0, cnt2 = 0, cnt22 = 0, cnt3 = 0;
    vector<bool> check(3*n, false);
    int next = 0;
    vector<vector<int>> pla(3);
    for (int i=0; i<3*n; i++) {
        if (check.at(i)) {
            continue;
        }
        if (step == 0) {
            one = s.at(i);
            cnt1++;
            pla.at(0).push_back(i);
            step = 1;
        }
        else if (step == 1) {
            if (s.at(i) == one) {
                cnt1++;
                pla.at(0).push_back(i);
            }
            else {
                two = s.at(i);
                cnt2++;
                next = i;
                pla.at(1).push_back(i);
                step = 2;
            }
        }
        else if (step == 2) {
            if (s.at(i) == one) {
                continue;
            }
            else if (s.at(i) == two) {
                cnt2++;
                pla.at(1).push_back(i);
                if (cnt2 == cnt1) {
                    step = 3;
                }
            }
            else {
                step = 3;
                three = s.at(i);
                cnt3++;
                pla.at(2).push_back(i);
            }
        }
        else if (step == 3) {
            if (s.at(i) == one) {
                continue;
            }
            else if (s.at(i) == two) {
                if (cnt2 + cnt22 < cnt1) {
                    cnt22++;
                    pla.at(1).push_back(i);
                }
            }
            else {
                cnt3++;
                pla.at(2).push_back(i);
                if (cnt3 == cnt1) {
                    if (cnt22 + cnt2 == cnt1) {
                        ans *= fact_mod(cnt1);
                        ans %= mod;
                        ans *= fact_mod(cnt2);
                        ans %= mod;
                        for (int j=0; j<3; j++) {
                            for (int x : pla.at(j)) {
                                check.at(x) = true;
                            }
                        }
                        pla = vector<vector<int>>(3);
                        cnt1 = cnt2 = cnt22 = cnt3 = step = 0;
                        for (int j=0; j<3*n; j++) {
                            if (!check.at(j)) {
                                i = j-1;
                                break;
                            }
                        }
                        // i = next;
                    }
                    else {
                        ans *= fact_mod(cnt2+cnt22);
                        ans %= mod;
                        ans *= fact_mod(cnt2);
                        ans %= mod;
                        for (int j=0; j<3; j++) {
                            for (int k=0; k<cnt2+cnt22; k++) {
                                check.at(pla.at(j).at(k)) = true;
                            }
                        }
                        pla = vector<vector<int>>(3);
                        cnt1 = cnt2 = cnt22 = cnt3 = step = 0;
                        one = two = three = 0;
                        for (int j=0; i<3*n; j++) {
                            if (!check.at(j)) {
                                i = j-1;
                                break;
                            }
                        }
                        // i = next - (cnt1 - (cnt2 + cnt22) + 1);
                    }
                }
            }
        }
    }
    cout << ans * fact_mod(n) % mod << endl;
    return 0;
}

