  std::vector<int> count(8);
  const auto encode = [](char c) {
    if (c == 'R') return 1;
    if (c == 'G') return 2;
    if (c == 'B') return 4;
    return -421;
  };
  modint ans(1);
  for (const auto c: S) {
    int t = encode(c);
    if (count[7 ^ t] > 0) {
      ans *= count[7 ^ t];
      --count[7 ^ t];
    }
    else {
      bool found = false;
      for (int i: revrange(0, 3)) {
        int bit = (1 << i);
        if (count[bit] > 0 && t != bit) {
          ans *= count[bit];
          ++count[bit | t];
          --count[bit];
          found = true;
        }
      }
      if (!found) {
        ++count[t];
      }
    }
  }
  for (modint i: range(1, N + 1)) {
    ans *= i;
  }
  std::cout << ans << '\n';
  return 0;
}

