#define l_ength size

void mul_mod(ll& a, ll b){
	a *= b;
	a %= MOD;
}

void add_mod(ll& a, ll b){
	a = (a<MOD)?a:(a-MOD);
	b = (b<MOD)?b:(b-MOD);
	a += b;
	a = (a<MOD)?a:(a-MOD);
}

ll fc[334334]={1ll},nv[334334]={1ll};
vector<int> r,g,b;
vector<P> v[6];

ll rwpw(ll a, ll p){
	ll ret = 1ll;
	while(p){
		if(p&1){
			mul_mod(ret,a);
		}
		mul_mod(a,a);
		p >>= 1;
	}
	return ret;
}

int main(void){
	ll n,i,j,ans=1ll,x,y,z;
	string s;
	cin >> n;
	cin >> s;
	for(i=0; i<n*3; ++i){
		fc[i+1] = fc[i]; mul_mod(fc[i+1],i+1);
		nv[i+1] = rwpw(fc[i+1],MOD-2);
		switch(s[i]){
			case 'R':
			r.push_back(i);
			break;

			case 'G':
			g.push_back(i);
			break;

			case 'B':
			b.push_back(i);
			break;
		}
	}
	for(i=0; i<n; ++i){
		x = min({r[i],g[i],b[i]});
		z = max({r[i],g[i],b[i]});
		y = r[i]+g[i]+b[i]-x-z;
		if(x == r[i] && z == g[i]){
			j = 0;
		}else if(x == r[i] && z == b[i]){
			j = 1;
		}else if(x == g[i] && z == r[i]){
			j = 2;
		}else if(x == g[i] && z == b[i]){
			j = 3;
		}else if(x == b[i] && z == r[i]){
			j = 4;
		}else if(x == b[i] && z == g[i]){
			j = 5;
		}
		v[j].push_back(P(x,0));
		v[j].push_back(P(y,1));
		v[j].push_back(P(z,2));
	}
	for(j=0; j<6; ++j){
		sort(v[j].begin(),v[j].end());
		x = 0; y = 0; z = 0;
		for(i=0; i<v[j].l_ength(); ++i){
			switch(v[j][i].second){
				case 0:
				++x;
				break;

				case 1:
				mul_mod(ans,x);
				--x; ++y;
				break;

				case 2:
				mul_mod(ans,y);
				--y; ++z;
				break;
			}
		}
	}
	mul_mod(ans,fc[n]);
	cout << ans << endl;
	return 0;
}

