constexpr int MOD = 998244353;

ll modinv(ll a) {
    ll b = MOD, u = 1, v = 0;
    while (b) {
        ll t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= MOD;
    if (u < 0) u += MOD;
    return u;
}

int main(void){
    Cin(int, n);
    Cin(string, s);

    vc<int> ic[3];
    For(i, 3*n){
        (s[i] == 'R' ? ic[0] : s[i] == 'G' ? ic[1] : ic[2]).push_back(i);
    }
    For(i, 3) ic[i].push_back(3*n);

    vc<int> ps[3], pt[3];
    For(i, 3) ps[i] = vc<int>(n), pt[i] = vc<int>(n);
    For(i, n){
        for(int pl = 0; pl < 3; pl ++){
            for(int pc = 0; pc < 3; pc ++){
                for(int pr = 0; pr < 3; pr ++){
                    if(ic[pl][i] < ic[pc][i] && ic[pc][i] < ic[pr][i]){
                        ps[pl][i] = 0;
                        ps[pc][i] = 1;
                        ps[pr][i] = 2;
                        pt[0][i] = pl;
                        pt[1][i] = pc;
                        pt[2][i] = pr;
                        goto next;
                    }
                }
            }
        }
        next:;
    }

    vc<int> ic2[3], ic3[3];
    For(i, n) For(j, 3){
        if(ps[j][i] == 0) continue;
        ic2[j].push_back(ic[j][i]);
        if(ps[j][i] == 1) continue;
        ic3[j].push_back(ic[j][i]);
    }
    For(i, 3) ic2[i].push_back(3*n), ic3[i].push_back(3*n);

    /*
    For(i, 3) Couts(ps[i]);  // ps[i][j] : 色 i の j-RGB における位置関係
    For(i, 3) Couts(pt[i]);  // pt[i][j] : 位置関係 i の j-RGB における色
    For(i, 3) Couts(ic[i]);  // ic[i][j] : 色 i の j-RGB における座標
    For(i, 3) Couts(ic2[i]);
    For(i, 3) Couts(ic3[i]);
    */

    ll ans = 1;
    For(i, n){
        ans = ans * (i+1) % MOD;
        int pl = pt[0][i];
        int pm = pt[1][i];
        int pr = pt[2][i];

        int ulm = *upper_bound(ic[pm].begin(), ic[pm].end(), ic[pl][i]);
        int ulr = *upper_bound(ic[pr].begin(), ic[pr].end(), ic[pl][i]);
        int uml = *upper_bound(ic[pl].begin(), ic[pl].end(), ic[pm][i]);
        int umr = *upper_bound(ic[pr].begin(), ic[pr].end(), ic[pm][i]);
        int url = *upper_bound(ic[pl].begin(), ic[pl].end(), ic[pr][i]);
        int urm = *upper_bound(ic[pm].begin(), ic[pm].end(), ic[pr][i]);

        auto itl = ic[pl].begin() + i;
        int nl = distance(itl, lower_bound(itl, ic[pl].end(), min(ulm, ulr)));
        auto itm = lower_bound(Range(ic2[pm]), ic[pm][i]);
        int nm = distance(itm, lower_bound(itm, ic2[pm].end(), min(uml, umr)));
        auto itr = lower_bound(Range(ic3[pr]), ic[pr][i]);
        int nr = distance(itr, lower_bound(itr, ic3[pr].end(), min(url, urm)));

        //Cout(nl, " ", nm, " ", nr);

        int m = min({nl, nm, nr});
        ans = ans * nl % MOD * nm % MOD * nr % MOD * modinv(m) % MOD;
    }
    Cout(ans);
}

