typedef long long ll;

const ll M = 998244353;

vector<ll> fac(300001); //n!(mod M)
vector<ll> ifac(300001); //k!^{M-2} (mod M)
//a,bの範囲的にこれだけ配列を用意していけば十分

ll mpow(ll x, ll n){ //x^n(mod M) ←普通にpow(x,n)では溢れてしまうため，随時mod計算
    ll ans = 1;
    while(n != 0){
        if(n&1) ans = ans*x % M;
        x = x*x % M;
        n = n >> 1;
    }
    return ans;
}

ll comb(ll a, ll b){ //aCbをmod計算
    if(a == 0 && b == 0)return 1;
    if(a < b || a < 0)return 0;
    ll tmp = ifac[a-b]* ifac[b] % M;
    return tmp * fac[a] % M;
}


int main(){
    fac[0] = 1;
    ifac[0] = 1;
    for(ll i = 0; i<300000; i++){
        fac[i+1] = fac[i]*(i+1) % M; // n!(mod M)
        ifac[i+1] = ifac[i]*mpow(i+1, M-2) % M; // k!^{M-2} (mod M) ←累乗にmpowを採用
    }

    int N;
    cin >> N;
    string S;
    cin >> S;
    int K=0;

    int R[3]={0,0,0},G[3]={0,0,0},B[3]={0,0,0};

    for (size_t i = 0; i < N; i++)
    {
        if(S[i]=='R') R[0]++;
        if(S[i]=='G') G[0]++;
        if(S[i]=='B') B[0]++;
    }

    for (size_t i = N; i < 2*N; i++)
    {
        if(S[i]=='R') R[1]++;
        if(S[i]=='G') G[1]++;
        if(S[i]=='B') B[1]++;
    }

    for (size_t i = 2*N; i < 3*N; i++)
    {
        if(S[i]=='R') R[2]++;
        if(S[i]=='G') G[2]++;
        if(S[i]=='B') B[2]++;
    }

    const int RGB=0,RBG=1,GBR=2,GRB=3,BRG=4,BGR=5;

    ll total=0;
    int g[6];


    for(g[RGB]=0; g[RGB]<=R[0]; g[RGB]++){
        g[RBG] = R[0] - g[RGB];
        g[BGR] = G[1] - g[RGB];
        g[GRB] = B[2] - g[RGB];
        g[GBR] = G[0] - g[GRB];
        g[BRG] = R[1] - g[GRB]; 
        bool flag = false;
        for(int k=0;k<6;k++){
            if(g[k]<0) flag=true;
        }
        for(int k=0;k<6;k++){
            cerr << g[k] << " ";
        }
        cerr << endl;
        if(flag) continue;

        int remain = N;
        ll L=1;
        for (size_t i = 0; i < 6; i++)
        {
            L*=comb(remain,g[i]);
            remain -= g[i];
            L %= M;
        }
        cerr << L << endl;
        for(int k=0;k<3;k++){
            for (ll j = R[k]; j >0; j--)
            {
                L *= j;
                L %= M;
            }
            for (ll j = G[k]; j >0; j--)
            {
                L *= j;
                L %= M;
            }
            for (ll j = B[k]; j >0; j--)
            {
                L *= j;
                L %= M;
            }
        }
        total += L;
        total %= M;
    }

    cout << total << endl;    
    return 0;
}

