signed main() {
    int n; cin >> n;
    vector<int> a(n); REP (i, n) cin >> a[i];
    vector<int> b(n); REP (i, n) cin >> b[i];
    queue<int> q;
    int cnt = 0;
    auto is_top = [&](int i) {
        int x = b[(i - 1 + n) % n];
        int y = b[i];
        int z = b[(i + 1) % n];
        return y > x + z;
    };
    REP (i, n) {
        if (is_top(i)) q.push(i);
    }
    while (!q.empty()) {
        int i = q.front(); q.pop();
        if (b[i] == a[i]) continue;
        if (b[i] < a[i]) no();
        int sum = b[(i - 1 + n) % n] + b[(i + 1) % n];
        if (b[i] % sum < a[i]) {
            int dif = b[i] - a[i];
            if (dif % sum) no();
            cnt += dif / sum;
            b[i] = a[i];
        } else {
            if (b[i] < sum) no();
            cnt += b[i] / sum;
            b[i] %= sum;
            if (is_top((i - 1 + n) % n)) q.push((i - 1 + n) % n);
            if (is_top((i + 1) % n)) q.push((i + 1) % n);
        }
    }
    REP (i, n) {
        if (a[i] != b[i]) no();
    }
    cout << cnt << endl;
}

