					ans*=start*mid;
					start--;mid--;
				}
				end-=t;
				//start-=t;mid-=t;end-=t;
				if(start==0){
					start=mid;
					startchar=midchar;
					midchar='x';
				}
				if(midchar==0){
					mid=end;
					midchar=endchar;
				}
				f(r,g,b,run[i]);
