#define REP(i, n) for (int i = 0; i < (n); i++)
#define RREP(i, n) for (int i = (n) - 1; i >= 0; i--)
#define FOR(i, a, b) for (int i = (a); i < (b); i++)
#define RFOR(i, a, b) for (int i = (a); i > (b); i--)
#define ALL(a) (a).begin(), (a).end()
#define MOD 998244353

typedef enum { R, G, B } color;

typedef struct range {
    pair<ll, color> l, m, u;
} range;

ll fact[100011];

void init(ll n) {
    fact[0] = 1;
    REP(i, n) fact[i + 1] = fact[i] * (i + 1) % MOD;
}

ll index[100000][3];
range ran[100000];

int main() {
    init(100010);
    ll N;
    string S;
    cin >> N >> S;

    ll red = 0, green = 0, blue = 0;
    REP(i, N * 3) {
        if (S[i] == 'R') index[red++][0] = i;
        else if (S[i] == 'G') index[green++][1] = i;
        else index[blue++][2] = i;
    }

    REP(i, N) {
        vector<ll> vi = { index[i][0], index[i][1], index[i][2] };
        sort(ALL(vi));
        if (index[i][0] == vi[0]) {
            if (index[i][1] == vi[1]) ran[i] = {{vi[0], R}, {vi[1], G}, {vi[2], B}};
            else ran[i] = {{vi[0], R}, {vi[1], B}, {vi[2], G}};
        }
        else if (index[i][1] == vi[0]) {
            if (index[i][0] == vi[1]) ran[i] = {{vi[0], G}, {vi[1], R}, {vi[2], B}};
            else ran[i] = {{vi[0], G}, {vi[1], B}, {vi[2], R}};
        }
        else {
            if (index[i][0] == vi[1]) ran[i] = {{vi[0], B}, {vi[1], R}, {vi[2], G}};
            else ran[i] = {{vi[0], B}, {vi[1], G}, {vi[2], R}};
        }
    }
    // REP(i, N) {
    //     range ra = ran[i];
    //     cout << ra.l.first << "," << ra.l.second << ":" << ra.m.first << "," << ra.m.second << ":" << ra.u.first << "," << ra.u.second << endl;
    // }

    ll ans = 1;
    for (ll i = 0; i < N - 1; i++) {
        color c = ran[i].l.second;
        ll m = ran[i].m.first;

        ll j = i + 1;
        while (j < N) {
            if (ran[j].l.second == c && ran[j].l.first < m) j++;
            else break;
        }
        ans = ans * fact[j - i] % MOD;
        i = j - 1;
    }
    for (ll i = N; i > 0; i--) {
        color c = ran[i].u.second;
        ll m = ran[i].m.first;

        ll j = i - 1;
        while (j >= 0) {
            if (ran[j].u.second == c && ran[j].u.first > m) j--;
            else break;
        }
        ans = ans * fact[i - j] % MOD;
        i = j + 1;
    }

    cout << ans * fact[N] % MOD << endl;
    return 0;
}

