void fracinvfrac(ll n) {
    frac = vector<Mint>(n + 1);
    invfrac = vector<Mint>(n + 1);
    frac[0] = 1;
    for (int i = 1; i <= n; i++) {
        frac[i] = frac[i - 1] * i;
    }
    invfrac[n] = (Mint)1 / frac[n];
    for (int i = n - 1; i >= 0; i--) {
        invfrac[i] = invfrac[i + 1] * (i + 1);
    }
}

