#include <bits/stdc++.h>

using namespace std;

const int RIGHT  = 0;
const int CENTER = 1;
const int LEFT   = 2;

const int64_t MOD = 998244353;

int64_t F(int n) {
  static unordered_map<int, int64_t> cache;
  if (cache.find(n) != cache.end()) {
    return cache[n];
  }

  if (n <= 1) {
    return cache[n] = 1;
  } else {
    return cache[n] = F(n - 1) * n % MOD;
  }
}

int main() {
  int64_t L;
  cin >> L;
  string S;
  cin >> S;

  unordered_map<char, int64_t> m;
  int64_t result = F(L);
  int64_t openL = 0;
  int64_t openC = 0;

  string RGB = "RGB";
  for (char c : S) {
    int current_pos = 0;
    for (int i = 0; i < 3; i++) {
      char other = RGB[i];
      if (c == other) continue;
      if (m[c] >= m[other]) current_pos++;
    }
    m[c]++;

    if (current_pos == LEFT) {
      openL += 1;
    } else if (current_pos == CENTER) {
      openC += 1;
      result *= openL;
      result %= MOD;
      openL--;
    } else {
      result *= openC;
      result %= MOD;
      openC--;
    }
  }

  cout << result << endl;

  return 0;
}

