        vector<Int> R, G, B;
        for (int i = 0; i < 3 * N; ++i) {
            if (S[i] == 'R') {
                R.push_back(i);
            } else if (S[i] == 'G') {
                G.push_back(i);
            } else {
                B.push_back(i);
            }
        }

        vector<Int> X, Y, Z;
        string T(' ', 3 * N);
        for (int i = 0; i < N; ++i) {
            vector<Int> rgb = {R[i], G[i], B[i]};
            sort(all(rgb));
            X.push_back(rgb[0]);
            Y.push_back(rgb[1]);
            Z.push_back(rgb[2]);
            T[rgb[0]] = 'x';
            T[rgb[1]] = 'y';
            T[rgb[2]] = 'z';
        }

        vector<Int> cntL(3 * N), cntR(3 * N);
        for (int i = 0; i < 3 * N; ++i) {
            if (i > 0) cntL[i] = cntL[i - 1];
            if (T[i] == 'x') {
                cntL[i]++;
            } else if (T[i] == 'y') {
                cntL[i]--;
            }

            Int ri = 3 * N - i - 1;
            if (ri < 3 * N - 1) {
                cntR[ri] = cntR[ri + 1];
            }
            if (T[ri] == 'z') {
                cntR[ri]++;
            } else if (T[ri] == 'y') {
                cntR[ri]--;
            }
        }


        Mint ans = 1;
        for (int i = 1; i <= N; ++i) {
            ans *= i;
        }
        for (int i = 0; i < N; ++i) {
            Mint tmp = Mint(cntL[Y[i] - 1]) * Mint(cntR[Y[i] + 1]);
            ans *= tmp;
        }
        cout << ans.value() << endl;


    }
};


