		vector<int> locs({pos[0][i], pos[1][i], pos[2][i]});
		sort(locs.begin(), locs.end());
		probs[0][V[locs[0]]].push_back(locs[0]);
		probs[0][V[locs[0]]].push_back(locs[1]);

		probs[1][V[locs[2]]].push_back(locs[1]);
		probs[1][V[locs[2]]].push_back(locs[2]);
	}

	num ans = 1;
	for (int i = 1; i <= N; i++) ans *= i;

	for (int z = 0; z < 2; z++) {
		for (int a = 0; a < 3; a++) {
			sort(probs[z][a].begin(), probs[z][a].end());
			int nLo = 0;
			for (int i : probs[z][a]) {
				if ((V[i] == a) == (z == 0)) {
					nLo ++;
				} else {
					assert(nLo > 0);
					ans *= nLo;
					nLo --;
				}
			}
		}
	}
	cout << ans << '\n';

	return 0;
}

