  int M = S.size();
  S.pb('x');

  vector<ll> fact(N + 1);
  fact[1] = 1;
  repp(i, 2, N) {
    fact[i] = fact[i - 1] * i;
    fact[i] %= MOD;
  }

  vector<int> rgb(3);
  map<char, int> m;
  m['R'] = 0;
  m['G'] = 1;
  m['B'] = 2;

  mint ans = 1;
  rep(i, M) {
    char now = S[i];
    char next = S[i + 1];

    rgb[m[now]]++;
    int x = rgb[m[now]];
    int y = rgb[(m[now] + 1) % 3];
    int z = rgb[(m[now] + 2) % 3];
    if (y < z)
      swap(y, z);
    if (now != next) {
      if (x > y && x > z) {
        int temp = x - max(y, z);
        ans *= fact[temp];
      } else if (x <= y && x > z) {
        int temp = x - z;
        ans *= fact[temp];
      }
    }
  }
  ans *= fact[N];
  cout << ans.x << endl;
}

