void solve() {
	int n;
    string s; cin >> n >> s;
    vector<int> cnt(3 * n);
    bc.init(300300);
    int cntb = 0, cntg = 0, cntr = 0;
    map<int, int> mp;
    vector<int> a(3 * n);
    rep(i, 3 * n) {
        if(s[i] == 'B') {
            cntb ++;
            cnt[i] = cntb;
        } else if(s[i] == 'G') {
            cntg ++;
            cnt[i] = cntg;
        } else {
            cntr ++;
            cnt[i] = cntr;
        }
        mp[cnt[i]] ++;
        a[i] = mp[cnt[i]];
    }
    mint ans = bc.fact(n);
    int cnt1 = 0, cnt2 = 0;
    rep(i, 3 * n) {
        if(a[i] == 1) {
            cnt1 ++;
        } else if(a[i] == 2) {
            ans *= (mint)cnt1;
            cnt1 --;
            cnt2 ++;
        } else {
            ans *= (mint)cnt2;
            cnt2 --;
        }
    }
    cout << ans << endl;
}

