char s[MAXN];

int n, len;




int main(int argc, char const *argv[])
{
    scanf("%d%s", &n, s);
    // printf("%d %s\n", n, s);
    len = n * 3;
    // dbg(n, len);
    for (int i=0; i<len; ++i) {
        if (s[i] == 'R') r.push_back(i);
        else if (s[i] == 'G') g.push_back(i);
        else if (s[i] == 'B') b.push_back(i);
    }
    low.resize(n);
    high.resize(n);
    mid.resize(n);
    for (int i=0; i<n; ++i) {
        vi tmp = {r[i], g[i], b[i]};
        sort(tmp.begin(), tmp.end());
        low[i] = tmp[0];
        mid[i] = tmp[1];
        high[i] = tmp[2];
    }


    LL ans = 1;
    for (int i=1; i<=n; ++i)
        ans = ans * i % MOD;
    int j = 0;
    for (int i=0; i<n; ++i) {
        while (j+1<n && low[j+1] <= mid[i]) ++j;
        ans = ans * (j-i+1) % MOD;
    }
    j = 0;
    for (int i=0; i<n; ++i) {
        while (j+1<n && mid[j+1] <= high[i]) ++j;
        ans = ans * (j-i+1) % MOD;
    }
    printf("%lld\n", ans);
    return 0;
}

