const int N = 3e5 + 10;

const ll M = 1e9 + 7;

ll ans = 1;
int n;
string s;

map<set<int>, int> cnt[3];

ll pw(ll a, ll n = M - 2) {
    ll ret = 1;
    while (n) {
        if (n & 1) ret = ret * a % M;
        a = a * a % M;
        n >>= 1;
    }

    return ret;
}

void smain() {

    cin >> n;
    cin >> s;
    for (auto c : s) {
        bool did = false;
        int zc = -1;
        set<int> key;
        for (int z = 2; !did && z >= 1; --z) {
            for (auto item : cnt[z]) {
                if (!item.first.count(c)) {
                    key = item.first;
                    zc = z;
                    did = true;
                    break;
                }
            }
        }
        if (did) {
            ans = ans * cnt[zc][key] % M;
            cnt[zc][key]--;
            if (cnt[zc][key] == 0) cnt[zc].erase(key);
            if (zc != 2) {
                key.insert(c);
                cnt[zc + 1][key]++;
            }
        } else {
            key.insert(c);
            cnt[1][key]++;
        }
    }
    for (int i = 1; i <= n; ++i) {
        ans = ans * i % M;
    }
    cout << ans;
}

