        auto sorted = count;
        sort(begin(sorted), end(sorted));
        if (sorted[2] != prev[2]) {
            result = result * sorted[2] % MOD;
        } else if (sorted[0] != prev[0]) {
            result = result * (sorted[1] - sorted[0] + 1) % MOD;
        } else {
            result = result * (sorted[2] - sorted[1] + 1) % MOD;
        }
        swap(prev, sorted);
    }
    cout << result;
    return 0;
}

