    ll idxr = 0, idxg = 0, idxb = 0;
    vector<ll> type(3*n);
    REP(i, 3*n) {
        if(s[i]=='R') type[i]=idxr++;
        else if(s[i]=='G') type[i]=idxg++;
        else if(s[i]=='B') type[i]=idxb++;
    }

    // 両端が対応する真ん中のやつが何か
    vector<vector<ll>> v(n);
    REP(i, 3*n) v[type[i]].push_back(i);

    vector<ll> cntr(3*n), cntg(3*n), cntb(3*n);
    REP(i, 3*n) {
        if(s[i]=='R') cntr[i] = 1;
        else if(s[i]=='G') cntg[i] = 1;
        else if(s[i]=='B') cntb[i] = 1;
    }
    FOR(i, 1, 3*n) {
        cntr[i] += cntr[i-1];
        cntg[i] += cntg[i-1];
        cntb[i] += cntb[i-1];
    }

    mint ret = 1;
    REP(i, n) {
        // [v[i][0],v[i][1]] に存在する左端でs[v[i][0]]と同じやつの数
        if(s[v[i][0]]=='R') {
            ret *= cntr[v[i][1]] - (v[i][0]==0?0:cntr[v[i][0]-1]);
        } else if(s[v[i][0]]=='G') {
            ret *= cntg[v[i][1]] - (v[i][0]==0?0:cntg[v[i][0]-1]);
        } else if(s[v[i][0]]=='B') {
            ret *= cntb[v[i][1]] - (v[i][0]==0?0:cntb[v[i][0]-1]);
        }
        // [v[i][1],v[i][2]] に存在する右端でs[v[i][2]]と同じやつの数
        if(s[v[i][2]]=='R') {
            ret *= cntr[v[i][2]] - (v[i][1]==0?0:cntr[v[i][1]-1]);
        } else if(s[v[i][2]]=='G') {
            ret *= cntg[v[i][2]] - (v[i][1]==0?0:cntg[v[i][1]-1]);
        } else if(s[v[i][2]]=='B') {
            ret *= cntb[v[i][2]] - (v[i][1]==0?0:cntb[v[i][1]-1]);
        }
    }
    REP(i, n) ret *= i+1;
    cout << ret << endl;

    return 0;
}

