        a = b = c = 0;
    }
};
segment dat[nsz + 5];

void inline upd(int id, int val) {
    if (!dat[id].a) {
        dat[id].a = val;
    } else if (!dat[id].b) {
        dat[id].b = val;
    } else if (!dat[id].c) {
        dat[id].c = val;
    }
}

int main() {
    ios_base::sync_with_stdio(0);
