        if (s[i] == 'R') {
            a[i] = ++cnt[0];
            upd(cnt[0], i);
        } else if (s[i] == 'G') {
            a[i] = ++cnt[1];
            upd(cnt[1], i);
        } else if (s[i] == 'B') {
            a[i] = ++cnt[2];
            upd(cnt[2], i);
