int binpow(int a,int b){
    if(b == 0)return 1;
    if(b % 2)return a * 1ll * binpow(a , b - 1) % mod;
    int t = binpow(a , b / 2);
    return t * 1ll * t % mod;
}

int C(int n,int k){
    int answ = fact[n] * 1ll * rf[k] % mod;
    answ = answ * 1ll * rf[n - k] % mod;
    return answ;
}

