int main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	ll N;
	cin >> N;

	string S;
	cin >> S;

	vector<ll> Rs, Gs, Bs;
	Rs.reserve(N);
	Gs.reserve(N);
	Bs.reserve(N);
	for (ll i = 0; i < N * 3; ++i)
	{
		if (S[i] == 'R')
		{
			Rs.push_back(i);
		}
		else if (S[i] == 'G')
		{
			Gs.push_back(i);
		}
		else if (S[i] == 'B')
		{
			Bs.push_back(i);
		}
	}

	vector<ll> as(N), cs(N);
	vector<bool> is_bs(N * 3, true);
	for (ll i = 0; i < N; ++i)
	{
		ll a = min({ Rs[i], Gs[i], Bs[i] });
		ll c = max({ Rs[i], Gs[i], Bs[i] });
		as[i] = a;
		cs[i] = c;
		is_bs[a] = false;
		is_bs[c] = false;
	}

	rll res = 1;
	ll count = 0;
	for (ll i = 0; i < N * 3; ++i)
	{
		if (!is_bs[i])
		{
			continue;
		}
		res *= distance(as.begin(), upper_bound(as.begin(), as.end(), i)) - count;
		++count;
	}

	count = 0;
	for (ll i = N * 3 - 1; i >= 0; --i)
	{
		if (!is_bs[i])
		{
			continue;
		}
		res *= distance(upper_bound(cs.begin(), cs.end(), i), cs.end()) - count;
		++count;
	}

	for (ll i = 1; i <= N; ++i)
	{
		res *= i;
	}

	cout << res << endl;

	return 0;
}

