	for (int i = 0; i < n; i++) {
		seg a, b, c;
		a.add(pos[0][i]);
		b.add(pos[1][i]);
		c.add(pos[2][i]);
		int r = i;
		while (r + 1 < n) {
			seg na = a;
			seg nb = b;
			seg nc = c;
			na.add(pos[0][r + 1]);
			nb.add(pos[1][r + 1]);
			nc.add(pos[2][r + 1]);
			if (!na.intr(nb) && !na.intr(nc) && !nb.intr(nc)) {
				r++;
				a = na;
				b = nb;
				c = nc;
			} else {
				break;
			}
		}
		int len = r - i + 1;
		ans = mul(ans, binpow(fact[len], 2));
		cnt++;
		i = r;
	}
	for (int i = 0; i + 1 < n; i++) {
		int any = 0;
		if (who(pos[0][i], pos[1][i], pos[2][i]) == who(pos[0][i], pos[1][i + 1], pos[2][i + 1]) && who(pos[0][i + 1], pos[1][i + 1], pos[2][i + 1]) == who(pos[0][i + 1], pos[1][i], pos[2][i])) {
			any++;
		}
		if (who(pos[1][i], pos[0][i], pos[2][i]) == who(pos[1][i], pos[0][i + 1], pos[2][i + 1]) && who(pos[1][i + 1], pos[0][i + 1], pos[2][i + 1]) == who(pos[1][i + 1], pos[0][i], pos[2][i])) {
			any++;
		}
		if (who(pos[2][i], pos[1][i], pos[0][i]) == who(pos[2][i], pos[1][i + 1], pos[0][i + 1]) && who(pos[2][i + 1], pos[1][i + 1], pos[0][i + 1]) == who(pos[2][i + 1], pos[1][i], pos[0][i])) {
			any++;
		}
		if (any < 1) {
			ans = mul(ans, 2);
		}
	}
	int res = mul(ans, fact[n]);
	cout << res << '\n';
}

