using namespace std;
#define int64 long long

const int MODULO = 998244353;

namespace Mod {
	int product(int x, int y) {
		return (int64)x * y % MODULO;
	}
}

struct Group {
	vector<int> A, B, C;
};

Group groups[3][3];
int nTuple;

int computeAlignment(const vector<int> &A, const vector<int> &B) {
	int n = A.size();

	vector<int> rightBound(n);
	for (int i = 0; i < n; ++i) {
		int j = (i > 0 ? rightBound[i - 1] : 0);
		while (j < n && A[j] < B[i]) ++j;
		rightBound[i] = j;
	}

	int result = 1;
	int cnt = 0;
	int j = n - 1;
	for (int i = n - 1; i >= 0; --i) {
		while (j >= 0 && rightBound[j] > i) {
			++cnt;
			--j;
		}

		result = Mod::product(result, cnt);
		--cnt;
		assert(cnt >= 0);
	}

	return result;
}

int computeGroupShuffle(const Group &group) {
	if (group.A.empty()) return 1;

	int s = computeAlignment(group.A, group.B);
	s = Mod::product(s, computeAlignment(group.B, group.C));
	return s;
}

void outerInit() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	auto fi = new ifstream("test.inp");
	if (*fi) {
		cin.rdbuf(fi->rdbuf());
	}
}

void readData() {
	string S;
	cin >> nTuple >> S;

	deque<int> R, G, B;
	vector<pair<int, int>> tmp;
	for (int i = 0; i < S.size(); ++i) {
		if (S[i] == 'R') R.push_back(i);
		if (S[i] == 'G') G.push_back(i);
		if (S[i] == 'B') B.push_back(i);

		if (!R.empty() && !G.empty() && !B.empty()) {
			tmp.clear();
			tmp.emplace_back(R.front(), 0);
			tmp.emplace_back(G.front(), 1);
			tmp.emplace_back(B.front(), 2);
			sort(tmp.begin(), tmp.end());

			R.pop_front();
			G.pop_front();
			B.pop_front();

			int x = tmp.front().second;
			int y = tmp.back().second;
			groups[x][y].A.push_back(tmp[0].first);
			groups[x][y].B.push_back(tmp[1].first);
			groups[x][y].C.push_back(tmp[2].first);
		}
	}
	assert(R.empty() && G.empty() && B.empty());
}

void solveData() {
	int result = 1;
	for (int i = 1; i <= nTuple; ++i) {
		result = Mod::product(result, i);
	}

	for (int x = 0; x < 3; ++x) {
		for (int y = 0; y < 3; ++y) {
			result = Mod::product(result, computeGroupShuffle(groups[x][y]));
		}
	}

	cout << result << "\n";
}

int main() {
	outerInit();

	readData();
	solveData();
}

