char kind[3*MAXN+1];

int cnt1[3],cnt2[3];

int solve() {
	REP(j,3) prefsum[0][j]=0;
	REP(i,3*n) REP(j,3) prefsum[i+1][j]=prefsum[i][j]+(s[i]==CHARS[j]?1:0);
	REPE(i,3*n) { int mn=INT_MAX,mx=INT_MIN; REP(j,3) mn=min(mn,prefsum[i][j]),mx=max(mx,prefsum[i][j]); bal[i]=mx-mn; }
	//printf("bal:"); REPE(i,3*n) printf(" %d",bal[i]); puts("");
	REP(i,3*n) { int a=bal[i],b=bal[i+1]; assert(abs(a-b)<=1); kind[i]=a<b?'L':a>b?'R':'M'; } kind[3*n]='\0';
	//printf("kind: %s\n",kind);
	REP(j,3) cnt1[j]=cnt2[j]=0;
	int ret=1;
	REP(i,3*n) {
		int x=-1; REP(j,3) if(s[i]==CHARS[j]) x=j; assert(x!=-1); int y=0; while(y==x) ++y; int z=0; while(z==y||z==x) ++z;
		if(kind[i]=='L') ++cnt1[x];
		if(kind[i]=='M') { if(cnt1[y]==0) swap(y,z); assert(cnt1[y]>0&&cnt1[z]==0); ret=(ll)ret*cnt1[y]%MOD; --cnt1[y],++cnt2[z]; }
		if(kind[i]=='R') { assert(cnt2[x]>0); ret=(ll)ret*cnt2[x]%MOD; --cnt2[x]; }
	}
	REP(j,3) assert(cnt1[j]==0&&cnt2[j]==0);
	FORE(i,1,n) ret=(ll)ret*i%MOD;
	return ret;
}

