const ll mod = 998244353;
const ll base_num = (1 << 3) - 1;

ll cnt[1 << 3];

ll color_id(char c) {
    if(c == 'R') return 0;
    if(c == 'G') return 1;
    if(c == 'B') return 2;
    assert(false);
}

ll decide_idx(char c) {
    ll id = color_id(c);
    ll high = base_num ^ (1ll << id);
    if(cnt[high]) return high;
    for(ll i = 0; i <= 2; i++) {
        if(id == i) continue;
        ll mid = 1ll << i;
        if(cnt[mid]) return mid;
    }
    return 0;
}

int main() {
    ll N;
    string S;
    cin >> N >> S;
    ll ans = 1;
    for(char c : S) {
        ll id = color_id(c);
        ll idx = decide_idx(c);
        ll add_idx = idx | (1ll << id);
        if(idx == 0) {
            cnt[add_idx]++;
        } else {
            (ans *= cnt[idx]) %= mod;
            cnt[idx]--;
            cnt[add_idx]++;
        }
    }
    for(ll i = 1; i <= N; i++) (ans *= i) %= mod;
    cout << ans << endl;
    return 0;
}

