class BRGBBalls {
public:
    void solve(istream& in, ostream& out) {
        cin.tie(nullptr);
        ios::sync_with_stdio(false);
        int n;
        in>>n;
        string S;
        in>>S;
        vector<int> v(3*n);
        fr(i,3*n){
            if(S[i]=='G') v[i]=1;
            if(S[i]=='B') v[i]=2;
        }
        int a=0,b=0;
        vector<int> p(3),q(3);
        vector<bool> s(3*n),t(3*n);
        fr(i,3*n){
            //cout<<p[0]<<" "<<p[1]<<" "<<p[2]<<" "<<q[0]<<" "<<q[1]<<" "<<q[2]<<endl;
            if(q[v[i]]){
                t[i]=true;
                --q[v[i]];
            }
            else if(p[v[i]]){
                s[i]=true;
                ++p[v[i]];
            }
            else if(p[0]+p[1]+p[2]){
                int j;
                fr(k,3) if(p[k]) j=k;
                --p[j];
                ++q[3-j-v[i]];
            }
            else{
                s[i]=true;
                ++p[v[i]];
            }
        }
        modint ans(1);
        Fr(i,n) ans*=i;
        a=0;b=0;
        fr(i,3*n){
            if(s[i]) ++a;
            else if(t[i]) ans*=b,--b;
            else ans*=a,--a,++b;
        }
        out<<ans<<endl;
    }
};

