void makeNumSet()
{
	for (int i = 0 ; i < n ; i++)
	{
		posSet[i].nums[0] = rPos[i];
		posSet[i].nums[1] = gPos[i];
		posSet[i].nums[2] = bPos[i];

		sort(posSet[i].nums, posSet[i].nums + 3);
	}
