	for (int i = 0; i < 3 * n; i++) {
		for (int j = 0; j < 3; j++) {
			if (s[i] == uu[j]) {
				pos[j].push_back(i);
			}
		}
	}
	vector<vector<int>> help(3, vector<int> (n));
	for (int i = 0; i < n; i++) {
		help[0][i] = who(pos[0][i], pos[1][i], pos[2][i]);
		help[1][i] = who(pos[1][i], pos[2][i], pos[0][i]);
		help[2][i] = who(pos[2][i], pos[0][i], pos[2][i]);
	}
	vector<vector<int>> bl(3);
	int ans = fact[n];
	for (int i = 0; i < 3; i++) {
		for (int j = 0; j < n; j++) {
			int r = j;
			bl[i].push_back(j);
			while (r + 1 < n) {
				vector<int> o;
				for (int k = 0; k < 3; k++) {
					if (i != k) {
						o.push_back(k);
					}
