void solve() {
    map<char, vector<string>> f;
    f['R'].pb("BG");
    f['R'].pb("GB");
    f['B'].pb("RG");
    f['B'].pb("GR");
    f['G'].pb("BR");
    f['G'].pb("RB");
    int n; string s; cin >> n >> s;
    map<string, int> hs;
    int res = 1;
    for (char c : s) {
        int found = 0;
        for (string t : f[c]) {
            if (hs[t]) {
                res = mult(res, hs[t]);
                hs[t]--;
                found = 1;
                break;
            }
        }
        if (!found) {
            for (char e : {'R', 'G', 'B'}) {
                if (e ^ c) {
                    if (hs[string("") + e]) {
                        res = mult(res, hs[string("") + e]);
                        hs[string("") + e]--;
                        hs[string("") + e + c]++;
                        found = 1;
                        break;
                    }
                }
            }
        }
        if (!found) {
            hs[string("") + c]++;
        }
    }
    FOR(i, 1, n + 1) {
        res = mult(res, i);
    }
    cout << res << "\n";
}

