      str.push_back({c, 1});
    else
      str.back().n++;
  }

  const long MOD = 998244353;
  vector<long> fact(100001);
  fact[0] = 1;
  for (long i = 1; i < fact.size(); i++)
    fact[i] = fact[i-1]*i%MOD;
  vector<long> finv(fact.size());
  {
    long t = 1, u = fact.back();
    long p = MOD-2;
    while (p) {
      if (p&1) {
        t = t*u%MOD;
      }
      u=u*u%MOD;
      p >>= 1;
    }
    finv.back() = t;
  }
  for (long i = finv.size()-2; i >= 0; i--) {
    finv[i] = finv[i+1]*(i+1)%MOD;
  }
  auto perm = [&](int x, int y) {
    return fact[x]*finv[x-y]%MOD;
  };

  int cand = N;
  long ans = 0;
  unordered_map<char, long> cmap;
