MF sub(const vector<int>& a, const vector<int>& b) {
	vector<PP> v;
	for (int i : a) v.push_back(PP(i, 0));
	for (int i : b) v.push_back(PP(i, 1));
	sort(v.begin(), v.end());

	MF ret = 1;
	int cnt = 0;
	for (auto&& p : v) {
		if (p.second == 0) {
			++cnt;
		} else {
			ret *= cnt;
			--cnt;
		}
	}
	return ret;
}

