struct state {
	int n1[3];
	int n2[3];
	int n3;

	inline int count_total() const {
		return n1[0] + n1[1] + n1[2] + 2 * (n2[0] + n2[1] + n2[2]) + 3 * n3;
	}

	bool operator<(const state & S) const {
		return count_total() < S.count_total();
	}
};

int main() {
	cin.sync_with_stdio(0);
	cin.tie(0);
	cout << fixed << setprecision(10);
	int N;
	string S;
	cin >> N >> S;
	cat mod = 998244353;
	map<state, cat> dp;
	dp[{{0, 0, 0}, {0, 0, 0}, 0}] = 1;
	auto it = begin(dp);
	while(true) {
		int pos = it->ff.count_total();
		it->ss %= mod;
		if(pos == 3*N) break;
		int v = (S[pos] == 'R') ? 0 : ((S[pos] == 'B') ? 1 : 2);
		// add as 1
		if(it->ff.n1[0] + it->ff.n1[1] + it->ff.n1[2] == 0) {
			state s = it->ff;
			s.n1[v]++;
			assert(s.count_total()-pos == 1);
			if(it->ff.n2[v] == 0) dp[s] += it->ss;
		}
		else if(it->ff.n1[v] > 0) {
			state s = it->ff;
			s.n1[v]++;
			assert(s.count_total()-pos == 1);
			dp[s] += it->ss;
		}
		// add as 3
		if(it->ff.n2[v] > 0) {
			state s = it->ff;
			s.n2[v]--;
			s.n3++;
			assert(s.count_total()-pos == 1);
			dp[s] += it->ss * it->ff.n2[v] % mod;
		}
		else
		// add as 2 with sth else
		for(int k = 0; k < 3; k++) if(k != v && it->ff.n1[k] > 0) {
			state s = it->ff;
			s.n1[k]--;
			s.n2[3-v-k]++;
			dp[s] += it->ss * it->ff.n1[k] % mod;
		}
		it++;
	}
	cat fac = 1;
	for(int i = 2; i <= N; i++) fac = fac * i % mod;
	cout << dp[{{0, 0, 0}, {0, 0, 0}, N}] * fac % mod << "\n";
	return 0;
}

