using namespace std;

int main() {
	const Int MOD = 998244353;
	Int N;
	cin >> N;
	string s;
	cin >> s;

	vector<int> rx, gx, bx;
	for (int i = 0; i < s.size(); ++i) {
		if (s[i] == 'R') { rx.push_back(i); }
		if (s[i] == 'G') { gx.push_back(i); }
		if (s[i] == 'B') { bx.push_back(i); }
	}

	vector<int> a(N), b(N), c(N);
	for (int i = 0; i < N; ++i) {
		a[i] = min({ rx[i], gx[i], bx[i] });
		c[i] = max({ rx[i], gx[i], bx[i] });
		b[i] = rx[i] + gx[i] + bx[i] - a[i] - c[i];
	}

	Int ans = 1;
	for (Int i = 0; i < N; ++i) {
		Int x = lower_bound(a.begin(), a.end(), b[i]) - a.begin();
		Int y = lower_bound(b.begin(), b.end(), c[i]) - b.begin();
		(ans *= (x - i) * (y - i) % MOD) %= MOD;
	}
	while (N > 0) {
		(ans *= N--) %= MOD;
	}
	cout << ans % MOD << endl;

	return 0;
}

