				ans=mul(ans,b);
				b--;
			}
			else{
				ans=mul(ans,a);
				b++;
				a--;
			}
		}
		else{
			int i=lower_bound(all(rv[2]),j)-rv[2].begin();
			if(rv[2][i]==min({rv[0][i],rv[1][i],rv[2][i]})){
