    mint &operator+=(const mint a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }

    mint &operator-=(const mint a) {
        if ((x += mod - a.x) >= mod) x -= mod;
        return *this;
    }

    mint &operator*=(const mint a) {
        (x *= a.x) %= mod;
        return *this;
    }

    mint operator+(const mint a) const {
        mint res(*this);
        return res += a;
    }

    mint operator-(const mint a) const {
        mint res(*this);
        return res -= a;
    }

    mint operator*(const mint a) const {
        mint res(*this);
        return res *= a;
    }

    mint pow(ll t) const {
        if (!t) return 1;
        mint a = pow(t >> 1);
        a *= a;
        if (t & 1) a *= *this;
        return a;
    }

    // for prime mod
    mint inv() const {
        return pow(mod - 2);
    }

    mint &operator/=(const mint a) {
        return (*this) *= a.inv();
    }

    mint operator/(const mint a) const {
        mint res(*this);
        return res /= a;
    }

    friend std::istream &operator>>(std::istream &in, mint &o) {
        ll a;
        in >> a;
        o = a;
        return in;
    }

    friend std::ostream &operator<<(std::ostream &out, const mint &o) {
        out << o.x;
        return out;
    }

};


int main() {

    int n;
    string s;
    cin >> n >> s;

    mint ans = 1;

    int r = 0, g = 0, b = 0;

    auto get = [&](char c) -> int {
        if (c == 'R') {
            return r;
        } else if (c == 'G') {
            return g;
        } else {
            return b;
        }
    };

    auto get_other_min = [&](char c) -> int {
        if (c == 'R') {
            return min(g, b);
        } else if (c == 'G') {
            return min(r, b);
        } else {
            return min(r, g);
        }
    };


    auto get_other_max = [&](char c) -> int {
        if (c == 'R') {
            return max(g, b);
        } else if (c == 'G') {
            return max(r, b);
        } else {
            return max(r, g);
        }
    };

    auto increment = [&](char c) {
        if (c == 'R') {
            r++;
        } else if (c == 'G') {
            g++;
        } else {
            b++;
        }
    };

    auto decrement_all = [&](char c) {
        r--;
        g--;
        b--;
    };

    rep(i, 3 * n) {
        char c = s[i];
        int me = get(c);
        int omin = get_other_min(c);
        int omax = get_other_max(c);

        increment(c);

        assert(omin <= omax);

        // 成立
        if (omin > 0 && omax > 0) {
            assert(me == 0);

            ans *= omin;
            decrement_all(c);
            continue;
        }

        if (omin == 0 && omax == 0) {
            continue;
        }

        assert(omin == 0 && omax > 0);

        if (omax > me) {
            ans *= (omax - me);
        }
    }

    rep(i, n) ans *= (i + 1);

    cout << ans << endl;

}

