        int g = 0, b = 0, gb = 0;
        F0R (i, sz(S)) {
            if (S[i] == 'R') {
                if (gb > 0) { ans *= gb; gb--; }
                else if (b > 0) { ans *= b; b--, g--; }
                else if (g > 0) { ans *= g; g--, b--; }
                else gb--;
            } else if (S[i] == 'G') {
                g++;
            } else {
                b++;
            }

            if (g > 0 && b > 0) {
                if (gb < 0) ans *= g * b;
                g--, b--, gb++;
            }
        }
        reverse(all(S));
    }

    ps(ans);

    return 0;
}

