        else if (s[i] == 'G')
            a[i] = 2;
        else
            a[i] = 4;
    }

    vector<int> cnt(8, 0);
    for(int i = 0; i < 8; i += 1)
        cnt[i] = __builtin_popcount(i);

    vector<int> freq(8, 0);
    int ans = 1;

    for(int i = 0; i < m; i += 1) {
        bool matched = false;

        for(int mask = 0; mask < 8; mask += 1) {
            if(freq[mask] > 0 and (a[i] | mask) == 7) {
                ans = 1LL * ans * freq[mask];
                freq[mask] -= 1;
                matched = true;
            }
        }

        if (matched)
