        for(int mask = 0; mask < 8; mask += 1) {
            if(freq[mask] == 0)
                continue;
            if((a[i] | mask) > mask) {
                ans = 1LL * ans * freq[mask];
                freq[mask] -= 1;
                freq[a[i] | mask] += 1;
                matched = true;
            }
        }

        if (matched)
            continue;

        freq[a[i]] += 1;
    }

    for(int i = 1; i <= n; i += 1)
        ans = 1LL * ans * i % MOD;

