            b++;
        }
    }
    vector<ll> dp(3,0);
    dp[0] = n;
    ll ret = 1;
    rep(i,3*n){
        // debug(i);
        // print(dp);
        ret *= dp[table[i]-1];
        ret %= MOD;
        dp[table[i]-1]--;
        if(table[i] < 3)dp[table[i]]++;
    }

    // print(table);

    cout << ret % MOD << endl;
}

