        z.pb(mp(pos[1][i],1));
        z.pb(mp(pos[2][i],2));
        sort(z.begin(),z.end());
        v[z[1].second*3+z[2].second].pb(mp(z[1].first,1)),v[z[1].second*3+z[2].second].pb(mp(z[2].first,-1));
        v[z[0].second*3+z[1].second+9].pb(mp(z[0].first,1)),v[z[0].second*3+z[1].second+9].pb(mp(z[1].first,-1));
    }
    for (i = 0; i < 18; i++) {
        int c = 0;
        sort(v[i].begin(),v[i].end());
        for (j = 0; j < v[i].size(); j++) {
            if (v[i][j].second == 1) c++;
            else ways *= c,ways %= MOD,c--;
        }
    }
    for (i = 1; i <= N; i++) ways *= i,ways %= MOD;
    printf("%lld\n",ways);

    return 0;
}

