inline ll count(const vector<int>& vec, int l, int r)
{
	auto fst = lower_bound(vec.begin(), vec.end(), l);
	auto lst = upper_bound(vec.begin(), vec.end(), r);

	return lst - fst;
}

void solve()
{
	cin >> n >> str;
	n *= 3;

	for(int i = 0; i < n; ++i)
		pos[str[i]].push_back(i);

	for(int i = 0; i < n / 3; ++i)
	{
		int R = pos['R'][i];
		int G = pos['G'][i];
		int B = pos['B'][i];

		int left  = min({R, G, B});
		int right = max({R, G, B});
		int mid   = R ^ G ^ B ^ left ^ right;

		str[left] = '1';
		str[mid] = '2';
		str[right] = '3';
	}

	for(int i = 0; i < n; ++i)
		pos[str[i]].push_back(i);

	ll answ12 = 1LL, answ23 = 1LL;

	vector<int> cur1, cur2, cur3;

	for(int i = 0; i < n / 3; ++i)
	{
		cur1.push_back(pos['1'][i]);
		cur2.push_back(pos['2'][i]);
		cur3.push_back(pos['3'][i]);

		ll mult12 = 1LL, mult23 = 1LL;

		mult12 += count(cur2, pos['1'][i], pos['2'][i] - 1);
		mult23 += count(cur3, pos['2'][i], pos['3'][i] - 1);

		answ12 = (answ12 * mult12) % mod;
		answ23 = (answ23 * mult23) % mod;
	}

	ll answ = (answ12 * answ23) % mod;

	for(ll f = 1; f <= n / 3; ++f)
		answ = (answ * f) % mod;

	cout << answ << endl;
}

