void _main() {
	cin >> N >> S;
	map<char, int> dic;
	dic['R'] = 0; dic['G'] = 1; dic['B'] = 2;
	rep(i, 0, N * 3) Balls[dic[S[i]]].push_back(i + 1);

	rep(i, 0, N) {
		int ma = max({ Balls[0][i], Balls[1][i], Balls[2][i] });
		int mi = min({ Balls[0][i], Balls[1][i], Balls[2][i] });
		flag[ma] = 1;
		flag[mi] = -1;
	}

	mint ans = 1;
	int r = 0, g = 0, b = 0;
	int rg = 0, rb = 0, gr = 0, gb = 0, br = 0, bg = 0;
	rep(i, 1, 3 * N + 1) {
		char c = S[i - 1];
		if (flag[i] < 0) {
			if (c == 'R') r++;
			if (c == 'B') b++;
			if (c == 'G') g++;
		}
		else if (flag[i] == 0) {
			if (c == 'R') {
				if (0 < g) ans *= g, g--, gr++;
				if (0 < b) ans *= b, b--, br++;
			}
			if (c == 'B') {
				if (0 < r) ans *= r, r--, rb++;
				if (0 < g) ans *= g, g--, gb++;
			}
			if (c == 'G') {
				if (0 < r) ans *= r, r--, rg++;
				if (0 < b) ans *= b, b--, bg++;
			}
		}
		else {
			if (c == 'R') {
				if (0 < gb) ans *= gb, gb--;
				if (0 < bg) ans *= bg, bg--;
			}
			if (c == 'B') {
				if (0 < rg) ans *= rg, rg--;
				if (0 < gr) ans *= gr, gr--;
			}
			if (c == 'G') {
				if (0 < rb) ans *= rb, rb--;
				if (0 < br) ans *= br, br--;
			}
		}
	}

	rep(i, 1, N + 1) ans *= i;

	cout << ans << endl;
}

