  cin >> dat;
  vector<int> r, g, b;
  for (int i = 0; i < 3 * n; i++) {
    if (dat[i] == 'R') r.push_back(i);
    else if (dat[i] == 'G') g.push_back(i);
    else b.push_back(i);
  }
  vector<int> sign(3*n);
  for (int i = 0; i < n; i++) {
    int left = min(r[i], min(g[i], b[i]));
    int right = max(r[i], max(g[i], b[i]));
    sign[left] = -1;
    sign[right] = 1;
  }
  long long ans = 1;
  for (int i = 1; i <= n; i++) ans = (ans*i) % mod;
  int rp = 0, gp = 0, bp = 0;
  int rm = 0, gm = 0, bm = 0;
  for (int i = 0; i < 3*n; i++) {
    if (sign[i] == -1) {
      if (dat[i] == 'R') rp++;
      else if (dat[i] == 'G') gp++;
      else bp++;
    } else if (sign[i] == 1) {
      if (dat[i] == 'R') {
        ans *= gm + bm; ans %= mod;
        if (gm) gm--; else bm--;
      }
      else if (dat[i] == 'G') {
        ans *= rm + bm; ans %= mod;
        if (rm) rm--; else bm--;
      }
      else {
        ans *= rm + gm; ans %= mod;
        if (rm) rm--; else gm--;
      }
    } else {
      if (dat[i] == 'R') {
        ans *= gp + bp; ans %= mod;
        if (gp) gp--; else bp--;
        rm++;
      }
      else if (dat[i] == 'G') {
        ans *= rp + bp; ans %= mod;
        if (rp) rp--; else bp--;
        gm++;
      }
      else {
        ans *= rp + gp; ans %= mod;
        if (rp) rp--; else gp--;
        bm++;
      }
    }
  }
  cout << ans << "\n";
  return 0;
}

