  REP(i,n*3){
    if (s[i]=='R') flag=0;
    if (s[i]=='G') flag=1;
    if (s[i]=='B') flag=2;
    rgb[flag]++;
    lr[i]=1;
    if ((rgb[(flag+1)%3]!=0)&(rgb[(flag+2)%3]!=0)){
      lr[i]=2;
      rgb[0]--;
      rgb[1]--;
      rgb[2]--;
    }else{
      if (rgb[flag]>rgb[(flag+1)%3]){
        if (rgb[flag]>rgb[(flag+2)%3]){
          lr[i]=0;
        }
      }
    }
  }


  dat0[0]=(ll)s[0]*1LL;
  datn[0]=1;
  int w=0;
  int ref=0;
  int dref=0;
