        dat0[w]=(ll)s[i]*1LL;
        datn[w]=1;
      }
      ref=i;
    }
  }

  REP(i,n){
    ans*=(i+1LL);
    ans%=MOD;
  }


  cout<<ans<<endl;
  return 0;
}

