	int cR=0, cG=0, cB=0;
	ll ans = 1;
	while (l < 3 * N&&r<3*N) {
		//print(r);
		if (S[r] == 'R') {
			R = true;
			cR++;
		}
		else if (S[r] == 'G') {
			G = true;
