		}
		else if (S[r] == 'B') {
			B = true;
			cB++;
		}
		if (cR>0&&cG>0&&cB>0) {
			if (r < 3 * N - 1 && S[r + 1] == S[r]) {
				r++;
				continue;
			}
			ans = mult(ans, fac[cG]);
			ans = mult(ans, fac[cB]);
			if (ans < 0)return 1;
			ans %= MOD;
			int mn = min({ cR,cG,cB });
			cR -= mn, cG -= mn, cB -= mn;
			l = r;
