template <uint_fast64_t Modulus> class mint {
    using u64 = uint_fast64_t;
    public:
    u64 a;
    constexpr mint(const u64 x = 0) noexcept : a(x % Modulus) {}
    constexpr u64 &value() noexcept { return a; }
    constexpr const u64 &value() const noexcept { return a; }
    constexpr mint operator+(const mint rhs) const noexcept {
        return mint(*this) += rhs;
    }
    constexpr mint operator-(const mint rhs) const noexcept {
        return mint(*this) -= rhs;
    }
    constexpr mint operator*(const mint rhs) const noexcept {
        return mint(*this) *= rhs;
    }
    constexpr mint operator/(const mint rhs) const noexcept {
        return mint(*this) /= rhs;
    }
    constexpr mint &operator+=(const mint rhs) noexcept {
        a += rhs.a;
        if (a >= Modulus) {
            a -= Modulus;
        }
        return *this;
    }
    constexpr mint &operator-=(const mint rhs) noexcept {
        if (a < rhs.a) {
            a += Modulus;
        }
        a -= rhs.a;
        return *this;
    }
    constexpr mint &operator*=(const mint rhs) noexcept {
        a = a * rhs.a % Modulus;
        return *this;
    }
    constexpr mint &operator/=(mint rhs) noexcept {
        u64 exp = Modulus - 2;
        while (exp) {
            if (exp % 2) {
                *this *= rhs;
            }
            rhs *= rhs;
            exp /= 2;
        }
        return *this;
    }
    constexpr mint operator++(int n) const noexcept {
        return mint(*this) +=1;
    }
    constexpr mint operator--(int n) const noexcept {
        return mint(*this) -=1;
    }
};
template <uint_fast64_t Modulus>ostream& operator<<(ostream& lhs, const mint<Modulus>& rhs) noexcept {
    lhs << rhs.a;
    return lhs;
}
template <uint_fast64_t Modulus>istream& operator>>(istream& lhs, const mint<Modulus>& rhs) noexcept {
    lhs >> rhs.a;
    return lhs;
}
int main(){
    lint n;
    cin>>n;
    string s;
    cin>>s;
    mat v(3,vec{});
    vec mid(n);
    rep(i,3*n){
        if(s[i]=='R')v[0].push_back(i);
        if(s[i]=='G')v[1].push_back(i);
        if(s[i]=='B')v[2].push_back(i);
    }
    rep(i,n){
        vec tmp={v[0][i],v[1][i],v[2][i]};
        sort(all(tmp));
        mid[i]=tmp[1];
    }
    mat up(n,vec{}),down(n,vec{});
    rep(i,n){
        rep(j,3){
            auto it=lower_bound(all(v[j]),mid[i]);
            if(*it==mid[i]){
                continue;
            }
            down[i].push_back(it-v[j].begin());
            auto upit=upper_bound(all(v[j]),mid[i]);
            up[i].push_back(v[j].end()-upit);
        }
    }
    mint<998244353> ans=1;
    rep(i,n){
        lint d=max(0LL,down[i][0]-i);
        lint u=max(0LL,up[i][1]-(n-1-i));
        lint d2=max(0LL,down[i][1]-i);
        lint u2=max(0LL,up[i][0]-(n-1-i));
        ans*=(d*u+d2*u2);
    }
    repi(i,1,n+1){
        ans*=i;
    }
    cout<<ans;
}

