const long long MOD = 998244353;

int main() {
    int n;
    array<int, 3> count = {}, prev = {};
    string s;
    cin >> n >> s;
    long long result = 1;
    for (char c : s) {
        if (c == 'R') {
            count[0]++;
        } else if (c == 'G') {
            count[1]++;
        } else {
            count[2]++;
        }
        auto sorted = count;
        sort(begin(sorted), end(sorted));
        if (sorted[2] != prev[2]) {
            result = result * sorted[2] % MOD;
        } else if (sorted[0] != prev[0]) {
            result = result * (prev[1] - prev[0]) % MOD;
        } else {
            result = result * (prev[2] - prev[1]) % MOD;
        }
        swap(prev, sorted);
    }
    cout << result;
    return 0;
}

