    string S;
    cin >> N >> S;
    auto id = [](char c){
        if(c=='R') return 0;
        if(c=='G') return 1;
        if(c=='B') return 2;
    };
    auto the_other = [](int x,int y){
        if(x>y) swap(x,y);
        if(x==0 && y==1) return 2;
        if(x==0 && y==2) return 1;
        if(x==1 && y==2) return 0;
    };
    ll res = N;
    vector<ll> cnt0(3,0),cnt1(3,0);
    mint ans = 1;
    for(int i=0;i<3*N;i++){
        int now = id(S[i]);
        if(cnt1[now]!=0){
            ans *= cnt1[now];
            cnt1[now]--;
        }else{
            bool ok = false;
            for(int k=0;k<3;k++){
                if(now==k) continue;
                if(cnt0[k]!=0){
                    ans *= cnt0[k];
                    cnt0[k]--;
                    cnt1[the_other(now,k)]++;
                    ok = true;
                    break;
                }
            }
            if(!ok){
                ans *= res;
                res--;
                cnt0[now]++;
            }
        }
    }
    cout << ans.x << endl;
