			}
		}
	}
	else {
		s = s0;
	}
	string brstr, grstr;
	int b = 0, g = 0, r = 0, br = 0, gr = 0;
	deque<char> st;
	ll res = 1;
	REP(i, n * 3) {
		char c = s[i];
		if (c == 'R') {
			if (b > 0 && g > 0) {
				r++;
				st.push_back('R');
				while (!(r == g && g == b)) {
					i++;
					st.push_back(s[i]);
					if (s[i] == 'R') r++;
					else if (s[i] == 'G') g++;
					else if (s[i] == 'B') b++;
				}
