				for (char c : st) sss += c;
				st.clear();
				res = mmul(res, f(sss, r));
				r = 0;g = 0;b = 0;
			}
			else if (b > 0) {
				res = mmul(res, b);
				b--;
				st.pop_back();
				br++;
				brstr += 'x';
			}
			else if (g > 0) {
				res = mmul(res, g);
				g--;
				st.pop_back();
				gr++;
				grstr += 'x';
			}
			else {
				r++;
			}
		}
		else if (c == 'G') {
			if (br > 0) {
				br--;
				brstr += 'y';
			}
			else if (r == 0) {
				g++;
				st.push_back('G');
			}
			else {
				res = mmul(res, r);
				r--;
				gr++;
				grstr += 'x';
			}
		}
		else if (c == 'B') {
			if (gr > 0) {
				gr--;
				grstr += 'y';
			}
			else if (r == 0) {
				b++;
				st.push_back('B');
			}
			else {
				res = mmul(res, r);
				r--;
				br++;
				brstr += 'x';
			}
		}
	}
	res = mmul(res, ff(grstr));
	res = mmul(res, ff(brstr));
	return res;
}

