LL exp(LL a, LL b){
	LL res = 1;
	LL sum = a;
	while(b){
		if(b&1)res = (res * sum) % MOD;
		sum = (sum * sum) % MOD;
		b>>=1;
	}
	return res;
}

LL factorial(LL x){
	if(x<=1){
		return 1;
	}
	return x * factorial(x-1) % MOD;
}

