ll mult(ll a, ll b){
    return a * b % MOD;
}
ll binPow(ll a, ll b){
    if(b == 0) return 1;
    if(b & 1) return a * binPow(a, b-1) % MOD;
    return binPow(a * a % MOD, b >> 1);
}
ll inv(ll a){
    return binPow(a, MOD - 2);
}

ll fact[MAXN], invFact[MAXN];
ll factorial(int n){
    if(fact[n] != -1) return fact[n];
    return fact[n] = n * factorial(n-1) % MOD;
}
ll invFactorial(int n){
    if(invFact[n] != -1) return invFact[n];
    return invFact[n] = inv(n) * invFactorial(n-1) % MOD;
}

ll binomial(int n, int k){
    ll num = factorial(n);
    ll den = mult(invFactorial(k), invFactorial(n-k));
    return mult(num, den);
}

ll assign(int &n, int &k){
    ll ret; 
    if(n >= k) ret = mult(factorial(n), invFactorial(n-k));
    else ret = factorial(n);

    int x = min(n, k);
    n -= x;
    k -= x;
    return ret;
}

char other(char a, char b){
    if(a == 'R') return (b == 'G' ? 'B' : 'G');
    if(a == 'B') return (b == 'G' ? 'R' : 'G');
    return (b == 'R' ? 'B' : 'R');
}

