    ll ans = 1;

    while(i < 3*n){
        int len = 0;
        while(i + len < 3*n && s[i] == s[i+len]) len++;

        //Make shit happen        
        int cnt = len;

        //Complete if possible
        if(s[i] == 'R')
            ans = mult(ans, assign(r, cnt));
        if(s[i] == 'G')
            ans = mult(ans, assign(g, cnt));
        if(s[i] == 'B')
            ans = mult(ans, assign(b, cnt));

        //Add to the ones that have only one color
        if(s[i] != col){
            char c = other(s[i], col);
            if(c == 'R') r += min(rem, cnt);
            if(c == 'G') g += min(rem, cnt);
