                f[i+1]=f[i]*(i+1)%MOD;
            }
            i_f[n]=power(f[n],MOD-2);
            per(i,n){
                i_f[i]=(i_f[i+1]*(i+1))%MOD;
            }
        }
        ll power(ll a ,ll x){
            if (x==0) return 1;
            if (x==1) return a%MOD;
            if (x==2) return (a*a)%MOD;
            if (x%2==1) return (a*power(power(a,(x-1)/2),2))%MOD;
            return (power(power(a,x/2),2))%MOD;
        }
        ll fac(int x){
            return f[x];
        }
        ll invfac(int x){
            return i_f[x];
        }
        ll comb(int m,int k){
            if (m<0 or k<0) return 0;
            if (m<k) return 0;
            return (((f[m]*i_f[k])%MOD)*i_f[m-k])%MOD;
        }
};

int n;
string s;
vector<int> R,G,B,list;

void solve(){
    cin >> n;
    cin >> s;
    rep(i,3*n) {
        if (s[i]=='R') R.push_back(i);
        if (s[i]=='G') G.push_back(i);
        if (s[i]=='B') B.push_back(i);
    }
    list.resize(3*n,0);
    sort(R.begin(),R.end());
    sort(G.begin(),G.end());
    sort(B.begin(),B.end());
    rep(i,n){
        list[min(min(R[i],G[i]),B[i])]=-1;
        list[max(max(R[i],G[i]),B[i])]=1;
    }
    ll ans=1;
    int m=0,M=0;
    rep(i,3*n){
        if (list[i]==-1) {
            m+=1;
        }
        if (list[i]==0) {
            ans*=m;
            ans%=mod;
            m-=1;
        }
    }
    per(i,3*n){
        if (list[i]==1) {
            M+=1;
        }
        if (list[i]==0) {
            ans*=M;
            ans%=mod;
            M-=1;
        }
    }
    mod_fac mo;mo.init(n,mod);

    cout << ans*mo.fac(n)%mod << endl;

}

