            rgbs[0][1].push_back(g[i]);
            rgbs[0][2].push_back(b[i]);
        } else if (r[i] < b[i] && b[i] < g[i]) {
            rgbs[1][0].push_back(r[i]);
            rgbs[1][1].push_back(b[i]);
            rgbs[1][2].push_back(g[i]);
        } else if (g[i] < b[i] && b[i] < r[i]) {
            rgbs[2][0].push_back(g[i]);
            rgbs[2][1].push_back(b[i]);
            rgbs[2][2].push_back(r[i]);
        } else if (g[i] < r[i] && r[i] < b[i]) {
            rgbs[3][0].push_back(g[i]);
            rgbs[3][1].push_back(r[i]);
