        for (int j = 0; j < k; ++j) {
            while (l != k - 1 && rgbs[i][1][j] > rgbs[i][0][l + 1])
                l++;
            ret *= l + 1 - j;
            assert(l + 1 - j > 0);
        }
        int r = k - 1;
