struct mod_cal{
  long long val;
  mod_cal(long long val) : val(val) {}

  mod_cal operator + (const mod_cal x) const{
    return (val + x.val) % MOD;
  }

  mod_cal operator - (const mod_cal x) const{
    return (val - x.val + MOD) % MOD;
  }

  mod_cal operator * (const mod_cal x) const{
    return val * x.val % MOD; 
  }
};

