			tgt = B;
			opp1 = R;
			opp2 = G;
		}

		if (ball_count[tgt] >= ball_count[opp1] && ball_count[tgt] >= ball_count[opp2]) {
			//min
			type_ary.at(ball_count[tgt]) += tgt;
		}
		else if (ball_count[tgt] < ball_count[opp1] && ball_count[tgt] < ball_count[opp2]) {
			//max
			type_ary.at(ball_count[tgt]) += tgt*CNUM;
		}
		else {
			//center
		}

		ball_count[tgt]++;
	}

	for (int i = 0; i < CNUM; i++) {
		ball_count[i] = 0;
	}

	int min_count = 0;
	int max_count = 0;
	int type_duration = 0;
	for (unsigned int i = 0; i < N*CNUM; i++) {
		if (b.at(i) == 'R') {
			tgt = R;
			opp1 = G;
			opp2 = B;
