			opp1 = R;
			opp2 = G;
		}


		if (ball_count[tgt] >= ball_count[opp1] && ball_count[tgt] >= ball_count[opp2]) {
			//min
			min_count++;
		}
		else if (ball_count[tgt] < ball_count[opp1] && ball_count[tgt] < ball_count[opp2]) {
			//max
			max_count++;
		}
		else {
			//center
			if (ball_count[tgt] == 0 || type_ary[ball_count[tgt]] != type_ary[ball_count[tgt] - 1]) {
				min_count -= type_duration;
