  vi lr(n*3);//0がL、1が中間、2がR
  vi rgb(3);
  vi dat0(n*3);//0が何個つながってるか、1が何こつながってるか記憶するやつ
  vi datn(n*3);//0が何個つながってるか、1が何こつながってるか記憶するやつ

  ll flag=0;
  REP(i,n*3){
    if (s[i]=='R') flag=0;
    if (s[i]=='G') flag=1;
    if (s[i]=='B') flag=2;
    rgb[flag]++;
    lr[i]=1;
    if ((rgb[(flag+1)%3]!=0)&(rgb[(flag+2)%3]!=0)){
      lr[i]=2;
      rgb[0]--;
      rgb[1]--;
      rgb[2]--;
    }else{
      if (rgb[flag]>rgb[(flag+1)%3]){
        if (rgb[flag]>rgb[(flag+2)%3]){
          lr[i]=0;
        }
      }
    }
  }


  dat0[0]=(ll)s[0]*1LL;
  datn[0]=1;
  int w=0;
  int ref=0;
  int dref=0;
  for(int i=1;i<n*3;i++){
    if (lr[i]==2){
      ll nnum=0LL;
      for(int j=dref+1;j<=w;j+=2){
          nnum+=datn[j];
      }

      ans*=nnum;
      ans%=MOD;
      ans*=datn[dref];
      ans%=MOD;
      //cout<<i<<" "<<nnum<<" "<<dref<<" "<<datn[dref+1]<<" "<<ans<<endl;
      datn[dref]--;
