const int mod = 998244353;

const int xyz = 'R' + 'G' + 'B';

int oneside(string &s) {
    int t0 = 0, c0 = 0;
    int t1 = 0, c1 = 0;

    int ans = 1;

    for (auto x : s) {
        if (x == c1) {
            if (--t1 == 0) c1 = 0;
        } else if (t0) {
            if (x == c0) {
                t0++;
            } else {
                ans = 1LL * ans * t0-- % mod;
                t1++;
                c1 = xyz - x - c0;
            }
        } else {
            t0++;
            c0 = x;
        }
    }

    return ans;
}

