    for (int i = 2; i <= n; ++i){
        answer = 1LL * answer * i % mod;
    }

    answer = 1LL * answer * oneside(s) % mod;

    reverse(s.begin(), s.end());

    answer = 1LL * answer * oneside(s) % mod;

    cout << answer << endl;

    return 0;
}

