        vec.push_back({v[1][i],1});
        vec.push_back({v[2][i],2});
        sort(vec.begin(),vec.end());
        p1[vec[0].second].push_back(vec[1].first);
        p2[vec[2].second].push_back(vec[1].first);
        pp1[vec[0].second].push_back(vec[0].first);
        pp2[vec[2].second].push_back(vec[2].first);
    }
    ll ans = 1;
    for(int i=0;i<3;i++){
        sort(p1[i].begin(),p1[i].end());
        for(int j=0;j<(int)p1[i].size();j++){
            int num = upper_bound(pp1[i].begin(),pp1[i].end(),p1[i][j]) - pp1[i].begin();
            ans = ans * (num-j) % mod;
        }
    }
    for(int i=0;i<3;i++){
        sort(p2[i].begin(),p2[i].end());
        int cnt = 0;
        for(int j=(int)p2[i].size()-1;j>=0;j--){
            int num = upper_bound(pp2[i].begin(),pp2[i].end(),p2[i][j]) - pp2[i].begin();
            num = pp2[i].size() - num;
            ans = ans * (num-cnt) % mod;
            cnt++;
        }
    }
    for(int i=1;i<=n;i++) ans = ans * i % mod;
    cout<<ans<<endl;
}

