        a[v[i][0]] = 1;
        a[v[i][1]] = 2;
        a[v[i][2]] = 3;
    }

    vector<ll> b(3*n), c(3*n);
    REP(i, 3*n) {
        if(a[i]==1) b[i] = (i==0?0:b[i-1]) + 1;
        else if(a[i]==2) b[i] = (i==0?0:b[i-1]) - 1;
        else if(a[i]==3) b[i] = (i==0?0:b[i-1]);
    }
    for(ll i=3*n-1; i>=0; --i) {
        if(a[i]==1) c[i] = (i==3*n-1?0:c[i+1]);
        else if(a[i]==2) c[i] = (i==3*n-1?0:c[i+1]) - 1;
        else if(a[i]==3) c[i] = (i==3*n-1?0:c[i+1]) + 1;
    }

    // cout << a << endl;
    // cout << b << endl;
    // cout << c << endl;

    mint ret = 1;
    REP(i, 3*n) if(a[i]==2) ret *= mint(b[i-1]) * c[i+1];
    REP(i, n) ret *= i+1;
    cout << ret << endl;

    return 0;
}

