        for (int j = 1; j <= 3; j++) {
            id[i][j] = id[i + 1][j];
        }
        id[i][a[i]] = i;
    }

    int ans = 1;
    for (int i = 1; i <= m; i++) {
        if (!sum(i, i, a[i])) {
            continue;
        }
        int x = 0, y = 0, z = 0;
        x = i;
        for (int j = 1; j <= 3; j++) {
            if (j == a[x]) {
                continue;
            }
            if (!y) {
                y = fun(i, j);
            } else {
                z = fun(i, j);
            }
        }

        if (y > z) {
            swap(y, z);
        }
        int o = m;
        for (int j = 1; j <= 3; j++) {
            if (a[z] == j) {
                continue;
            }
            o = min(o, fun(z, j));
        }
        if (a[o] != z) {
            o = z;
        }
//        cout << x << " " << y << " " << z << " " << o << "\n";
//        cout << sum(x, z, a[y]) << "\n";
        if (sum(x, z, a[y]) > 0) {
            ans *= sum(x, z, a[y]);
        } else {
            throw 1;
        }
        ans %= MOD;
        if (sum(z, o, a[z]) > 0) {
            ans *= sum(z, o, a[z]);
        } else {
            throw 1;
        }
        ans %= MOD;
        add(y, -1, a[y]);
        add(x, -1, a[x]);
        add(z, -1, a[z]);
//        cout << sum(y, y, a[y]) << " " << sum(x, x, a[x]) << " " << sum(z, z, a[z]) << "\n";
    }
    ans *= f[n];
    ans %= MOD;
    cout << ans;
}

