  string S; cin >> S;

  vector<int> appear(3);
  vector<int> rank(3, 1);

  auto getAbove = [&](int x) -> int {
    assert(x == 2 || x == 3);
    for (int i = 0; i < 3; i++) {
      if (rank.at(i) + 1 == x) return i;
    }
    assert(x == 3);
    for (int i = 0; i < 3; i++) {
      if (rank.at(i) == 1) return i;
    }
    assert(0);
  };

  Fp ans = 1;
  for (int i = 0; i < 3*N; i++) {
    int c = toIdx(S.at(i));
    if (rank.at(c) == 1) {
      ans *= Fp(N - appear.at(c));
      for (int j = 0; j < 3; j++) {
	if (c == j) continue;
	if (rank.at(j) == 1) rank.at(j) = 2;
      }
    }else if (rank.at(c) == 2) {
      int d = getAbove(2);
      int diff = appear.at(d) - appear.at(c);
      ans *= Fp(diff);
      if (diff == 1) rank.at(c) = 1;
      for (int j = 0; j < 3; j++) {
	if (c == j) continue;
	if (rank.at(j) == 2) rank.at(j) = 3;
      }
    }else if (rank.at(c) == 3) {
      int d = getAbove(3);
      int diff = appear.at(d) - appear.at(c);
      ans *= Fp(diff);
      if (diff == 1) rank.at(c) = rank.at(d);
    }else assert(false);

    appear.at(c) += 1;

    DLOG("ans = %d", ans);
    DLOG("appear = %s", toString(appear).c_str());    // You need c_str()  
    DLOG("rank = %s", toString(rank).c_str());    // You need c_str()  

  }
  cout << (int)ans << endl;

  return 0;
}

