ll gogo()
{
    for (int i = 0; i < 3; i++)
    {
        nv[i] = 0;
    }

    ll ans = 1;
    int chi = 0, clo = 0;
    for (int i = 0; i < N; i++)
    {
        int ctype = 0;
        if (s[i] == 'R') ctype = 1;
        else if (s[i] == 'G') ctype = 2;

        nv[ctype]++;
        if (nv[ctype] > chi)
        {
            chi = nv[ctype];
            continue;
        }
        int nlo = 1e9;
        for (int j = 0; j < 3; j++)
        {
            nlo = min (nlo, nv[j]);
        }
        if (nlo > clo)
        {
            clo = nlo;
            continue;
        }

        ans *= (chi - nv[ctype] + 1);
        ans %= MOD;
    }
    return ans;
}

