template<class Monoid> 
struct SegTree{
	using ftm = function<Monoid(Monoid, Monoid)>;//Function Type Monoid
	size_t n;
	Monoid unity;
	ftm operation;
	ftm update;

	vector<Monoid> data;

	SegTree(size_t _n, Monoid _unity,        ftm _operation,    ftm _update)
	                 : unity(_unity), operation(_operation), update(_update)
	{
			   n = 1;
			   while(n < _n){
				   n *= 2;
			   }
			   data = vector<Monoid>(2*n-1, unity);
	}

	Monoid _query(int a, int b, int k, int l, int r){
		if(r <= a || b <= l) return unity;
		if(a <= l && r <= b) return data[k];
		else{
			Monoid c1 = _query(a, b, 2*k+1, l, (l+r)/2);
			Monoid c2 = _query(a, b, 2*k+2, (l+r)/2, r);
			return operation(c1, c2);
		}
	}

	void change(int i, Monoid x){
		data[i+=n-1] = update(data[i], x);
		while(i > 0){
			data[i = (i-1)/2] = operation(data[i*2+1], data[i*2+2]);
		}
	}

	Monoid query(int a, int b){
		return _query(a,b,0,0,n);
	}

	Monoid operator [](int i){
		return data[i+n-1];
	}

};

