			for(int j = 0 ; j < 3 ; ++j)
				if(j != num && cnt[j]){
					ans = 1ll * ans * (cnt[j] - cnt[num]++) % MOD;
					break;
				}
		}
		else{
			int mn = MOD;
			for(int j = 0 ; j < 3 ; ++j)
				if(j != num){
					mn = min(mn , cnt[j]); --cnt[j];
				}
			ans = 1ll * ans * mn % MOD;
		}
	}
	for(int i = 1 ; i <= N ; ++i) ans = 1ll * ans * i % MOD;
	cout << ans;
	return 0;
}

