ll ff(string s) {
	ll res = 1, cnt0 = 0, cnt1 = 0;
	char c = s[0];
	bool b = true;
	REP(i, s.length()) {
		if (b) {
			if (s[i] == c) {
				cnt0++;
			}
			else {
				b = false;
				c = s[i];
				cnt1++;
			}
		}
		else {
			if (s[i] == c) {
				cnt1++;
			}
			else {
				b = true;
				c = s[i];
				ll m = min(cnt0, cnt1);
				REP(j, m) {
					res = mmul(res, j + 1);
				}
				cnt0 -= m;
				cnt1 -= m;
				cnt0++;
			}
		}
	}
	REP(i, cnt0) {
		res = mmul(res, i + 1);
	}

	return res;
}

ll f(string s0, int n) {
	string s;
	char c = s0[0];
	char cc;
	REP(i, n * 3) {
		if (s0[i] != c) {
			cc = s0[i];
			break;
		}
	}
	if (cc == 'G') {
		for (char c : s0) {
			if (c == 'R') {
				s += 'B';
			}
			else if (c == 'G') {
				s += 'R';
			}
			else if(c=='B'){
				s += 'G';
			}
		}
	}
	else if (cc == 'B') {
		for (char c : s0) {
			if (c == 'R') {
				s += 'G';
			}
			else if (c == 'G') {
				s += 'B';
			}
			else if(c=='B'){
				s += 'R';
			}
		}
	}
	else {
		s = s0;
	}
	string brstr, grstr;
	int b = 0, g = 0, r = 0, br = 0, gr = 0;
	deque<char> st;
	ll res = 1;
	REP(i, n * 3) {
		char c = s[i];
		if (c == 'R') {
			if (b > 0 && g > 0) {
				r++;
				st.push_back('R');
				while (!(r == g && g == b)) {
					i++;
					st.push_back(s[i]);
					if (s[i] == 'R') r++;
					else if (s[i] == 'G') g++;
					else if (s[i] == 'B') b++;
				}
				string sss;
				for (char c : st) sss += c;
				st.clear();
				res = mmul(res, f(sss, r));
				r = 0;g = 0;b = 0;
			}
			else if (b > 0) {
				res = mmul(res, b);
				b--;
				st.pop_back();
				br++;
				brstr += 'x';
			}
			else if (g > 0) {
				res = mmul(res, g);
				g--;
				st.pop_back();
				gr++;
				grstr += 'x';
			}
			else {
				r++;
			}
		}
		else if (c == 'G') {
			if (br > 0) {
				br--;
				brstr += 'y';
			}
			else if (r == 0) {
				g++;
				st.push_back('G');
			}
			else {
				res = mmul(res, r);
				r--;
				gr++;
				grstr += 'x';
			}
		}
		else if (c == 'B') {
			if (gr > 0) {
				gr--;
				grstr += 'y';
			}
			else if (r == 0) {
				b++;
				st.push_back('B');
			}
			else {
				res = mmul(res, r);
				r--;
				br++;
				brstr += 'x';
			}
		}
	}
	res = mmul(res, ff(grstr));
	res = mmul(res, ff(brstr));
	return res;
}

int main() {
	int n;
	string s;
	cin >> n >> s;
	ll res = f(s, n);
	REP(i, n) res = mmul(res, i + 1);
	cout << res;
	return 0;
}

