int solve() {

    int N;
    cin >> N;

    string S;
    cin >> S;

    REP(i, N) {
        wait_r.emplace(i);
        wait_g.emplace(i);
        wait_b.emplace(i);
    }

    idxs.assign(3 * N, -1);
    which.assign(3 * N, -1);
    REP(i, 3 * N) {
        char c = S[i];
        int idx = -1;
        if (c == 'R') {
            auto itr = wait_r.begin();
            idx = *itr;
            wait_r.erase(itr);
        }
        if (c == 'G') {
            auto itr = wait_g.begin();
            idx = *itr;
            wait_g.erase(itr);
        }
        if (c == 'B') {
            auto itr = wait_b.begin();
            idx = *itr;
            wait_b.erase(itr);
        }
        idxs[i] = idx;
        which[i] = triplet[idx].size();
        triplet[idx].emplace_back(i);
    }

    modint res = 1;

    {   // head -> mid
        int cnt = 0;
        REP(i, 3 * N) {
            if (which[i] == 2) continue;
            if (which[i] == 0) ++cnt;
            else {
                res *= cnt--;
            }
        }
    }

    {   // tail -> mid
        int cnt = 0;
        RREP(i, 3 * N - 1) {
            if (which[i] == 0) continue;
            if (which[i] == 2) ++cnt;
            else {
                res *= cnt--;
            }
        }
    }

    REP(i, N) res *= i + 1;

    print(res);

    return 0;

}

