template<uint_fast64_t Modulus = MOD>
struct Modint {
  using u64 = uint_fast64_t;
  u64 a;

  constexpr Modint(const u64 x = 0) noexcept : a(x % Modulus) {}

  constexpr Modint operator+(const Modint rhs) const noexcept {
    return Modint(*this) += rhs;
  }
  constexpr Modint operator-(const Modint rhs) const noexcept {
    return Modint(*this) -= rhs;
  }
  constexpr Modint operator*(const Modint rhs) const noexcept {
    return Modint(*this) *= rhs;
  }
  constexpr Modint operator/(const Modint rhs) const noexcept {
    return Modint(*this) /= rhs;
  }

  constexpr Modint &operator+=(const Modint rhs) noexcept {
    a += rhs.a;
    if (a >= Modulus) a -= Modulus;
    return *this;
  }
  constexpr Modint &operator-=(const Modint rhs) noexcept {
    if (a < rhs.a) a += Modulus;
    a -= rhs.a;
    return *this;
  }
  constexpr Modint &operator*=(const Modint rhs) noexcept {
    a = a * rhs.a % Modulus;
    return *this;
  }
  constexpr Modint &operator/=(Modint rhs) noexcept {
    u64 exp = Modulus - 2;
    while (exp) {
      if (exp & 1) *this *= rhs;
      rhs *= rhs;
      exp >>= 1;
    }
    return *this;
  }

  explicit operator bool() const {
    return a;
  }

  friend ostream &operator<<(ostream &os, const Modint &m) {
    return os << m.a;
  }
};

using mint = Modint<MOD2>;

void solve() {
  int n; cin >> n;
  string s; cin >> s;

  int r = 0, g = 0, b = 0;
  mint ans = 1;
  rep1eq(i,n) ans *= i;

  for (auto &c : s) {
    if (c == 'R') {
      if (g && b) {
        ans *= min(g, b);
        --g, --b;
      } else {
        if (r < g + b) ans *= g + b - r;
        ++r;
      }
    } else if (c == 'G') {
      if (r && b) {
        ans *= min(r, b);
        --r, --b;
      } else {
        if (g < r + b) ans *= r + b - g;
        ++g;
      }
    } else {
      if (r && g) {
        ans *= min(r, g);
        --r, --g;
      } else {
        if (b < r + g) ans *= r + g - b;
        ++b;
      }
    }
  }

  cout << ans << endl;
}


