const int MOD = 998244353;
const ll INF = 1e9;
const double pi = acos(-1);
const double EPS = 1e-10;
typedef pair<int, int>P;
const int MAX = 200020;


long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
	fac[0] = fac[1] = 1;
	finv[0] = finv[1] = 1;
	inv[1] = 1;
	for (int i = 2; i < MAX; i++) {
		fac[i] = fac[i - 1] * i % MOD;
		inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
		finv[i] = finv[i - 1] * inv[i] % MOD;
	}
}

// 二項係数計算
long long COM(int n, int k) {
	if (n < k) return 0;
	if (n < 0 || k < 0) return 0;
	return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}
ll add(ll x, ll y) {
	x += y;
	if (x >= MOD) return x - MOD;
	return x;
}
ll sub(ll x, ll y) {
	x -= y;
	if (x < 0) return x + MOD;
	return x;
}
ll mult(ll x, ll y) {
	return (x * y) % MOD;
}
ll bin_pow(ll x, ll p) {
	if (p == 0) return 1;
	if (p & 1) return mult(x, bin_pow(x, p - 1));
	return bin_pow(mult(x, x), p / 2);
}
signed main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	int N; cin >> N;
	string S; cin >> S;
	COMinit();

	ll ans = 1;
	map<char, int>mp;
	mp['R'] = 0; mp['G'] = 1, mp['B'] = 2;
	vector<int>hav(3), cnt(3);
	int st = 0;
	REP(i, 3 * N) {
		int pos = mp[S[i]];
		int A = (pos + 1) % 3;
		int B = (pos + 2) % 3;

		if ((cnt[A] == 0 && cnt[B] == 0&&st==0)||(hav[pos]>0&&cnt[A]==0&&cnt[B]==0)) {
			cnt[pos]++;
			hav[pos]++;
		}
		else if (hav[A] > 0 && hav[B] > 0) {
			ans *= st;
			ans %= MOD;
			st--;
			hav[A]--, hav[B]--;
		}
		else if (cnt[A] > 0) {
			st++;
			ans *= max((ll)1,cnt[A]);
			ans %= MOD;
			cnt[A]--;
			hav[pos]++;
		}
		else if (cnt[B] > 0) {
			st++;
			ans = mult(ans, max((ll)1,cnt[B]));
			cnt[B]--;
			hav[pos]++;
		}
	}
	ans *= fac[N];
	ans %= MOD;
	if (ans < 0)return 1;
	print(ans);
}

