int get(char c){
	if(c=='R')return 0;
	if(c=='G')return 1;
	return 2;
}

int main(){

	int N;
	cin>>N;

	string S;
	cin>>S;

	vector<pair<int,int>> V;
	for(int i=0;i<3*N;i++){
		char c = S[i];
		int cnt = 1;
		while(true){
			i++;
			if(i==3*N){
				V.push_back(make_pair(get(c),cnt));
				break;
			}
			if(S[i]==c){
				cnt++;
			}
			else{
				V.push_back(make_pair(get(c),cnt));
				i--;
				break;
			}
		}
	}

	vector<int> cnt(3,0);
	vector<vector<int>> ind(3,vector<int>(0));
	int ans = 1;
	for(int i=0;i<V.size();i++){
		int a = V[i].first;
		int b = V[i].second;
		ind[a].push_back(i);
		cnt[a] += b;

		while((long long)cnt[0]*cnt[1]*cnt[2]!=0){
			for(int j=0;j<3;j++){
				if(j==a)continue;
				int tail = ind[j][ind[j].size()-1];
				ans = mod(ans * V[tail].second);
			}

			for(int j=0;j<3;j++){
				cnt[j]--;
				int tail = ind[j][ind[j].size()-1];
				V[tail].second --;
				if(V[tail].second==0)ind[j].pop_back();
			}

		}

	}

	for(int i=1;i<=N;i++)ans = mod(ans * i);

	cout<<ans<<endl;





	return 0;
}

