int main() {
  std::cin.tie(0); std::ios::sync_with_stdio(false);
  int N; std::string S; std::cin >> N >> S;
  std::vector<int> r, g, b;
  for(int i = 0; i < S.size(); ++i) {
    switch(S[i]){
    case 'R': r.push_back(i); break;
    case 'G': g.push_back(i); break;
    case 'B': b.push_back(i); break;
    }
  }
  std::vector<char> x(N*3, '_');
  for(int i = 0; i < N; ++i) {
    int mi = std::min(r[i], std::min(g[i], b[i]));
    x[mi] = '-';
    int ma = std::max(r[i], std::max(g[i], b[i]));
    x[ma] = '+';
  }
  int64_t ans = 1;
  for(int64_t i = 2; i <= N; ++i) (ans *= i) %= MOD;
  int64_t nmi = 0, np = 0;
  for(int i = 0; i < N*3; ++i) {
    switch(x[i]) {
    case '-': ++nmi; break;
    case '_': (ans *= nmi) %= MOD; --nmi; ++np; break;
    case '+': (ans *= np) %= MOD; --np;
    }
  }
  fin(ans);
  return 0;
}

