		int c = -1;
		rep(j, 3) if (s[i] == COL[j]) c = j;
		vi vec;

		rep(j, 3) if (j != c) {
			vec.pb(cnt[j]);
		}
		if (vec[0] > vec[1]) swap(vec[0], vec[1]);

		//cerr << cnt[c] << " " << vec[1] << endl;
		if (cnt[c] < vec[0]) {
			ans = ans * (vec[0] - cnt[c]) % MOD;
		} else if (cnt[c] < vec[1]) {
			ans = ans * (vec[1] - cnt[c]) % MOD;
		}

		cnt[c]++;
	}

	cout << ans << endl;
	return 0;
}

