long long solve();
long long calccol(char x);

int main() {
  cin >> n >> s;
  smodfact();
  cout << solve() << endl;
  return 0;
}

long long solve() {
  long long ans = factorial[n];
  for(int i = 0; i < 3 * n; ++i) {
    long long nowi = calccol(s[i]), num = 0;
    ++cnt[nowi];
    for(int j = 0; j < 3; ++j)
      if(j != nowi && cnt[j] > 0) ++num;
    if(num == 2) {
      num = cnt[nowi == 1];
      for(int j = 0; j < 3; ++j)
        if(j != nowi) num = min(cnt[j], num);
      ans *= num;
      ans %= N;
      for(int j = 0; j < 3; ++j) --cnt[j];
    }
    else if(num == 1) {
      for(int j = 0; j < 3; ++j)
        if(cnt[j] > cnt[nowi]) {
          ans *= cnt[j] - cnt[nowi] + 1;
          ans %= N;
        }
    }
  }

  return ans % N;
}

long long calccol(char x) {
  if(x == 'R')
    return 0;
  else if(x == 'G')
    return 1;
  else
    return 2;
}

