struct Data{
	int id,val;
	bool operator <(const Data &z)const{return val<z.val;}
};
priority_queue<Data> Q;
int main(){
	scanf("%d",&n);
	for(register int i=0;i<n;++i)scanf("%d",&b[i]);
	for(register int i=0;i<n;++i)scanf("%d",&a[i]);
	for(register int i=0;i<n;++i)Q.push((Data){i});
	for(register int i=0;i<n;++i)
	    if(a[i]==a[(i+1)%n]){
	    	puts("-1");
	    	return 0;
		}
	for(register int i=0;i<n;++i)Q.push((Data){i,a[i]});
	long long ans=0;
	while(!Q.empty()){
		int x=Q.top().id;
		Q.pop();
		if(a[x]==b[x])continue;
		int y1=(x-1+n)%n,y2=(x+1)%n;
		if(a[x]<=a[y1]||a[x]<=a[y2]){
			puts("-1");
			return 0;
		}
		ans+=a[x]/(a[y1]+a[y2]);
		a[x]%=(a[y1]+a[y2]);
		if(a[x]==b[x])continue;
		if(a[x]<b[x]){
			puts("-1");
			return 0;
		}
		if(a[x]>=a[y1]&&a[x]>=a[y2]){
			puts("-1");
			return 0;
		}
		Q.push((Data){x,a[x]});
	}
	printf("%lld\n",ans);
