#define mod 998244353 //(prime number)
#define INF 1000000000 //1e9
#define LLINF 2000000000000000000LL //2e18
#define SIZE 300010

vector<ll> factmemo, factmemoInv;
ll factmemoMod = -1;

ll factorial(int n, int M){
  if(factmemoMod == M) return factmemo[n];
  if(n <= 1) return 1;

  ll res = 1;
  for(int i=1; i<=n; i++) res = res * i % M;
  return res;
}

ll power(int k, int n, int M){
  if(n == 0) return 1;
  if(n == 1) return (ll)k;

  ll res = power(k, n/2, M);

  res = res * res % M;
  return n%2 == 1 ? res * k % M : res;
}

void initFactorial(int n, int M){
  factmemo.assign(n+1, 0);
  factmemoInv.assign(n+1, 0);
  factmemoMod = M;
  factmemo[0] = 1;
  for(int i=1;i<=n;i++) factmemo[i] = factmemo[i-1] * i % M;
  factmemoInv[n] = power(factmemo[n], M-2, M);
  for(int i=n;i>0;i--) factmemoInv[i-1] = factmemoInv[i] * i % M;
}

//nCm nPm nHm (mod M)

/*Combination*/
ll C(int n, int m, int M){
  if(n < m) return 0;
  if(m == 0 || n == m) return 1;

  if(factmemoMod == M)
    return factmemo[n] * factmemoInv[m] % M * factmemoInv[n-m] % M;

  ll numer = factorial(n, M);
  ll denom = factorial(m, M) * factorial(n-m, M) % M;

  denom = power((int)denom, M-2, M);

  return numer * denom % M;
}
/*Permutation*/
ll P(int n, int m, int M){
  if(n < m) return 0;
  if(m == 0) return 1;

  if(factmemoMod == M)
    return factmemo[n] * factmemoInv[n-m] % M;

  ll numer = factorial(n, M);
  ll denom = factorial(n-m, M);

  denom = power((int)denom, M-2, M);

  return numer * denom % M;
}
/*Combination with Repetitions*/
ll H(int n, int m, int M){
  if(n == 0 && m == 0) return 1;
  return C(n+m-1, m, M);
}



int main(){
  int N;
  char s[SIZE];

  scanf("%d%s", &N, s);

  initFactorial(N*3, mod);

  ll ans = 1;

  int sum[4] = {};
  char c[3];
  int counter = 0;


  for(int i=0; i<N*3; i++) {

    if ((sum[1] == 0 && sum[2] == 0) ||
        (sum[1] + sum[2] > 0 && c[1] == s[i])) {
      sum[1]++;
      c[1] = s[i];
    } else if ((sum[1] > 0 && sum[2] == 0) ||
               (sum[1] > 0 && sum[2] > 0 && c[2] == s[i])) {
      sum[1]--;
      sum[2]++;
      c[2] = s[i];
      ans = (sum[1] + 1) * ans % mod;

    } else if (sum[2] > 0 && c[1] != s[i] && c[2] != s[i]) {
      sum[2]--;

      ans = (sum[2] + 1) * ans % mod;

    } else if (sum[1] == 0 && sum[2] > 0 && c[2] == s[i]){
      swap(c[1], c[2]);
      sum[1]++;
    } else {
      assert(0);
    }
  }

  cout << ans * P(N, N, mod) % mod << endl;

  return 0;
}

