                }else if(cn[G])
                {
                    ans *= cn[G];
                    ans %= MOD;
                    cn[G+R]++;
                    cn[G]--;
                }else
                {
                    cn[R]++;
                }

                break;

            case 'G':
                if(cn[B+R])
                {
                    ans *= cn[B+R];
                    ans %= MOD;

                    cn[B+R]--;
                }else if(cn[B])
                {
                    ans *= cn[B];
                    ans %= MOD;
                    cn[B+G]++;
                    cn[B]--;
                }else if(cn[R])
                {
                    ans *= cn[R];
                    ans %= MOD;
                    cn[G+R]++;
                    cn[R]--;
                }else
                {
                    cn[G]++;
                }
                break;

            case 'B':
                if(cn[R+G])
                {
                    ans *= cn[R+G];
                    ans %= MOD;

                    cn[R+G]--;
                }else if(cn[R])
                {
                    ans *= cn[R];
                    ans %= MOD;
                    cn[B+R]++;
                    cn[R]--;
                }else if(cn[G])
                {
                    ans *= cn[G];
                    ans %= MOD;
                    cn[G+B]++;
                    cn[G]--;
                }else
                {
                    cn[B]++;
                }

                break;
        }
    }
    for(int i=2;i<=n;i++)
    {
        ans *= i;
        ans %= MOD;
    }

    printf("%d\n",ans);
    return 0;
}

