		class Edge implements Comparable<Edge> {
			int source;
			int target;
			long cost;
			Edge(int source, int target, long cost) {
				this.source = source;
				this.target = target;
				this.cost = cost;
			}

			@Override
			public int compareTo(Edge e) {
				return Long.compare(this.cost, e.cost);
			}
		}

public void solve() {
	int num = ni();
	int numBall = num * 3;
	char c[] = nc();
	int color[] = new int[numBall];
	for(int i = 0; i < numBall; i ++) {
		color[i] = c[i] == 'R' ? 0 : c[i] == 'G' ? 1 : 2;
	}
	prepareFact();

	int pair[][] = new int[num][3]; // R, G, B
	int type[][] = new int[num][3]; // R, G, B // 0, 1, 2
	fill(pair, -1);
	fill(type, -1);
	int index[] = {0, 0, 0};
	for(int i = 0; i < numBall; i ++) {
		int tmp = color[i];
		int tmpIndex = index[tmp];
		pair[tmpIndex][tmp] = i;
		if(type[tmpIndex][(tmp + 1) % 3] >= 0 && pair[tmpIndex][(tmp + 2) % 3] >= 0) {
			type[tmpIndex][tmp] = 2;
		}else if(type[tmpIndex][(tmp + 1) % 3] < 0 && pair[tmpIndex][(tmp + 2) % 3] < 0) {
			type[tmpIndex][tmp] = 0;
		}else {
			type[tmpIndex][tmp] = 1;
		}
		index[tmp] ++;
	}

	int pair2[][] = new int[num][3]; // 0, 1, 2
	for(int i = 0; i < num; i ++) {
		for(int j = 0; j < 3; j ++) {
			pair2[i][type[i][j]] = pair[i][j];
		}
	}

	boolean ok[][] = new boolean[num][3];
	for(int i = 1; i < num; i ++) {
		for(int j = 0; j < 3; j ++) {
			ok[i][j] = type[i][j] == type[i - 1][j];
			if(ok[i][j]) {
				switch(type[i][j]) {
				case 0:
					ok[i][j] &= pair2[i][0] < pair2[i - 1][1];
					break;
				case 1:
					ok[i][j] &= pair2[i][1] < pair2[i - 1][2] && pair2[i - 1][1] > pair2[i][0];
					break;
				case 2:
					ok[i][j] &= pair2[i - 1][2] > pair2[i][1];
					break;
				}
			}
		}
	}

	long ans = 1;
	int count = 0;
	for(int j = 0; j < 3; j ++) {
		count = 0;
		for(int i = 1; i <= num; i ++) {
			if(i < num && ok[i][j]) { count ++; }
			else { ans = mod(ans * fact[count + 1]); count = 0; }
		}
	}
	count = 0;
	for(int i = 1; i <= num; i ++) {
		if(i < num && ok[i][0] && ok[i][1] && ok[i][2]) { count ++; }
		else { ans = mod(ans * invFact[count + 1]); count = 0; }
	}
	ans = mod(ans * fact[num]);
	prtln(ans);
}

	}
}

import java.io.*;
import java.util.NoSuchElementException;


public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		final int MOD = 998_244_353;

		int n = sc.nextInt();
		char[] s = sc.next().toCharArray();

		PC pc = new PC(n, MOD);

		long[] cnt = new long[3];
		long d = 1;
		for (int i = 0; i < 3 * n; i++) {
			if (s[i] == 'R') {
				if (cnt[1] > 0 && cnt[2] > 0) {
					d *= Math.min(cnt[1], cnt[2]);
				} else if (cnt[1] > 0 && cnt[2] == 0) {
					d *= Math.max(1, cnt[1] - cnt[0]);
				} else if (cnt[1] == 0 && cnt[2] > 0) {
					d *= Math.max(1, cnt[2] - cnt[0]);
				} else {
				}
				cnt[0]++;
			} else if (s[i] == 'G') {
				if (cnt[0] > 0 && cnt[2] > 0) {
					d *= Math.min(cnt[0], cnt[2]);
				} else if (cnt[0] > 0 && cnt[2] == 0) {
					d *= Math.max(1, cnt[0] - cnt[1]);
				} else if (cnt[0] == 0 && cnt[2] > 0) {
					d *= Math.max(1, cnt[2] - cnt[1]);
				} else {
				}
				cnt[1]++;
			} else if (s[i] == 'B') {
				if (cnt[0] > 0 && cnt[1] > 0) {
					d *= Math.min(cnt[0], cnt[1]);
				} else if (cnt[0] > 0 && cnt[1] == 0) {
					d *= Math.max(1, cnt[0] - cnt[2]);
				} else if (cnt[0] == 0 && cnt[1] > 0) {
					d *= Math.max(1, cnt[1] - cnt[2]);
				} else {
				}
				cnt[2]++;
			}
			d %= MOD;

			long min = Math.min(cnt[0], Math.min(cnt[1], cnt[2]));
			for (int j = 0; j < 3; j++) {
				cnt[j] -= min;
			}
		}

		d *= pc.fact[n];
		d %= MOD;

		pr.println(d);
	}

	/**
	 * 組合せの数、順列、重複組み合わせなどを求める
	 * MOD による剰余を返す
	 */
    static class PC {
    	/** 除数。素数であることが基本的に必要(逆元をフェルマーの小定理で求めているため) */
    	int MOD;
    	/** 階乗 {@code fact[i]=i! % MOD} */
    	long[] fact;
    	/** 階乗の逆元 {@code ifact[i]=1/i! % MOD} */
    	long[] ifact;

    	/**
    	 * size を引数の上限とし、MOD を除数として剰余を取るインスタンスを返す
    	 * O(size) の事前処理が必要
    	 * 
    	 * @param size 主なメソッドの引数の上限値
    	 * @param MOD 除数
    	 */
    	PC(int size, int MOD) {
    		this.MOD = MOD;

    		fact = new long[size + 1];
    		fact[0] = 1;
    		for (int i = 1; i <= size; i++) {
    			fact[i] = fact[i - 1] * i % MOD;
    		}

    		ifact = new long[size + 1];

    		int loop = MOD - 2;
    		long x = fact[size];
    		ifact[size] = 1;
    		while (loop > 0) {
    			if (loop % 2 == 1) {
    				ifact[size] = ifact[size] * x % MOD;
    			}
    			x = x * x % MOD;
    			loop /= 2;
    		}

    		for (int i = size - 1; i >= 0; i--) {
    			ifact[i] = ifact[i + 1] * (i + 1) % MOD;
    		}

    	}

    	/**
    	 * 組合せの数 nCr を返す
    	 * O(1)
    	 * 
    	 * @param n {@literal 0<=n<=size}
    	 * @param r {@literal r>=0}
    	 * @return nCr の値(MOD による剰余)
    	 */
    	int C(int n, int r) {
    		if (r > n) {
    			return 0;
    		}

    		return (int)(((fact[n] * ifact[n - r]) % MOD) * ifact[r] % MOD);
    	}

    	// 
    	/**
    	 * 順列 nPr を返す
    	 * O(1)
    	 * 
    	 * @param n {@literal 0<=n<=size}
    	 * @param r {@literal r>=0}
    	 * @return nPr の値(MOD による剰余)
    	 */
    	int P(int n, int r) {
    		if (r > n) {
    			return 0;
    		}

    		return (int)((fact[n] * ifact[n -r]) % MOD);
    	}

    	/**
    	 * 重複組み合わせ nHr を返す
    	 * 異なるn種のものから重複を許してr個を選ぶ場合の数
    	 * 0個の種類もあり得る
    	 * O(1)
    	 * 
    	 * @param n {@literal 0<=n+r-1<=size}(他と上限が異なる)
    	 * @param r {@literal r>=0}
    	 * @return nHr の値(MOD による剰余)
    	 */
    	int H(int n, int r) {
    		if (n == 0 && r == 0) {
    			return 1;
    		}

    		return C(n + r - 1, r);
    	}

    	/**
    	 * 組合せの数 nCr を返す(nが大きいとき)
    	 * O(r)
    	 * 
    	 * @param n {@literal n>=0}(上限はなくlongの範囲内であればよい)
    	 * @param r {@literal 0<=r<=size}
    	 * @return nCr の値(MOD による剰余)
    	 */
    	int C2(long n, int r) {
    		long ret = ifact[r];
    		for (int i = 1; i <= r; i++) {
    			long tmp = (n - r + i) % MOD;
    			ret = (ret * tmp) % MOD;
    		}

    		return (int)ret;
    	}

    	/**
    	 * 第2種スターリング数 S(n,r) を返す
    	 * n人をちょうどr個のグループに分ける(グループの区別はなし)
    	 * グループの区別をする場合はr!S(n,r)。全射の場合の数と同義
    	 * O(r log n)
    	 * 
    	 * @param n {@literal n>=0}(上限はなくlongの範囲内であればよい)
    	 * @param r {@literal 0<=r<=size}
    	 * @return S(n,r) の値(MOD による剰余)
    	 */
    	int S(long n, int r) {
    		//全射の場合の数を包除原理を使って求めて、1/r!をかける。
    		long ret = 0;
    		for (int i = 1; i <= r; i++) {
    			long tmp = (r - i) % 2 == 0 ? 1 : -1;
    			tmp *= pow(i, n) * C(r, i) % MOD;
    			ret = (ret + tmp + MOD) % MOD;
    		}
    		ret = ret * ifact[r] % MOD;

    		return (int)ret;
    	}

    	/**
    	 * 繰り返し二乗法によるべき乗 {@code a^n % MOD} を返す
    	 * O(log n)
    	 * 
    	 * @param a 底
    	 * @param n べき指数
    	 * @return a^n の値(MOD による剰余)
    	 */
    	long pow(int a, long n) {
    		long loop = n;
    		long ret = 1;
    		long x = a;
    		while (loop > 0) {
    			if (loop % 2 == 1) {
    				ret = ret * x % MOD;
    			}
    			x = x * x % MOD;
    			loop /= 2;
    		}

    		return ret;
    	}

    	private final static int LIMIT = 66;
    	private static int to;
    	private static long[][] cache;

    	/**
    	 * 組合せの数 nCr を返す(MODによる剰余なし)
    	 * パスカルの三角形によって求める
    	 * 限界：n=66 : 66C33=7_219_428_434_016_265_740
    	 * O(n^2)
    	 * 
    	 * @param n {@literal 0<=n<=66}
    	 * @param r {@literal 0<=r}
    	 * @return nCr の値
    	 * @throws IllegalArgumentException {@literal n>66}の場合
    	 */
    	static long CLong(int n, int r) {
    		if (r > n) {
    			return 0;
    		}

    		if (n > LIMIT) {
    			throw new IllegalArgumentException(Integer.toString(n));
    		}

    		if (cache == null) {
    			cache = new long[LIMIT + 1][];
    			cache[0] = new long[1];
    			cache[0][0] = 1;
    			to = 0;
    		}

    		if (cache[n] == null) {
    			for (int i = to + 1; i <= n; i++) {
    				cache[i] = new long[i + 1];
    				for (int j = 0; j <= i; j++) {
    					if (j == 0 || j == i) {
    						cache[i][j] = 1;
    					} else {
    						if (Long.MAX_VALUE - cache[i - 1][j - 1] < cache[i - 1][j]) {
    			    			throw new IllegalArgumentException("Overflow");
    						} else {
    							cache[i][j] = cache[i - 1][j - 1] + cache[i - 1][j];
    						}
    					}
    				}
    			}
    			to = n;
    		}

    		return cache[n][r];
    	}
    }

