	public class Pair implements Comparable<Pair> {
		int x;
		int y;

		public Pair(int x, int y) {
			this.x = x;
			this.y = y;
		}

		@Override
		public int compareTo(Pair o) {
			if (x != o.x) {
				return x - o.x;
			}
			return y - o.y;
		}
	}

	public int[] sort(int[] a, int l, int r) {
		if (r < l) {
			return new int[0];
		}
		if (l == r) {
			int[] ans = { a[l] };
			return ans;
		}
		int m = (l + r) / 2;
		int[] left = sort(a, l, m);
		int[] right = sort(a, m + 1, r);
		return merge(left, right);
	}

	public int[] merge(int[] a, int[] b) {
		int i = 0;
		int j = 0;
		int[] ans = new int[a.length + b.length];
		while (i < a.length && j < b.length) {
			if (a[i] <= b[j]) {
				ans[i + j] = a[i];
				i++;
			} else {
				ans[i + j] = b[j];
				j++;
				perm += a.length - i;
			}
		}
		while (i < a.length) {
			ans[i + j] = a[i];
			i++;
		}
		while (j < b.length) {
			ans[i + j] = b[j];
			j++;
		}
		return ans;
	}

