		for (int i = 0; i < a.length; i++) {
			if (a[i] == 1) {
				if (gb > 0) {
					ans *= gb;
					ans %= mod;
					gb--;
				} else if (g > 0) {
					ans *= g;
					ans %= mod;
					g--;
					rg++;
				} else if (b > 0) {
					ans *= b;
					ans %= mod;
					b--;
