int pair[][];
int type[][];
int pair2[][];
public void solve() {
	prepareFact();
	int num = ni();
	int numBall = num * 3;
	char c[] = nc();
	int color[] = new int[numBall];
	for(int i = 0; i < numBall; i ++) {
		color[i] = c[i] == 'R' ? 0 : c[i] == 'G' ? 1 : 2;
	}

	pair = new int[num][3]; // R, G, B
	type = new int[num][3]; // R, G, B // 0, 1, 2
	fill(pair, -1);
	fill(type, -1);
	int index[] = {0, 0, 0};
	for(int i = 0; i < numBall; i ++) {
		int tmp = color[i];
		int tmpIndex = index[tmp];
		pair[tmpIndex][tmp] = i;
		if(type[tmpIndex][(tmp + 1) % 3] >= 0 && pair[tmpIndex][(tmp + 2) % 3] >= 0) {
			type[tmpIndex][tmp] = 2;
		}else if(type[tmpIndex][(tmp + 1) % 3] < 0 && pair[tmpIndex][(tmp + 2) % 3] < 0) {
			type[tmpIndex][tmp] = 0;
		}else {
			type[tmpIndex][tmp] = 1;
		}
		index[tmp] ++;
	}

	pair2 = new int[num][3]; // 0, 1, 2
	for(int i = 0; i < num; i ++) {
		for(int j = 0; j < 3; j ++) {
			pair2[i][type[i][j]] = pair[i][j];
		}
	}

	boolean ok[][] = new boolean[num][3];
	for(int i = 1; i < num; i ++) {
		for(int j = 0; j < 3; j ++) {

		}
	}

	long ans = 1;
	int left = 0;
	int right = 0;
	for(int j = 0; j < 3; j ++) {
		left = 0;
		right = 0;
		while(right < num) {
			if(check(j, right, left)) {
				right ++;
			}else {
				ans = mod(ans * fact[right - left]);
				left ++;
			}
		}
		ans = mod(ans * fact[right - left]);
	}
	int count = 0;
	for(int i = 1; i <= num; i ++) {
		if(i < num && check(0, i, i - 1) && check(1, i, i - 1) && check(2, i, i - 1)) { count ++; }
		else { ans = mod(ans * invFact[count + 1]); count = 0; }
	}
	ans = mod(ans * fact[num]);
	prtln(ans);
}

boolean check(int color, int i, int j) {
	if(i == j) { return true; }
	if(i < j) {
		int tmp = j;
		j = i;
		i = tmp;
	}
	boolean ok = type[i][color] == type[j][color];
	if(ok) {
		switch(type[i][color]) {
		case 0:
			ok &= pair2[i][0] < pair2[j][1];
			break;
		case 1:
			ok &= pair2[i][1] < pair2[j][2] && pair2[j][1] > pair2[i][0];
			break;
		case 2:
			ok &= pair2[j][2] > pair2[i][1];
			break;
		}
	}
	return ok;
}

