public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(out);
        pw.flush();
        pw.close();
    }

    public static void solve(StringBuilder out) {
        int n = In.ni();
        char[] s = In.nc();
        int cr = 0, cg = 0, cb = 0;
        int[] p = new int[3 * n];
        for (int i = 0; i < 3 * n; i++) {
            char c = s[i];
            switch (c) {
                case 'R':
                    if (cr < cg && cr < cb) p[i] = 1;
                    cr++;
                    break;
                case 'G':
                    if (cg < cb && cg < cr) p[i] = 1;
                    cg++;
                    break;
                case 'B':
                    if (cb < cr && cb < cg) p[i] = 1;
                    cb++;
                    break;
            }
        }
        for (int i = 3 * n - 1; i >= 0; i--) {
            char c = s[i];
            switch (c) {
                case 'R':
                    if (cr > cg && cr > cb) p[i] = -1;
                    cr--;
                    break;
                case 'G':
                    if (cg > cb && cg > cr) p[i] = -1;
                    cg--;
                    break;
                case 'B':
                    if (cb > cr && cb > cg) p[i] = -1;
                    cb--;
                    break;
            }
        }
        ModuloArithmetic ma = new ModuloArithmetic(Const.MOD99);
        long ans = 1;
        for (int i = 1; i <= n; i++) ans = ma.mul(ans, i);
        int l = 0, m = 0;
        for (int i = 0; i < 3 * n; i++) {
            switch (p[i]) {
                case -1:
                    l++;
                    break;
                case 0:
                    ans = ma.mul(ans, l - m);
                    m++;
                    break;
                case 1:
                    ans = ma.mul(ans, m);
                    l--;
                    m--;
                    break;
            }
        }
        out.append(ans);
    }
}



