public class Main {

  private static void solve() {
    int n = ni();
    char[] s = ns();
    int[][] q = new int[n][3];
    int[] p = new int[3];

    for (int i = 0; i < n * 3; i++) {
      char c = s[i];
      if (c == 'R') {
        s[i] = 0;
      } else if (c == 'G') {
        s[i] = 1;
      } else {
        s[i] = 2;
      }
      q[p[s[i]]++][s[i]] = i;
    }

    int[] c = new int[n * 3];
    for (int i = 0; i < n; i++) {
      Arrays.sort(q[i]);
      for (int j = 0; j < 3; j++) {
        c[q[i][j]] = j;
      }
    }

    long ret = 1;
    int mod = 998244353;
    long[] cnt = new long[3];

    for (int i = 0; i < n * 3; i++) {
      if (c[i] == 0) {
        cnt[0]++;
      } else if (c[i] == 2) {
        ret *= cnt[1];
        cnt[1]--;
        cnt[2]++;
      } else {
        ret *= cnt[0];
        cnt[1]++;
        cnt[0]--;
      }
      ret %= mod;
