		pi[1] = 1;
		for (int i = 2; i < p.length; i++) {
			p[i] = p[i - 1] * i % mod;
			pi[i] = modinv(p[i], mod);
		}

		long ans = 1;
		int[] cnt = new int[3];
		int[] same = new int[3];
		for (int i = 0; i < s.length; i++) {
			if (a[i] == 1) {
				same[2] = Math.max(cnt[2], same[2]);
				ans *= p[Math.max(cnt[2], 1)];
				ans %= mod;
				if (same[0] > 1 && same[1] > 1 && same[2] > 1) {
					ans *= pi[Math.max(Math.max(same[0], same[1]), same[2])];
					ans %= mod;
					Arrays.fill(same, 0);
				}
				same[0] = Math.max(cnt[0], same[0]);
				ans *= p[Math.max(cnt[0], 1)];
				ans %= mod;
				cnt[0] = 0;
				cnt[2] = 0;
			} else {
				same[1] = Math.max(cnt[1], same[1]);
				ans *= p[Math.max(cnt[1], 1)];
				ans %= mod;
				cnt[1] = 0;
			}
			cnt[a[i]]++;
		}
		System.out.println(ans * p[n] % mod);
	}

	static long modinv(long a, long m) {
		long b = m;
		long u = 1;
		long v = 0;
		long tmp = 0;

		while (b > 0) {
			long t = a / b;
			a -= t * b;
			tmp = a;
			a = b;
			b = tmp;

			u -= t * v;
			tmp = u;
			u = v;
			v = tmp;
		}

		u %= m;
		if (u < 0) u += m;
		return u;
	}
}

