            char[] ch = str.ToCharArray();


            char prev = '0';
            int cnt = 1;
            for (int i = 0; i < ch.Length; i++)
            {
                if (ch[i] != prev)
                {
                    if (i > 0)
                    {
                        prod(prev, cnt);
                        cnt = 1;
                    }
                    prev = ch[i];
                }
                else
                {
                    cnt++;
                }
            }

            long min = Math.Min(Math.Min(Gsig, Bsig), Rsig);
            if (min == Bsig) B = 1;
            else if (min == Rsig) R = 1;
            else G = 1;

            long mod = 998244353;
            long result = B * G % mod;
            result = result * R % mod;
            result = result * factorial(n) % mod;
            Console.WriteLine(result);
        }

        private static void prod(char prev, int cnt)
        {
            long mod = 998244353;
            if (prev == 'G')
            {
                G = (G * factorial(cnt)) % mod;
                Gsig += cnt * cnt;
            }
            else if (prev == 'R')
            {
                R = (R * factorial(cnt)) % mod;
                Rsig += cnt * cnt;
            }
            else
            {
                B = (B * factorial(cnt)) % mod;
                Bsig += cnt * cnt;
            }
        }

        private static int factorial(int n)
        {
            if (n == 0)
                return 1;
            return (n * factorial(n - 1)) % 998244353;

