class Scanner
{
    string[] s; int i;
    readonly char[] cs = new char[] { ' ' };
    public Scanner() { s = new string[0]; i = 0; }
    public string[] scan => ReadLine().Split();
    public int[] scanint => Array.ConvertAll(scan, int.Parse);
    public long[] scanlong => Array.ConvertAll(scan, long.Parse);
    public double[] scandouble => Array.ConvertAll(scan, double.Parse);
    public string next
    {
        get
        {
            if (i < s.Length) return s[i++];
            string st = ReadLine();
            while (st == "") st = ReadLine();
            s = st.Split(cs, StringSplitOptions.RemoveEmptyEntries);
            i = 0;
            return next;
        }
    }
    public int nextint => int.Parse(next);
    public long nextlong => long.Parse(next);
    public double nextdouble => double.Parse(next);
}

using System;
using CompLib.Mathematics;
using CompLib.Util;

public class Program
{
    private int N;
    private string S;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        S = sc.Next();

        //RGBが出来たら出来た順で組にするのが最小

        ModInt ans = 1;

        int r = 0;
        int g = 0;
        int b = 0;
        int rg = 0;
        int gb = 0;
        int br = 0;

        foreach (char c in S)
        {
            switch (c)
            {
                case 'R':
                    if (gb > 0)
                    {
                        ans *= gb--;
                    }
                    else if (g > 0)
                    {
                        ans *= g--;
                        rg++;
                    }
                    else if (b > 0)
                    {
                        ans *= b--;
                        br++;
                    }
                    else
                    {
                        r++;
                    }

                    break;
                case 'B':
                    if (rg > 0)
                    {
                        ans *= rg--;
                    }
                    else if (g > 0)
                    {
                        ans *= g--;
                        gb++;
                    }
                    else if (r > 0)
                    {
                        ans *= r--;
                        br++;
                    }
                    else
                    {
                        b++;
                    }

                    break;
                case 'G':
                    if (br > 0)
                    {
                        ans *= br--;
                    }
                    else if (r > 0)
                    {
                        ans *= r--;
                        rg++;
                    }
                    else if (b > 0)
                    {
                        ans *= b--;
                        gb++;
                    }
                    else
                    {
                        g++;
                    }

                    break;
            }
        }

        for (int i = 1; i <= N; i++)
        {
            ans *= i;
        }

        Console.WriteLine(ans);
    }

    public static void Main(string[] args) => new Program().Solve();
}

