            int indexg = 0;
            int indexb = 0;
            for (int i = 0; i < s.Length; i++)
            {
                if (s.Substring(i, 1).Equals("R"))
                {
                    r[indexr] = i;
                    indexr++;
                }
                else if (s.Substring(i, 1).Equals("G"))
                {
                    g[indexg] = i;
                    indexg++;
                }
                else
                {
                    b[indexb] = i;
                    indexb++;
                }
            }

            int minimum = 100000;
            int duplicate = 1;
            int midr = 0;
            int midg = 0;
            int midb = 0;
            for (int i = 0; i < n; i++)
            {
                int tmpmax;
                int tmpmin;
                tmpmax = Math.Max(r[i], g[i]);
                tmpmax = Math.Max(tmpmax, b[i]);
                tmpmin = Math.Min(r[i], g[i]);
                tmpmin = Math.Min(tmpmin, b[i]);

                if (minimum > tmpmax - tmpmin)
                {
                    minimum = tmpmax - tmpmin;
                    duplicate = 1;
                }
                else if (minimum == tmpmax - tmpmin)
                {
                    duplicate++;
                }

                if (r[i] != tmpmax && r[i] != tmpmin)
                {
                    midr++;
                }
                if (g[i] != tmpmax && g[i] != tmpmin)
                {
                    midg++;
                }
                if (b[i] != tmpmax && b[i] != tmpmin)
                {
                    midb++;
                }
            }

            long ans = (Factorial(n) * Factorial(midr) * Factorial(midg) * Factorial(midb) * Factorial(duplicate)) % 998244353;

            Console.WriteLine(ans);
        }

        static long Factorial(long n)
        {
            if (n == 0)
                return 1;
            return n * Factorial(n - 1);
        }
