func Solve() {
  var N int
  NextInt(&N)
  var R, G, B []int
  S := NextLine()
  for i, s := range S {
    if s == 'R' { R = append(R, i) }
    if s == 'G' { G = append(G, i) }
    if s == 'B' { B = append(B, i) }
  }
  RGB := make([][]int, N)
  for i := range RGB {
    RGB[i] = []int{R[i], G[i], B[i]}
    sort.Ints(RGB[i])
  }
  F, _, _ := Factorial(N)
  ans := 1
  pos1, pos2 := 0, 0
  for i := range R[1:] {
    if RGB[i + 1][0] < RGB[pos1][1] {
      ans = ans * (i + 2 - pos1) % p
    } else {
      pos1 = i + 1
    }
    if RGB[i + 1][1] < RGB[pos2][2] {
      ans = ans * (i + 2 - pos2) % p
    } else {
      pos2 = i + 1
    }
  }
  Write(ans * F[N] % p)
  return
}

