func solve(stdin io.Reader, stdout io.Writer) {

	r := NewScannerEx(stdin)
	r.Scan(false)
	n := r.nextInt()
	r.Scan(false)
	s := r.nextString()

	cnt := 0
	bingo := func(src map[rune][]int) (vs bool) {
		vs = true
		var key rune
		for key = range src {
			if len(src[key]) <= cnt {
				vs = false
				break
			}
		}
		return
	}

	minI := func(a int, vs ...int) int {
		for i := range vs {
			v := &vs[i]
			if a > *v {
				a = *v
			}
		}
		return a
	}

	maxI := func(a int, vs ...int) int {
		for i := range vs {
			v := &vs[i]
			if a < *v {
				a = *v
			}
		}
		return a
	}

	rbg := make(map[rune][]int, 3)
	rbg['R'] = make([]int, 0, n)
	rbg['G'] = make([]int, 0, n)
	rbg['B'] = make([]int, 0, n)

	rgbp := make([]string, len(s))
	for i, c := range s {
		rbg[c] = append(rbg[c], i+1)

		if bingo(rbg) {
			r, g, b := rbg['R'][cnt], rbg['G'][cnt], rbg['B'][cnt]
			M := maxI(r, g, b)
			m := minI(r, g, b)
			c := r + g + b - M - m
			jun := fmt.Sprintf("%c%c%c", s[m-1], s[c-1], s[M-1])
			rgbp[m-1] = fmt.Sprintf("m%s", jun)
			rgbp[c-1] = fmt.Sprintf("c%s", jun)
			rgbp[M-1] = fmt.Sprintf("M%s", jun)
			cnt++
		}
	}

	ans := 1
	eachCnt := make(map[string]int, len(rgbp))
	for i, end := 0, len(rgbp); i < end; i++ {
		c := rgbp[i]
		eachCnt[c]++
		if len(c) > 0 && c[0] == 'c' {

			ans *= maxI(0, eachCnt["m"+c[1:]]-eachCnt[c]) + 1

		}
	}

	eachCnt = make(map[string]int, len(rgbp))
	for i := len(rgbp) - 1; i >= 0; i-- {
		c := rgbp[i]
		eachCnt[c]++
		if len(c) > 0 && c[0] == 'c' {

			ans *= maxI(0, eachCnt["M"+c[1:]]-eachCnt[c]) + 1

		}
	}

	for i := n; i >= 2; i-- {
		ans *= i
	}
	fmt.Fprintln(stdout, ans)
}

