func Factorial(N int) (F, Finv, Inv []int) {
  F = make([]int, N + 1)
  Finv = make([]int, N + 1)
  Inv = make([]int, N + 1)
  F[0] = 1
  F[1] = 1
  Finv[0] = 1
  Finv[1] = 1
  Inv[0] = 1
  Inv[1] = 1
  for i := 2; i < N + 1; i++ {
    F[i] = F[i - 1] * i % p
    Inv[i] = p - Inv[p % i] * (p / i) % p
    Finv[i] = Finv[i - 1] * Inv[i] % p
  }
  return
}

const p = 998244353

func Solve() {
  var N int
  NextInt(&N)
  var R, G, B []int
  S := NextLine()
  for i, s := range S {
    if s == 'R' { R = append(R, i) }
    if s == 'G' { G = append(G, i) }
    if s == 'B' { B = append(B, i) }
  }
  RGB := make([][]int, N)
  C := make([]int, 3 * N)
  for i := range RGB {
    RGB[i] = []int{R[i], G[i], B[i]}
    sort.Ints(RGB[i])
    C[RGB[i][0]] = 0
    C[RGB[i][1]] = 1
    C[RGB[i][2]] = 2
  }
  F, _, _ := Factorial(N)
  ans := 1
  cnt := make([]int, 3)
  for _, c := range C {
    cnt[c]++
    if c < 1 { continue }
    ans *= cnt[c - 1] - cnt[c] + 1
    ans %= p
  }
  Write(ans * F[N] % p)
  return
}

