        }
    }

    let mut left = vec![];
    let mut center = vec![];
    let mut right = vec![];

    for i in 0..n {
        let mut row = vec![r[i], g[i], b[i]];
        row.sort();
        left.push(row[0]);
        center.push(row[1]);
        right.push(row[2]);
    }

    let mut left_count = vec![0; n];
    left.reverse();
    for (i, &c) in center.iter().enumerate() {
        while let Some(l) = left.pop() {
            if l > c {
                left.push(l);
                break;
            }
        }
        let count = n - left.len();
        left_count[i] = count - i;
    }

    let mut right_count = vec![0; n];
