        while let Some(r) = right.pop() {
            if r < c {
                right.push(r);
                break;
            }
        }

        let count = n - right.len();
        right_count[i] = count - (n - 1 - i);
    }

    let mut ans = 1;
    for i in 0..n {
        ans *= right_count[i];
        ans %= MOD;
        ans *= left_count[i];
        ans %= MOD;
