fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize);
    let mut av = vec![];
    let mut bv = vec![];
    let mut cv = vec![];
    let mut q = VecDeque::<Vec<(_, usize)>>::new();
    for (i, c) in it.next().unwrap().bytes().enumerate() {
        let mut flag = false;
        for v in q.iter_mut() {
            if v.iter().all(|(d, _)| *d != c) {
                v.push((c, i));
                flag = true;
                break;
            }
        }
        if flag {
            if q[0].len() == 3 {
                let v = q.pop_front().unwrap();
                av.push(v[0].1);
                bv.push(v[1].1);
                cv.push(v[2].1);
            }
        } else {
            q.push_back(vec![(c, i)]);
        }
    }

    let mut ret = Mint(1);
    let mut cur = 0;
    for (i, &bi) in bv.iter().enumerate() {
        while cur < av.len() && av[cur] < bi {
            cur += 1;
        }
        ret *= cur - i;
        eprintln!("{:?}", (bi, cur, i, ret)); // DEBUG
    }

    let mut cur = (cv.len() - 1) as i64;
    for (i, &bi) in bv.iter().rev().enumerate() {
        while cur >= 0 && cv[cur as usize] > bi {
            cur -= 1;
        }
        ret *= (cv.len() as i64 - cur - i as i64 - 1) as usize;
    }
    for i in 1..=n {
        ret *= i;
    }
    println!("{}", ret);
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

