fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize);
    let mut av = vec![];
    let mut bv = vec![];
    let mut cv = vec![];
    let mut q = vec![VecDeque::<Vec<usize>>::new(); 8];
    for (i, c) in it.next().unwrap().bytes().enumerate() {
        let j = match c {
            b'R' => 0b1,
            b'G' => 0b10,
            b'B' => 0b100,
            _ => unreachable!(),
        };
        for k in (0..7).rev() {
            if k & j != 0 {
                continue;
            }
            if let Some(mut v) = q[k].pop_front() {
                v.push(i);
                q[k | j].push_back(v);
                break;
            }
            if k == 0 {
                q[j].push_back(vec![i]);
            }
        }
    }
    for v in q[7].iter() {
        av.push(v[0]);
        bv.push(v[1]);
        cv.push(v[2]);
    }

    let mut ret = Mint(1);
    let mut cur = 0;
    for (i, &bi) in bv.iter().enumerate() {
        while cur < av.len() && av[cur] < bi {
            cur += 1;
        }
        ret *= cur - i;
    }

    let mut cur = (cv.len() - 1) as i64;
    for (i, &bi) in bv.iter().rev().enumerate() {
        while cur >= 0 && cv[cur as usize] > bi {
            cur -= 1;
        }
        ret *= (cv.len() as i64 - cur - i as i64 - 1) as usize;
    }
    for i in 1..=n {
        ret *= i;
    }
    println!("{}", ret);
}

