    let mut bit_r = BIT::new(3 * n);
    let mut bit_g = BIT::new(3 * n);
    let mut bit_b = BIT::new(3 * n);

    for i in 0..3 * n {
        match s[i] {
            'R' => bit_r.add(i, 1),
            'G' => bit_g.add(i, 1),
            'B' => bit_b.add(i, 1),
            _ => unreachable!(),
        }
    }

    for &((ia, ca), _, (ic, cc)) in &ts {
        match ca {
            'R' => bit_r.add(ia, -1),
            'G' => bit_g.add(ia, -1),
            'B' => bit_b.add(ia, -1),
            _ => unreachable!(),
        }
        match cc {
            'R' => bit_r.add(ic, -1),
            'G' => bit_g.add(ic, -1),
            'B' => bit_b.add(ic, -1),
            _ => unreachable!(),
        }
    }

    let MOD = 998244353;
    let mut answer = 1;
    for i in 1..n + 1 {
        answer *= i;
        answer %= MOD;
    }

    let mut last = ('_', '_');
    let mut cons = VecDeque::new();

    for &((ia, ca), (ib, cb), (ic, cc)) in ts.iter().rev() {
        if last != (ca, cb) {
            cons = VecDeque::new();
            last = (ca, cb);
        }
        cons.push_back(ia);

        loop {
            {
                if let Some(o_ia) = cons.front() {
                    if *o_ia < ib {
                        break;
                    }
                } else {
                    break;
                }
            }
            cons.pop_front();
        }

        answer *= cons.len();
        answer %= MOD;
    }

    for &((ia, ca), (ib, cb), (ic, cc)) in ts.iter() {
        let mid = match cb {
            'R' => bit_r.get(ia + 1, ic),
            'G' => bit_g.get(ia + 1, ic),
            'B' => bit_b.get(ia + 1, ic),
            _ => unreachable!(),
        };

        answer *= mid as usize;
        answer %= MOD;

        match cb {
            'R' => bit_r.add(ib, -1),
            'G' => bit_g.add(ib, -1),
            'B' => bit_b.add(ib, -1),
            _ => unreachable!(),
        };
    }

    println!("{}", answer);
}

/// Binary Indexed Tree (0-indexed)
///
/// This data structure supports these two queries in O(log n)
///
/// 1. add w to v[at]
/// 2. the sum of v[begin], v[begin+1], .., v[end-1]
pub struct BIT {
    tree: Vec<i64>,
}

impl BIT {
    /// Constructs a new BIT of length `len`.
    /// All values are initialized zero.
    ///
    /// # Examples
    /// ```
    /// use algonium::data_structure::BIT;
    /// # #[warn(unused_mut)]
    /// let mut bit = BIT::new(100);
    /// ```
    pub fn new(len: usize) -> BIT {
        BIT { tree: vec![0; len] }
    }

    /// Returns the number of elements in the BIT.
    ///
    /// # Examples
    ///
    /// ```
    /// use algonium::data_structure::BIT;
    /// let mut bit = BIT::new(100);
    /// assert_eq!(bit.len(), 100);
    /// ```
    pub fn len(&self) -> usize {
        self.tree.len()
    }

    /// Add a value `value` to a element of index `index`.
    /// v[index] += value
    ///
    /// # Panics
    ///
    /// Panics if `index > len`
    ///
    /// # Examples
    ///
    /// ```
    /// use algonium::data_structure::BIT;
    /// let mut bit = BIT::new(10);
    /// bit.add(5, 100);
    /// assert_eq!(bit.get(3, 6), 100);
    /// bit.add(5, 10);
    /// assert_eq!(bit.get(3, 6), 110);
    /// ```
    pub fn add(&mut self, index: usize, value: i64) {
        assert!(index < self.tree.len());
        let mut idx = index;
        while idx < self.tree.len() {
            self.tree[idx] += value;
            idx |= idx + 1;
        }
    }

    /// sum of v[idx] such that begin <= idx < end
    pub fn get(&self, begin: usize, end: usize) -> i64 {
        if begin >= end {
            return 0;
        }
        let a = if end > 0 { self.cum(end - 1) } else { 0 };
        let b = if begin > 0 { self.cum(begin - 1) } else { 0 };
        a - b
    }

    /// v[0] + ... + v[last]
    fn cum(&self, last: usize) -> i64 {
        assert!(last < self.tree.len());
        let mut res = 0;
        let mut idx = last as i64;
        while idx >= 0 {
            res += self.tree[idx as usize];
            idx = (idx & (idx + 1)) - 1;
        }
        res
    }
}

