        mark[u[2]] = 2;
    }
    // debugln!("mark = {:?}", mark);
    let mut cnt = 0;
    for i in 0..3 * n {
        match mark[i] {
            0 => {
                ans = ans * (cnt as i64) % MOD;
                cnt -= 1;
            }
            1 => cnt += 1,
            2 => (),
            _ => unreachable!(),
        }
    }
    assert_eq!(cnt, 0);
    for i in (0..3 * n).rev() {
        match mark[i] {
            0 => {
                ans = ans * (cnt as i64) % MOD;
                cnt -= 1;
            }
            2 => cnt += 1,
            1 => (),
            _ => unreachable!(),
        }
    }
    for i in 0..n {
        ans = ans * (i + 1) as i64 % MOD;
    }
    puts!("{}\n", ans);
}

