fn factorial(a: usize, p: usize) -> usize {
    if a == 0 {
        return 1
    }
    let mut n = 1;
    let mut a = a;
    while a > 1 {
        n *= a;
        n %= p;
        a -= 1;
    }
    n
}
pub fn modpow(x: usize, n: usize, m: usize) -> usize {
    let mut res = 1;
    let mut x = x % m;
    let mut n = n;
    while n > 0 {
        if n & 1 == 1 {
            res = (res * x) % m;
        }
        x = (x * x) % m;
        n >>= 1;
    }
    res
}
fn solve() {
    input! {
        N: usize,
        S: chars,
    }
    let p = 998244353;
    let mut ans = factorial(N, p);
    let mut pows = vec![0; N+1];
    let mut filled = vec![false; 3];
    let mut cur = vec![];
    for i in 0..S.len() {
        let c = S[i];
        // dbg!(c);
        cur.push(c);
        let n = if c == 'R' {
            0
        } else if c == 'G' {
            1
        } else {
            2
        };
        filled[n] = true;
        let mut ready = true;
        for &b in &filled {
            if !b {
                ready = false;
                break;
            }
        }
        if !ready {
            continue;
        }
        // dbg!("ready");
        // dbg!(&cur);
        let first_c = cur[0];
        let mut first_cnt = 0;
        let mut i = 0;
        while cur[i] == first_c {
            first_cnt += 1;
            i += 1;
        }
        let second_c_first = i;
        let second_c = cur[second_c_first];
        let mut second_cnt = 0;
        while cur[i] == second_c {
            second_cnt += 1;
            i += 1;
        }

        // dbg!(first_cnt, second_cnt);

        pows[first_cnt] += 1;
        pows[min(first_cnt, second_cnt)] += 1;

        let last_c = cur[cur.len()-1];
        let k = cur.len() - 1;
        cur.remove(k);
        cur.remove(second_c_first);
        cur.remove(0);

        filled = vec![false; 3];
        for &c in &cur {
            let n = if c == 'R' {
                0
            } else if c == 'G' {
                1
            } else {
                2
            };
            filled[n] = true;
        }
    }

    for i in 0..pows.len() {
        let pow = pows[i];
        if i==0 || i==1 {
            continue;
        }
        ans *= modpow(i, pow, p);
        ans %= p;
    }
    println!("{}", ans);
}

