fn main() {
    input! {
        n: usize,
        s: Bytes,
    }
    let len = n*3;

    let mut x = ModInt::new(n as i64);
    let mut r = M0;
    let mut g = M0;
    let mut b = M0;
    let mut rg = M0;
    let mut gb = M0;
    let mut br = M0;

    let mut ans = M1;
    for i in 0..len {
        let f = |x: &mut ModInt, ans: &mut ModInt, r: &mut ModInt, g:&mut ModInt, b: &mut ModInt, rg: &mut ModInt, gb:&mut ModInt, br:&mut ModInt|{
            if *gb == M0 {
                if *g != M0 {
                    *ans = *ans * *g;
                    *g -= M1;
                    *rg += M1;
                } else if *b != M0 {
                    *ans = *ans * *b;
                    *b -= M1;
                    *br += M1;
                } else {
                    *ans = *ans * *x;
                    *x -= M1;                    
                    *r += M1;
                }
            } else {
                *ans = *ans * *gb;
                *gb -= M1;
            }
        };
        match s[i] {
            b'R' => f(&mut x, &mut ans, &mut r, &mut g, &mut b, &mut rg, &mut gb, &mut br),
            b'G' => f(&mut x, &mut ans, &mut g, &mut b, &mut r, &mut gb, &mut br, &mut rg),
            b'B' => f(&mut x, &mut ans, &mut b, &mut r, &mut g, &mut br, &mut rg, &mut gb),
            _ => panic!(),
        }
        //println!("x{} r{} g{} b{} rg{} gb{} br{} ans{}", x, r, g, b, rg, gb, br, ans);

    }

    println!("{}", ans);
}

