        for &l in &two[s[i]] {
            sum += ord[l];
            if ord[l] >= 1 {
                idx = l;
            }
        }
        if sum >= 1 {
            ways *= sum;
            ways %= MOD;
            ord[idx] -= 1;
            ord[idx+s[i]] += 1;
            // debug!(2, ways, ord);
            continue;
        }
        ways *= ord[0];
        ord[0] -= 1;
        ord[4*s[i]] += 1;
        // debug!(1, ways, ord);
    }
    println!("{}", ways);
}

