                    if s1 == s2 {
                        continue;
                    }
                }
                dp[i][j] = max(dp[i-k-1][k] + 1, dp[i][j]);
            }
        }
    }
    let mut ans = 0;
    for j in 0..3 {
        ans = max(ans, dp[n-j-1][j]);
    }
    puts!("{}\n", ans);
